window.__RTS_NOTICIAS_CACHE={"ts": 1795029306344, "data": [{"id": "viii-centenario-de-la-pascua-de-san-francisco-de-asis-1226-2026", "title": "VIII Centenario de la Pascua de San Francisco de Asís 1226-2026 ", "author": "direccion", "year": 2026, "category": "2026", "summary": "Con la festividad de San Francisco este año 2026, concluimos el VIII Centenario de la Pascua de San Francisco. Se conmemoran los 800 años del Tránsito y fallecimiento del santo el 3 de octubre de 1226 (1226-2026), un acontecimiento celebrado por la familia franciscana y la Iglesia Católica con un Año Jubilar que se extiende del 10 de", "note": "Publicado el octubre 1, 2026", "url": "https://revistatierrasanta.com/viii-centenario-de-la-pascua-de-san-francisco-de-asis-1226-2026/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Captura-de-pantalla-2026-09-29-104104-15729180-1024x512.webp", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "via-crucis-del-papa-leon-xiv-en-el-coliseo-con-meditaciones-de-fray-francesco-patton", "title": "Via Crucis del Papa León XIV en el Coliseo con meditaciones de fray Francesco Patton", "author": "direccion", "year": 2026, "category": "2026", "summary": "Evocando el sufrimiento del mundo y en un profundo gesto de humanidad, el Papa León XIV portó la Cruz durante las catorce estaciones del Via Crucis en el Coliseo durante su primer Viernes Santo como Pontífice. Durante el recorrido se leyeron pasajes del Evangelio acompañados por las meditaciones de fray Francesco Patton (excustodio de Tierra", "note": "Publicado el abril 4, 2026", "url": "https://revistatierrasanta.com/via-crucis-del-papa-leon-xiv-en-el-coliseo-con-meditaciones-de-fray-francesco-patton/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/El-Papa-Leon-XIV-llevando-la-Cruz-durante-el-Via-Crucis-en-el-Coliseo-@Vatican-Media-1024x675.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "un-sueno-hecho-realidad-en-tierra-santa", "title": "Un sueño hecho realidad en Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Con la Misa de inauguración, presidida por el arzobispo de Tánger, fray Emilio Rocha, y concelebrada, entre otros, por el custodio de Tierra Santa, fray Francesco Ielpo, se pone fin a un sueño que inició hace más de cinco años; el sueño de la construcción de una capilla, íntegramente sufragada por donantes españoles, en el", "note": "Publicado el enero 14, 2026", "url": "https://revistatierrasanta.com/un-sueno-hecho-realidad-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/FG_14012026_HQ_24-1024x683.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "triduo-en-honor-a-san-jose-maria-rubio", "title": "Triduo en honor a San José María Rubio", "author": "direccion", "year": 2026, "category": "2026", "summary": "La Real e Ilustre Ignaciana Hermandad Sacramental de San José María Rubio en Dalias (Almería) ha celebrado del 30 de abril al 4 de mayo un solemne Triduo y fiesta en honor del primer santo almeriense. El 1 de mayo, tuvo lugar la Eucaristía, que fue presidida por el vicecomisario de Tierra Santa de la", "note": "Publicado el mayo 2, 2026", "url": "https://revistatierrasanta.com/triduo-en-honor-a-san-jose-maria-rubio/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/05/1-768x1024.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "tierra-santa-llora", "title": "Tierra Santa, llora. Oración por la paz", "author": "direccion", "year": 2026, "category": "2026", "summary": "Cuando ya pensábamos que Tierra Santa recuperaba, poco a poco, la normalidad amanecimos con la noticia de un nuevo conflicto bélico entre Israel e Irán: cierre del espacio aéreo, cancelación de peregrinaciones y un conflicto que se extiende más allá de estos dos países en conflicto. El 28 de febrero comenzaron los ataques. En esos", "note": "Publicado el marzo 6, 2026", "url": "https://revistatierrasanta.com/tierra-santa-llora/", "cover": "", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "tierra-santa-en-medio-del-conflicto", "title": "Tierra Santa en medio del conflicto", "author": "direccion", "year": 2026, "category": "2026", "summary": "Viajar a Tierra Santa no es un viaje cualquiera: es una peregrinación. Es vivir una experiencia de fe visitando lugares que han marcado no solo la historia de la humanidad, sino también la de nuestras propias almas. Pisar la misma tierra que pisó Jesús, estar en los lugares donde habló, donde lloró, donde compartió y", "note": "Publicado el marzo 9, 2026", "url": "https://revistatierrasanta.com/tierra-santa-en-medio-del-conflicto/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/1-1024x768.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "reunion-de-la-asociacion-de-amigos-de-tierra-santa-en-toledo", "title": "Reunión de la Asociación de Amigos de Tierra Santa en Toledo", "author": "direccion", "year": 2026, "category": "2026", "summary": "El domingo 22 de febrero, tuvo lugar un encuentro de la Asociación de Tierra Santa de Toledo, en la que estuvo presente el presidente de la Asociacion Española de Amigos de Tierra Santa, Rafael Martínez Casado, y el Vicecomisario de Tierra Santa, fray Luis Quintana, quien dio una conferencia sobre «El pez como signo eucarístico", "note": "Publicado el febrero 23, 2026", "url": "https://revistatierrasanta.com/reunion-de-la-asociacion-de-amigos-de-tierra-santa-en-toledo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/2-2-1024x576.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "reunion-anual-de-acompanantes-espirituales-de-tierra-santa-en-madrid", "title": "Reunión anual de acompañantes espirituales de peregrinaciones en Madrid", "author": "direccion", "year": 2026, "category": "2026", "summary": "Durante la mañana del 23 de enero se han dado cita en la Basílica de San Francisco el Grande (Madrid) numerosos sacerdotes y religiosos que acompañan espiritualmente a los peregrinos en sus viajes a Tierra Santa y a otros lugares. En el salón de Santa Isabel de Hungría, de la OFS, y tras unas palabras", "note": "Publicado el enero 24, 2026", "url": "https://revistatierrasanta.com/reunion-anual-de-acompanantes-espirituales-de-tierra-santa-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/IMG_0902-1024x768.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "presentacion-de-la-obra-sinfonica-de-kiko-arguello", "title": "Presentación de la Obra sinfónica de Kiko Argüello", "author": "direccion", "year": 2026, "category": "2026", "summary": "Tras la reunión con la Asociación de Amigos de Tierra Santa de Toledo, el 22 de febrero, los presentes se trasladaron hasta la catedral primada para asistir a la presentación de la sinfonía de Kiko Argüello —iniciador del Camino Neocatecumenal— con las obras «El sufrimiento de los inocentes» y «El Mesías». Entre los asistentes se", "note": "Publicado el febrero 25, 2026", "url": "https://revistatierrasanta.com/presentacion-de-la-obra-sinfonica-de-kiko-arguello/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/Foto-1-768x512.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "podcast-podlectio-meditaciones-en-cuaresma", "title": "Podcast «PodLectio»: meditaciones franciscanas en Cuaresma", "author": "direccion", "year": 2026, "category": "2026", "summary": "Con el miércoles de Ceniza (18 de febrero) ha dado comienzo la Cuaresma. Por este motivo, la Custodia de Tierra Santa, a través del podcast «PodLectio» en la plataforma Spotify, difunde las meditaciones diarias del Evangelio realizadas por diferentes frailes de la Custodia. ¡No te lo puedes perder!", "note": "Publicado el febrero 24, 2026", "url": "https://revistatierrasanta.com/podcast-podlectio-meditaciones-en-cuaresma/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Captura-de-pantalla-2026-03-06-a-las-13.01.38-1024x494.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "peregrinaciones-programadas-a-tierra-santa", "title": "Peregrinaciones programadas a Tierra Santa durante 2026", "author": "direccion", "year": 2026, "category": "2026", "summary": "Desde la Comisaría de Tierra Santa de la Provincia de la Inmaculada Concepcion ya se tienen programadas peregrinaciones mensuales a Tierra Santa durante todo el 2026. A continuación os dejamos todas las que hay por si queréis peregrinar a la tierra de Jesús en el que, sin duda, será «el viaje de vuestra vida». MARZO-ABRIL", "note": "Publicado el febrero 11, 2026", "url": "https://revistatierrasanta.com/peregrinaciones-programadas-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/Captura-de-pantalla-2026-02-11-a-las-15.14.07-1024x725.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "pablo-chavez-recibe-la-medalla-del-peregrino", "title": "Pablo Chaves recibe la Medalla del Peregrino", "author": "direccion", "year": 2026, "category": "2026", "summary": "El peregrino Pablo Chaves Push acudió, el pasado 5 de agosto, al Centro de Tierra Santa, ubicado en la Basílica de San Francisco el Grande (Madrid) para recibir la Medalla del Peregrino, que le otorgó la Custodia de Tierra Santa. Desde aquí queremos felicitarle con este galardón por el que la Iglesia universal le reconoce", "note": "Publicado el agosto 10, 2026", "url": "https://revistatierrasanta.com/pablo-chavez-recibe-la-medalla-del-peregrino/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/4-1024x704.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "nuevos-candelabros-para-el-santo-sepulcro", "title": "Nuevos candelabros para el Santo Sepulcro", "author": "direccion", "year": 2026, "category": "2026", "summary": "La comunidad católica (franciscanos) del Santo Sepulcro han decidido renovar los candelabros, mesa del altar, jarras, copones, etc.. de la capilla de la Tumba vacía. Para realizar dicho encargo ha sido elegido el taller español «Orfebrería Bernet», de Sevilla, para que realice vasos sagrados y diversos objetos litúrgicos.", "note": "Publicado el junio 17, 2026", "url": "https://revistatierrasanta.com/nuevos-candelabros-para-el-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/Santo-Sepulcro-sacerdote-1024x597.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-16", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "La vida es corta si no se ha vivido En una circular escrita a los provinciales franciscanos, el vicario general de la Orden, fray Elías, anunció el 4 de octubre de 1226 que durante la noche anterior había fallecido san Francisco en la Porciúncula, muy cerca de Asís (Italia). Acabaron los días de su peregrinación", "note": "Publicado el agosto 30, 2026", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-16/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/08/Captura-de-pantalla-2026-08-30-a-las-19.49.43.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-15", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Alegría desbordante, ilusión contagiosa y oración compartida. Durante el viaje apostólico del Papa León XIV a nuestro país, España ha vuelto a demostrar que es un país católico por identidad, cultura y tradición. Según datos oficiales, más de millón y medio de personas se congregaron en Madrid; y otros cientos de miles en Barcelona y", "note": "Publicado el junio 24, 2026", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-15/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/Captura-de-pantalla-2026-06-24-a-las-10.19.50-1024x872.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-14", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "El ruido de las armas se está imponiendo en nuestra sociedad; una sociedad cada vez más herida por la muerte y la violencia. El sonido de la esperanza se desvanece y la paz parece un sueño lejano imposible de alcanzar. En medio del conflicto bélico que está desangrando Oriente Medio, lo único que podemos hacer", "note": "Publicado el abril 23, 2026", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-14/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/No-87-1024x797.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-13", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Tierra Santa parece un país lejano, aunque todos los que hemos tenido el privilegio de visitarla sabemos que no es así. Es una tierra lejana geográficamente, sí, pero muy cercana a nuestro corazón, porque quien peregrina a los Santos Lugares nunca lo olvida y lo lleva guardado en un rinconcito del alma. Ahora es el", "note": "Publicado el marzo 1, 2026", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-13/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Captura-de-pantalla-2026-03-13-a-las-11.41.56-1024x665.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-12", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "En este año que ahora comienza se celebra el VIII Centenario del tránsito de san Francisco de Asís, expresión que se emplea para referirse al momento de su muerte; pero una muerte entendida no como el final sino como un “paso” de la vida terrenal a una plena junto a Dios que, cada año, celebran", "note": "Publicado el enero 9, 2026", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-12/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/Revista-1024x1021.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "nueva-web-del-centro-tierra-santa", "title": "Nueva web del Centro Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "El Centro Tierra Santa inaugura nueva web. La página www.centrotierrasanta.com es un espacio dedicado a dar a conocer la historia, la cultura y la vida de los cristianos en Tierra Santa, con contenidos están estrechamente vinculados con la vida de Jesús. Se trata de una web informativa y cultural que busca acercar Tierra Santa a los usuarios", "note": "Publicado el mayo 18, 2026", "url": "https://revistatierrasanta.com/nueva-web-del-centro-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/05/Captura-de-pantalla-2026-05-18-a-las-10.18.42-1024x523.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "misa-solemne-y-conferencia-sobre-tierra-santa-en-buenos-aires", "title": "Misa solemne y conferencia sobre Tierra Santa en Buenos Aires", "author": "direccion", "year": 2026, "category": "2026", "summary": "El próximo 12 de noviembre a las 18.30h se celebrará en la iglesia del Convento de Tierra Santa una Misa solemne y posterior conferencia sobre Tierra Santa. Bajo el título «Tierra Santa te espera y te necesita» e impartida por fray Luis Quintana, director del Centro Terra Santa, la ponencia versará sobre las necesidades actuales", "note": "Publicado el noviembre 10, 2026", "url": "https://revistatierrasanta.com/misa-solemne-y-conferencia-sobre-tierra-santa-en-buenos-aires/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/11/Captura-de-pantalla-2026-11-10-a-las-11.50.44-1024x707.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "misa-por-tierra-santa-en-la-basilica-del-monte-calvario-en-buenos-aires", "title": "Misa por Tierra Santa en la basílica del Monte Calvario en Buenos Aires", "author": "direccion", "year": 2026, "category": "2026", "summary": "A las 12 de la mañana ha tenido lugar, en la basílica de la Piedad del Monte Calvario, en Buenos Aires (Argentina) una misa por la paz, presidida por el director del Centro de Tierra Santa, fray Luis Quintana, que fue presentado por el párroco, don Fabián Baez . Durante la homilía, fray Luis Quintana,", "note": "Publicado el noviembre 15, 2026", "url": "https://revistatierrasanta.com/misa-por-tierra-santa-en-la-basilica-del-monte-calvario-en-buenos-aires/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/11/Captura-de-pantalla-2026-11-15-a-las-20.19.11-1-1024x720.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "misa-de-inauguracion-de-la-capilla-de-la-inmaculada-concepcion-en-el-campo-de-los-pastores", "title": "Misa de Inauguración de la Capilla de la Inmaculada Concepción en el Campo de los Pastores", "author": "direccion", "year": 2026, "category": "2026", "summary": "Tras la conclusión de las obras de construcción e instalación de todas las obras artísticas que forman parte del presbiterio, el 14 de enero a las 16.00h, se celebrará la misa de inauguración de la Capilla de la Inmaculada Concepción, ubicada en el Campo de los Pastores, en Beit Sahour (cerca de Belén), que estará", "note": "Publicado el enero 9, 2026", "url": "https://revistatierrasanta.com/misa-de-inauguracion-de-la-capilla-de-la-inmaculada-concepcion-en-el-campo-de-los-pastores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Foto-2-La-Inmaculada-Concepcion-con-iconos-@Custodia-de-Tierra-Santa-1024x683.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "mesa-redonda-en-el-instituto-tierra-santa-de-buenos-aires", "title": "Fray Luis Quintana en Buenos Aires (Argentina)", "author": "direccion", "year": 2026, "category": "2026", "summary": "La mañana del 12 de noviembre ha sido muy especial para los alumnos del Instituto Tierra Santa de Buenos Aires ya que han asistido a una mesa redonda sobre Tierra Santa, el nacimiento de la Custodia, las peregrinaciones y la revista Tierra Santa.La mesa redonda estuvo formada por el director del colegio, Gerardo Curía, el", "note": "Publicado el noviembre 13, 2026", "url": "https://revistatierrasanta.com/mesa-redonda-en-el-instituto-tierra-santa-de-buenos-aires/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/11/5-1024x683.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "mensaje-de-pascua-de-los-patriarcas-y-jefes-de-las-iglesias-en-jerusalen", "title": "Mensaje de Pascua de los Patriarcas y Jefes de las Iglesias en Jerusalén", "author": "direccion", "year": 2026, "category": "2026", "summary": "«¡Bendito sea el Dios y Padre de nuestro Señor Jesucristo! Por su gran misericordia nos ha hecho nacer de nuevo a una esperanza viva mediante la resurrección de Jesucristo de entre los muertos…»1 Pedro 1:3En las semanas previas a la conmemoración de la muerte y resurrección de Cristo de este año, una nueva y devastadora", "note": "Publicado el marzo 27, 2026", "url": "https://revistatierrasanta.com/mensaje-de-pascua-de-los-patriarcas-y-jefes-de-las-iglesias-en-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/PHOTO-2026-03-27-09-19-41-1024x603.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "los-franciscanos-de-tierra-santa-llegan-a-valladolid", "title": "Los franciscanos de Tierra Santa llegan a Valladolid", "author": "direccion", "year": 2026, "category": "2026", "summary": "El lunes 23 de marzo y tras el desmontaje de la exposición «Los guardianes de la Tumba de Cristo», en Salamanca, se instaló la exposición en Valladolid, en los exteriores del convento de los Padres Filipinos, con la ayuda de los hermanos de la fraternidad franciscana seglar y de la cofradía. Por la tarde, a", "note": "Publicado el marzo 24, 2026", "url": "https://revistatierrasanta.com/los-franciscanos-de-tierra-santa-llegan-a-valladolid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/PHOTO-2026-03-24-19-10-19-1024x685.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "la-resurreccion-de-cristo-un-nuevo-juicio-sobre-la-historia", "title": "La Resurrección de Cristo: un nuevo juicio sobre la historia", "author": "direccion", "year": 2026, "category": "2026", "summary": "Queridos hermanos y hermanas: Que el Señor resucitado os conceda su paz. En esta Pascua, celebrada aquí en Tierra Santa en un tiempo marcado por tanto dolor y sufrimiento, estamos llamados a experimentar la resurrección de Cristo no solo como un acontecimiento del pasado, sino como un acontecimiento que nos alcanza hoy, en esta situación", "note": "Publicado el abril 2, 2026", "url": "https://revistatierrasanta.com/la-resurreccion-de-cristo-un-nuevo-juicio-sobre-la-historia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/AssisiCustode2026_00012-1024x683.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-familia-franciscana-se-reune-en-madrid-para-celebrar-el-jubileo-del-viii-centenario-del-transito-de-san-francisco", "title": "La familia franciscana se reúne para celebrar el Jubileo del  VIII centenario del tránsito de San Francisco", "author": "direccion", "year": 2026, "category": "2026", "summary": "La familia franciscana se dio cita en Madrid, el 19 y 20 de junio, para celebrar el VIII Centenario del Tránsito de San Francisco de Asís. Convocados por la Provincia de la Inmaculada Concepción (franciscanos), junto con la Conferencia Interfranciscana de España y las distintas ramas de la familia franciscana presentes en nuestro país, miembros", "note": "Publicado el junio 22, 2026", "url": "https://revistatierrasanta.com/la-familia-franciscana-se-reune-en-madrid-para-celebrar-el-jubileo-del-viii-centenario-del-transito-de-san-francisco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/IMG_4886-3-768x1024.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-sabadell", "title": "La exposición «Los guardianes de la Tumba de Cristo» llega a Sabadell", "author": "direccion", "year": 2026, "category": "2026", "summary": "El próximo 27 de septiembre, a las 11 de la mañana, monseñor Xabier Gómez, obispo de Sant Feliu de Llobregat, presidirá la Eucaristía en la parroquia franciscana de San Francisco de Asís de Sabadell (Carrer de Pizarro 16) con la que quedará inaugurada la exposición «Los guardianes de la Tumba de Cristo», que hasta ahora", "note": "Publicado el septiembre 23, 2026", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-sabadell/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/otra-1024x768.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-barcelona", "title": "La exposición “Los guardianes de la Tumba de Cristo” llega a Barcelona", "author": "direccion", "year": 2026, "category": "2026", "summary": "El próximo 2 de junio de 2026, martes, a las 19:00 horas, Mons. Javier Vilanova, obispo auxiliar de Barcelona presidirá la Misa en el Seminario diocesano de Barcelona, con la que inaugurará la exposición fotográfica “Los Guardianes de la Tumba de Cristo”. Una vez finalizada la Misa, los asistentes se trasladarán al exterior del Seminario,", "note": "Publicado el mayo 13, 2026", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-barcelona/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/8-1024x768.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-salamanca", "title": "La exposición «Los guardianes de la Tumba de Cristo» llega a Salamanca", "author": "direccion", "year": 2026, "category": "2026", "summary": "Un recorrido visual por la vida de los frailes de Tierra Santa es lo que los visitantes podrán encontrar en la exposición «Los guardianes de la Tumba de Cristo», que ha sido inaugurada el 5 de febrero se podrá visitar en la catedral de Salamanca hasta el próximo 25 de marzo. La muestra recoge, a", "note": "Publicado el febrero 5, 2026", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-salamanca/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/78f09975-d047-438e-a398-a571c0bc3da6_21-9-aspect-ratio_1600w_0-1024x439.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-comisaria-de-tierra-santa-publica-el-libro-de-la-capilla-de-la-inmaculada-concepcion", "title": "La Inmaculada Concepción", "author": "direccion", "year": 2026, "category": "2026", "summary": "La Comisaría de Tierra Santa de la Provincia de la Inmaculada ha publicado el libro «Capilla de la Inmaculada Concepción», ubicada en el Campo de los Pastores en Beit Sahour, cerca de Belén. En el libro se analizan los pormenores de la construcción de la capilla. Desde las primeras tomas de decisiones, bocetos, inicio de", "note": "Publicado el febrero 6, 2026", "url": "https://revistatierrasanta.com/la-comisaria-de-tierra-santa-publica-el-libro-de-la-capilla-de-la-inmaculada-concepcion/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/IMG_1213-1024x768.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "intercambio-pascual-de-felicitaciones-entre-las-iglesias-ortodoxas-y-la-custodia-de-tierra-santa", "title": "Intercambio pascual de felicitaciones entre las Iglesias ortodoxas y la Custodia de Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Jerusalén ha vivido hoy una de sus tradiciones más significativas en el tiempo pascual: el intercambio de felicitaciones entre las Iglesias ortodoxas y los Fray de la Custodia de Tierra Santa. Una cita que, año tras año, renueva el espíritu de fraternidad entre las diversas comunidades cristianas presentes en los Lugares Santos y que, en", "note": "Publicado el abril 9, 2026", "url": "https://revistatierrasanta.com/intercambio-pascual-de-felicitaciones-entre-las-iglesias-ortodoxas-y-la-custodia-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/Intercambio-pascual-1024x683.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "indignacion-y-condena-sin-reservas", "title": "«Indignación y condena sin reservas»", "author": "direccion", "year": 2026, "category": "2026", "summary": "Un soldado de las Fuerzas de Defensa de Israel (FDI) profanó una imagen de Jesús crucificado en la aldea cristiana de Debl, en el sur del Líbano, golpeándolo repetidamente con un garrote en la cabeza. El incidente, publicado en redes sociales, fue reconocido por Israel, generó indignación internacional y motivó disculpas del ministro de Exteriores,", "note": "Publicado el abril 20, 2026", "url": "https://revistatierrasanta.com/indignacion-y-condena-sin-reservas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/Captura-de-pantalla-2026-04-21-a-las-13.23.52.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "inaugurada-en-barcelona-la-exposicion-los-guardianes-de-la-tumba-de-cristo", "title": "Inaugurada en Barcelona la exposición «Los guardianes de la Tumba de Cristo»", "author": "direccion", "year": 2026, "category": "2026", "summary": "El 2 de junio, el obispo auxiliar de Barcelona, monseñor Javier Vilanova, presidió la misa con la que quedó inaugurada la exposición»Los guardianes de la Tumba de Cristo» en los exteriores del Seminario Conciliar. Una vez finalizada la Eucaristía, que fue concelebrada por fray Agustí Boadas, el rector del Seminario y otros sacerdotes— los asistentes", "note": "Publicado el junio 3, 2026", "url": "https://revistatierrasanta.com/inaugurada-en-barcelona-la-exposicion-los-guardianes-de-la-tumba-de-cristo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/6-1024x768.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "impiden-la-celebracion-del-domingo-de-ramos-en-el-santo-sepulcro", "title": "Impiden la entrada al Santo Sepulcro al Patriarca Latino de Jerusalén y al Custodio de Tierra Santa para la celebración del Domingo de Ramos", "author": "direccion", "year": 2026, "category": "2026", "summary": "Comunicado conjunto del Patriarcado Latino de Jerusalén y la Custodia de Tierra Santa. Ciudad Santa de Jerusalén Domingo de Ramos, 29 de marzo de 2026 Esta mañana, la policía israelí impidió que el Patriarca Latino de Jerusalén, Su Beatitud el Cardenal Pierbattista Pizzaballa, jefe de la Iglesia Católica en Tierra Santa, junto con el Custodio", "note": "Publicado el marzo 29, 2026", "url": "https://revistatierrasanta.com/impiden-la-celebracion-del-domingo-de-ramos-en-el-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/press-realease-1_750xauto.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "hermanamiento-del-monasterio-de-santo-toribio-de-liebana-con-la-basilica-del-santo-sepulcro", "title": "Hermanamiento del monasterio de Santo Toribio de Liébana con la basílica del Santo Sepulcro", "author": "direccion", "year": 2026, "category": "2026", "summary": "En el día de la Exaltación de la Santa Cruz, el padre custodio de Tierra Santa, Francesco Ielpo, y el obispo de Santander, monseñor Arturo Ros han rubricado el hermanamiento de la basílica del Santo Sepulcro en Jerusalén y del monasterio de Santo Toribio de Liébana (Cantabria), donde se custodia el Lignum Crucis, la reliquia", "note": "Publicado el septiembre 14, 2026", "url": "https://revistatierrasanta.com/hermanamiento-del-monasterio-de-santo-toribio-de-liebana-con-la-basilica-del-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/Firma-hermanamiento-1024x578.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "hemos-vuelto-a-tierra-santa", "title": "¡Hemos vuelto a Tierra Santa!", "author": "direccion", "year": 2026, "category": "2026", "summary": "El pasado 20 de julio partía desde Madrid un grupo de 54 peregrinos rumbo a Tierra Santa encabezados por fray Luis Quintana, vicecomisario de Tierra Santa en España. Por fin se retoman las peregrinaciones con la enorme alegría e ilusión de poder vivir el quinto Evangelio en la Tierra de Jesús; en el lugar donde", "note": "Publicado el julio 27, 2026", "url": "https://revistatierrasanta.com/hemos-vuelto-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/07/757921795_3179955428880379_3268150704638381976_n-1024x768.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "he-vencido-al-mundo-nuevo-libro-de-christian-galvez", "title": "«He vencido al mundo», nuevo libro de Christian Gálvez", "author": "direccion", "year": 2026, "category": "2026", "summary": "El escritor y presentador Christian Gálvez, colaborador habitual de la Revista Tierra Santa, ha presentado, el 5 de marzo, su última novela «He vencido al mundo», publicada por Suma de tres letras (Penguin Random House Grupo Editorial). La novela es una historia sobre el sacrificio. Jesús de Nazaret está a punto de ser entregado para", "note": "Publicado el marzo 5, 2026", "url": "https://revistatierrasanta.com/he-vencido-al-mundo-nuevo-libro-de-christian-galvez/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/He-vencido-al-mundo-1024x768.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-madrid", "title": "Exposición «Los guardianes de la Tumba de Cristo» llega a Madrid", "author": "direccion", "year": 2026, "category": "2026", "summary": "La muestra «Los guardianes de la Tumba de Cristo» estará expuesta de manera simultánea en Barcelona y Madrid. Con motivo de los actos desarrollados para la celebración del 50 aniversario de la parroquia Cristo de la Paz (Madrid), el 30 de mato se va a inaugurar en los exteriores del templo la exposición «Los guardianes", "note": "Publicado el mayo 20, 2026", "url": "https://revistatierrasanta.com/exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/10-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "excavaciones-en-el-santo-sepulcro-en-la-sapienza-el-primer-volumen-del-hagia-polis-project", "title": "Excavaciones en el Santo Sepulcro: en la Sapienza el primer volumen del «Hagia Polis Project»", "author": "direccion", "year": 2026, "category": "2026", "summary": "«En estos últimos años vuestros rostros han pasado a formar parte, de algún modo, del statu quo de la basílica del Santo Sepulcro», dice, con una punta de afectuosa ironía, el Custodio de Tierra Santa, Fray Francesco Ielpo, dirigiéndose a los investigadores y jóvenes arqueólogos de Sapienza Università di Roma que, desde 2022 hasta hoy,", "note": "Publicado el septiembre 20, 2026", "url": "https://revistatierrasanta.com/excavaciones-en-el-santo-sepulcro-en-la-sapienza-el-primer-volumen-del-hagia-polis-project/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/Excavaciones-1024x683.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "encuentro-de-amigos-de-tierra-santa-en-la-basilica-de-san-francisco-el-grande", "title": "Encuentro de Amigos de Tierra Santa en la Basílica de San Francisco el Grande", "author": "direccion", "year": 2026, "category": "2026", "summary": "La jornada del sábado 24 de enero tuvo un carácter especial pues tuvo lugar el encuentro de Amigos de Tierra Santa en la Basilica de San Francisco el Grande (Madrid), que comenzó con una visita guiada —a manos de fray Pedro Gonzalez, comisario de Tierra Santa de la Provincia de la Inmaculada— del interior de", "note": "Publicado el enero 26, 2026", "url": "https://revistatierrasanta.com/encuentro-de-amigos-de-tierra-santa-en-la-basilica-de-san-francisco-el-grande/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/IMG_0971-1024x796.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "encuentro-con-el-grupo-de-apoyo-a-tierra-santa-en-ciudad-real", "title": "Encuentro con el Grupo de Apoyo a Tierra Santa en Ciudad Real", "author": "direccion", "year": 2026, "category": "2026", "summary": "El jueves, día 26, tuvo lugar una emotiva y entrañable jornada en Ciudad Real, donde el director del Centro de Tierra Santa, fray Luis Quintana, acompañado de la directora de la Revista Tierra Santa, María Díaz-Ripoll, tuvo un encuentro con el Grupo de Apoyo a Tierra Santa. La jornada comenzó a las 12 de la", "note": "Publicado el marzo 27, 2026", "url": "https://revistatierrasanta.com/encuentro-con-el-grupo-de-apoyo-a-tierra-santa-en-ciudad-real/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/4-1-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "en-yaqubiya-y-al-quniya-vuelve-la-esperanza", "title": "En Yaqubiya y Al Quniya vuelve la esperanza", "author": "direccion", "year": 2026, "category": "2026", "summary": "Campanas que vuelven a sonar. Aulas de nuevo llenas. Niños que vuelven a estudiar, a hacer amistades, a conocer el mundo y a divertirse. En una Siria que ha vivido durante demasiados años el peso de la guerra y las profundas heridas infligidas por la violencia, la pobreza y la ausencia de futuro, la reapertura", "note": "Publicado el septiembre 21, 2026", "url": "https://revistatierrasanta.com/en-yaqubiya-y-al-quniya-vuelve-la-esperanza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/WhatsApp-Image-2026-09-20-at-20.10.11-1-1024x576.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "el-organo-vuelve-a-sonar-en-la-basilica-de-san-francisco-el-grande", "title": "El órgano vuelve a sonar en la basílica de San Francisco el Grande", "author": "direccion", "year": 2026, "category": "2026", "summary": "Durante el mes de octubre y durante cuatro jueves consecutivos (8,15,22 7 29) volverá a sonar nuevamente el órgano de la basílica de San Francisco el Grande (Madrid) en el IV Ciclo de Órgano, organizado por la Obra Pía De los Santos Lugares. En esta ocasión contará con organistas de España, Alemania y Japón. Las", "note": "Publicado el octubre 7, 2026", "url": "https://revistatierrasanta.com/el-organo-vuelve-a-sonar-en-la-basilica-de-san-francisco-el-grande/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Captura-de-pantalla-2026-10-07-a-las-13.49.40-1024x513.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "el-obispo-de-terrasa-inaugura-la-exposicion-los-guardianes-de-la-tumba-de-cristo", "title": "El obispo de Terrasa inaugura la exposición «Los guardianes de la Tumba de Cristo»", "author": "direccion", "year": 2026, "category": "2026", "summary": "En la parroquia San Francisco de Asís de Sabadell, el pasado 4 de octubre, el obispo de Terrassa, monseñor Salvador Cristau, culminó las celebraciones de la familia franciscana con motivo del VIII Centenario del Tránsito de San Francisco e inauguró la exposición fotográfica «Los guardianes de la tumba de Jesús», una muestra con la que", "note": "Publicado el octubre 5, 2026", "url": "https://revistatierrasanta.com/el-obispo-de-terrasa-inaugura-la-exposicion-los-guardianes-de-la-tumba-de-cristo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/3-768x576.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "el-museo-del-prado-celebra-el-viii-centenario-del-transito-de-san-francisco-de-asis", "title": "El Museo del Prado celebra el VIII centenario del Tránsito de San Francisco de Asís", "author": "direccion", "year": 2026, "category": "2026", "summary": "El Museo del Prado se ha querido sumar a todas las celebraciones que se están realizando este año para conmemorar el VIII centenario del Tránsito de San Francisco de Asís. Para ello, van a ofrecer dos conferencias —el 12 y 19 de diciembre a las 18.30 en el auditorio del Museo— en torno a este", "note": "Publicado el noviembre 6, 2026", "url": "https://revistatierrasanta.com/el-museo-del-prado-celebra-el-viii-centenario-del-transito-de-san-francisco-de-asis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/11/Captura-de-pantalla-2026-11-06-a-las-10.54.22-1024x533.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "el-custodio-de-tierra-santa-visitara-madrid-el-proximo-9-de-mayo", "title": "El Custodio de Tierra Santa visitará Madrid el próximo 9 de mayo", "author": "direccion", "year": 2026, "category": "2026", "summary": "El Custodio de Tierra Santa, Fray Francesco Ielpo, acompañado del vicario custodial, fray Ulises Zarza, visitarán Madrid el próximo 9 de mayo. Aprovechando la ocasión, asistirán al Día del Peregrino, donde darán su testimonio sobre la actual situación en Tierra Santa. Como todos los años, la jornada tendrá lugar en el colegio San Buenaventura (C/", "note": "Publicado el abril 7, 2026", "url": "https://revistatierrasanta.com/el-custodio-de-tierra-santa-visitara-madrid-el-proximo-9-de-mayo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/Captura-de-pantalla-2026-04-10-a-las-12.53.53-768x354.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "el-custodio-de-tierra-santa-fray-francesco-ielpo-visita-madrid", "title": "El custodio de Tierra Santa, fray Francesco Ielpo, visita Madrid", "author": "direccion", "year": 2026, "category": "2026", "summary": "El custodio y el vicario custodial, fray Francesco Ielpo y fray Ulises Zarza, respetivamente, aterrizaron en Madrid el 8 de mayo. Durante sus dos días de estancia en la capital española, quisieron conocer de primera mano la labor que realiza el Centro de Tierra Santa y la Comisaría de Tierra Santa, y compartir con los", "note": "Publicado el mayo 10, 2026", "url": "https://revistatierrasanta.com/el-custodio-de-tierra-santa-fray-francesco-ielpo-visita-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/05/IMG_3635-768x497.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "el-25-de-octubre-se-celebra-maria-reina-de-palestina", "title": "El 25 de octubre se celebra María, Reina de Palestina", "author": "direccion", "year": 2026, "category": "2026", "summary": "Todos los años, el último domingo de octubre se celebra la festividad de María, Reina de Palestina. Se trata de un evento anual que representa un momento de alegría, oración y recogimiento de todos los cristianos de Tierra Santa. Frente al reto diario de ser cristiano en aquellas tierras y vivir bajo las enseñanzas de", "note": "Publicado el octubre 19, 2026", "url": "https://revistatierrasanta.com/el-25-de-octubre-se-celebra-maria-reina-de-palestina/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Maria-reina-de-Palestina-768x627.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "diez-dias-de-guerra-diez-dias-de-fraternidad-cotidiana", "title": "Diez días de guerra, diez días de fraternidad cotidiana", "author": "direccion", "year": 2026, "category": "2026", "summary": "En estos días, mientras la guerra entre Israel e Irán traía tensión y preocupación a toda la región, también los conventos de la Custodia de Tierra Santa han vivido un tiempo inusual e intenso. Las disposiciones emanadas por las autoridades impidieron a muchos trabajadores llegar a sus lugares de trabajo. Esto significó, para nuestras comunidades,", "note": "Publicado el marzo 10, 2026", "url": "https://revistatierrasanta.com/diez-dias-de-guerra-diez-dias-de-fraternidad-cotidiana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/2-1024x768.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "declaracion-sobre-las-celebraciones-de-pascua-en-el-santo-sepulcro", "title": "Declaración sobre las celebraciones de Pascua en el Santo Sepulcro", "author": "direccion", "year": 2026, "category": "2026", "summary": "La Basílica del Santo Sepulcro es un punto de referencia para más de 2.300 millones de cristianos en todo el mundo, especialmente durante las celebraciones litúrgicas de la Semana Santa y la Resurrección de Nuestro Señor Jesucristo. Debido a las limitaciones impuestas por la actual situación de guerra, por motivos de seguridad, las autoridades civiles", "note": "Publicado el marzo 26, 2026", "url": "https://revistatierrasanta.com/declaracion-sobre-las-celebraciones-de-pascua-en-el-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/SSepil-1024x461.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "declaracion-de-la-asamblea-de-ordinarios-catolicos-de-tierra-santa", "title": "Declaración de la Asamblea de Ordinarios Católicos de Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "A nuestros hijos e hijas, alumnos de las escuelas cristianas de Tierra Santa,A los sacerdotes y religiosos y religiosas a cargo de nuestras escuelas,A los directores, maestros, personal administrativo y empleados,A nuestros queridos padres,Queridos hermanos y hermanas,¡Que el Señor les dé la paz! Al finalizar agosto, la ilusión por un nuevo año escolar se siente", "note": "Publicado el agosto 26, 2026", "url": "https://revistatierrasanta.com/declaracion-de-la-asamblea-de-ordinarios-catolicos-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/08/Declaracion-Ielpo-1024x683.webp", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "de-tierra-santa-al-futuro-de-la-orden-el-ministro-general-fray-fusarelli-permanecemos-y-elegimos-estar-aqui", "title": "De Tierra Santa al futuro de la Orden. El Ministro general Fray Fusarelli: «Permanecemos y elegimos estar aquí»", "author": "direccion", "year": 2026, "category": "2026", "summary": "La visita comenzó en Jerusalén con la profesión solemne de once frailes. Luego continuó en el Monte Nebo. Posteriormente se desarrolló de nuevo en la Ciudad Santa, con el encuentro con los frailes de Judea, las Misas en el Santo Sepulcro y en el Cenáculo y la visita a la Terra Santa School. Finalmente, hubo varios encuentros con las comunidades de Galilea. El viaje a Tierra", "note": "Publicado el octubre 17, 2026", "url": "https://revistatierrasanta.com/de-tierra-santa-al-futuro-de-la-orden-el-ministro-general-fray-fusarelli-permanecemos-y-elegimos-estar-aqui/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Fusarelli-1024x512.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "da-esperanza-siembra-la-paz-apoya-a-los-cristianos-y-a-la-tierra-santa", "title": "Da esperanza, siembra la Paz: apoya a los Cristianos y a la Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Queridos hermanos y hermanas:¡Que el Señor les conceda su paz! Al acercarse la Semana Santa, nuestro corazón y nuestra mirada vuelven a la Tierra Santa, la tierra donde el Hijo de Dios dio su vida “hasta el extremo” y de la cual nació la Iglesia.También hoy, desde estos Lugares Santos, seguimos bebiendo de la fuente", "note": "Publicado el febrero 18, 2026", "url": "https://revistatierrasanta.com/da-esperanza-siembra-la-paz-apoya-a-los-cristianos-y-a-la-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Custodio-colecta-FG_29112025_HQ_64-scaled.jpg-1024x683.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "curso-on-line-de-estudio-de-las-fuentes-franciscanas", "title": "Curso on line de estudio de las fuentes franciscanas", "author": "direccion", "year": 2026, "category": "2026", "summary": "Os invitamos a participar en el curso online dedicado al estudio de las fuentes franciscanas, a través de un recorrido por los escritos de Francisco de Asís, las fuentes hagiográficas, las fuentes litúrgicas y los documentos históricos. El curso se estructura en cuatro bloques temáticos y ofrece la oportunidad de profundizar en las fuentes que nos permiten", "note": "Publicado el octubre 17, 2026", "url": "https://revistatierrasanta.com/curso-on-line-de-estudio-de-las-fuentes-franciscanas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Captura-de-pantalla-2026-10-17-a-las-0.18.27-1-768x363.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "curso-la-arqueologia-en-la-pasion-de-cristo", "title": "Curso «La Arqueología en la Pasión de Cristo»", "author": "direccion", "year": 2026, "category": "2026", "summary": "La Universidad Eclesiástica de San Dámaso (UESD) presenta el curso La Universidad San Dámaso presenta el curso «La Pasión de Cristo. La Arqueología en la Pasión de Cristo explicada a través de las 14 estaciones del Via Crucis». El curso se desarrollará en cuatro sesiones —1. Arqueología del patíbulo (La Fortaleza Antonia y “Ecce homo”),", "note": "Publicado el marzo 27, 2026", "url": "https://revistatierrasanta.com/curso-la-arqueologia-en-la-pasion-de-cristo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Captura-de-pantalla-2026-03-27-a-las-10.35.54-1024x574.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "curso-cuando-la-biblia-toca-el-suelo-historia-fe-y-arqueologia", "title": "Curso «Cuando la Biblia toca el suelo: Historia, fe y arqueología»", "author": "direccion", "year": 2026, "category": "2026", "summary": "Para todas aquellas personas interesadas en la Biblia y Tierra Santa, el 1 y 2 de junio, se celebra en El Escorial el curso «Cuando la Biblia toca el suelo: Historia, fe y arqueología», dirigido por el p. Juan Antonio Rodriguez, director de la Casa De Santiago (Jerusalén). Durante los dos días, los asistentes podrán", "note": "Publicado el mayo 28, 2026", "url": "https://revistatierrasanta.com/curso-cuando-la-biblia-toca-el-suelo-historia-fe-y-arqueologia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/05/Captura-de-pantalla-2026-05-28-a-las-19.37.40-1024x547.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "convocatoria-jubilar-de-la-familia-franciscana-2", "title": "Convocatoria jubilar de la familia franciscana", "author": "direccion", "year": 2026, "category": "2026", "summary": "En este tiempo de gracia en el que celebramos el VIII Centenario del Tránsito de nuestro padre San Francisco de Asís, queremos hacer llegar una invitación abierta, fraterna y llena de esperanza a toda la familia franciscana. La Provincia Franciscana de la Inmaculada, junto con la Interfranciscana de España, convoca a frailes, hermanas, miembros de", "note": "Publicado el junio 7, 2026", "url": "https://revistatierrasanta.com/convocatoria-jubilar-de-la-familia-franciscana-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/Captura-de-pantalla-2026-06-01-a-las-19.49.06-1024x773.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "convocatoria-jubilar-de-la-familia-franciscana", "title": "Convocatoria Jubilar de la familia franciscana", "author": "direccion", "year": 2026, "category": "2026", "summary": "En este tiempo de gracia en el que celebramos el VIII Centenario del Tránsito de nuestro padre San Francisco de Asís, queremos hacer llegar una invitación abierta, fraterna y llena de esperanza a toda la familia franciscana. La Provincia Franciscana de la Inmaculada, junto con la Interfranciscana de España, convoca a frailes, hermanas, miembros de", "note": "Publicado el abril 28, 2026", "url": "https://revistatierrasanta.com/convocatoria-jubilar-de-la-familia-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/JUBILE-6ef32de2-1024x512.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "conmemoracion-del-dia-de-los-martires-de-damasco", "title": "Conmemoración del Día de los Mártires de Damasco", "author": "direccion", "year": 2026, "category": "2026", "summary": "El 10 de julio se celebra el Día de los Mártires de Damasco, que recuerda a los 11 mártires (8 hermanos franciscanos y tres laicos) que fueron asesinados por los drusos en 1860 por no querer renunciar a su fe. Tras un largo proceso, el Papa Francisco los canonizo el 20 de octubre de 2024.", "note": "Publicado el julio 10, 2026", "url": "https://revistatierrasanta.com/conmemoracion-del-dia-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/07/Martires-de-Damasco.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "concierto-solidario-a-favor-de-las-misiones-franciscanas", "title": "Concierto solidario a favor de las misiones franciscanas", "author": "direccion", "year": 2026, "category": "2026", "summary": "El grupo de jóvenes de la Fraternidad Seglar Asís (Alcalá de Henares, Madrid), ha organizado un concierto solidario de música religiosa a favor de Misiones franciscanas: Colegio de Belén. Durante al concierto, que tuvo lugar el 21 de febrero en la parroquia madrileña de San Antonio del Retiro, se recorrió, a través de las canciones, la vida", "note": "Publicado el febrero 22, 2026", "url": "https://revistatierrasanta.com/concierto-solidario-a-favor-de-las-misiones-franciscanas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/02/2-1-1024x768.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "comunicado-del-patriarcado-latino-de-jerusalen-sobre-las-celebraciones-en-semana-santa", "title": "Comunicado del Patriarcado Latino de Jerusalén sobre las celebraciones de Semana Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Queridos hermanos y hermanas: ¡Que el Señor les dé la paz! Debido a la guerra, este año no pudimos vivir la tradicional Cuaresma en Jerusalén, con las solemnes celebraciones en el Santo Sepulcro y en los Santos Lugares de la Pasión. Si bien pudimos orar y prepararnos personalmente, sentimos la ausencia del camino comunitario hacia", "note": "Publicado el marzo 23, 2026", "url": "https://revistatierrasanta.com/comunicado-del-patriarcado-latino-de-jerusalen-sobre-las-celebraciones-en-semana-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/slide-celebrations-of-holy-week-in-jerusalem_750xauto.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "comunicado-de-la-custodia-por-el-cierre-del-santo-sepulcro", "title": "Comunicado de la Custodia por el cierre del Santo Sepulcro", "author": "direccion", "year": 2026, "category": "2026", "summary": "En los últimos días, se ha difundido mucha información sobre el cierre de la Basílica del Santo Sepulcro y las próximas celebraciones de Pascua. Al respecto, la Custodia de Tierra Santa considera oportuno ofrecer algunas aclaraciones. La comunidad de frailes franciscanos presentes en el Santo Sepulcro nunca ha cesado, día y noche, de realizar las", "note": "Publicado el marzo 21, 2026", "url": "https://revistatierrasanta.com/comunicado-de-la-custodia-por-el-cierre-del-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/ss_silvia_5_0-scaled-1-1024x461.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "comienza-la-restauracion-de-la-gruta-de-la-natividad", "title": "Comienza la restauración de la Gruta de la Natividad", "author": "direccion", "year": 2026, "category": "2026", "summary": "El Patriarcado Greco-Ortodoxo de Jerusalén y la Custodia de Tierra Santa anuncian el inminente inicio de los trabajos de restauración en la Gruta de la Natividad, el santísimo lugar venerado en toda la cristiandad como el sitio de la Encarnación. Esta iniciativa conjunta, con la fraterna cooperación del Patriarcado Apostólico Armenio Ortodoxo, se lleva a", "note": "Publicado el enero 24, 2026", "url": "https://revistatierrasanta.com/comienza-la-restauracion-de-la-gruta-de-la-natividad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/GrottaNativita1-1024x683.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "comienza-el-xiv-congreso-de-comisarios-en-paraguay", "title": "Comienza el XIV Congreso de Comisarios en Paraguay", "author": "direccion", "year": 2026, "category": "2026", "summary": "Del 16 al 20 de noviembre tendrá lugar en Asunción (Paraguay) el XIV Congreso Latinoamericano de Comisarios de Tierra Santa. Cuatro días de escucha y oración en los que habrá diferentes ponencias relacionadas con Tierra Santa: economía, peregrinaciones, el proyecto María de Nazaret, la Revista Tierra Santa. Una jornada de encuentro para adecuar líneas de", "note": "Publicado el noviembre 15, 2026", "url": "https://revistatierrasanta.com/comienza-el-xiv-congreso-de-comisarios-en-paraguay/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/11/Captura-de-pantalla-2026-11-15-a-las-20.09.17-1024x542.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "colabora-con-la-colecta-de-semana-santa", "title": "Colabora con la Colecta de Semana Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "Durante la Colecta del Viernes Santo, únase a la llamada del Custodio de Tierra Santa. Su caridad concreta es un signo de esperanza y paz para quienes testimonian el Evangelio en los Lugares de la Redención. Apoye la Colecta Pontificia por los Santos Lugares.", "note": "Publicado el marzo 24, 2026", "url": "https://revistatierrasanta.com/colabora-con-la-colecta-de-semana-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Captura-de-pantalla-2026-03-24-a-las-11.38.05-843x1024.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "cerramos-por-vacaciones", "title": "Cerramos por vacaciones", "author": "direccion", "year": 2026, "category": "2026", "summary": "Como se acerca el periodo estival, queremos informar a los lectores que tanto el Centro de Tierra Santa como la Comisaría de Tierra Santa permanecerán cerradas por vacaciones del 10 al 14 de agosto. Salvo en estas fechas, les seguiremos atendiendo en nuestras oficinas en el horario habitual de 8 a 14h. ¡Esperamos que todos", "note": "Publicado el junio 29, 2026", "url": "https://revistatierrasanta.com/cerramos-por-vacaciones/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/IMG_5106-1024x723.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "celebracion-del-viii-centenario-del-transito-de-san-francisco-de-asis", "title": "Celebración del VIII Centenario del Tránsito de san Francisco de Asís", "author": "direccion", "year": 2026, "category": "2026", "summary": "Mañana, 10 de enero a las 10.00, comienzan en la Basilica de Santa María de Los Ángeles en Porciúncila (Italia) las celebraciones del VIII centenario del Tránsito de San Francisco de Asís como última etapa de un camino emprendido en 2023 que nos ha hecho revivir los últimos años de vida terrenal del Poverello. El", "note": "Publicado el enero 9, 2026", "url": "https://revistatierrasanta.com/celebracion-del-viii-centenario-del-transito-de-san-francisco-de-asis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/Captura-de-pantalla-2026-01-09-a-las-17.22.12-1024x491.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "celebracion-de-la-natividad-de-la-virgen-maria-en-jerusalen", "title": "Celebración de la Natividad de la Virgen María en Jerusalén", "author": "direccion", "year": 2026, "category": "2026", "summary": "En el corazón de la Ciudad Vieja de Jerusalén, los frailes de la Custodia de Tierra Santa se reunieron, el 8 de septiembre, para celebrar la Natividad de la Virgen María en la Basílica de Santa Ana. La celebración comenzó con la procesión de los frailes y de los misioneros de África hasta el altar", "note": "Publicado el septiembre 8, 2026", "url": "https://revistatierrasanta.com/celebracion-de-la-natividad-de-la-virgen-maria-en-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/09/Maria-1024x684.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "carta-del-ministro-general-para-la-pascua-2026", "title": "Carta del Ministro general para la Pascua 2026", "author": "direccion", "year": 2026, "category": "2026", "summary": "Estimados hermanos y hermanas ¡Que el Señor les dé la paz! Este año se cumple el octavo centenario de la muerte de san Francisco. En este contexto, celebramos la Pascua del Señor con una conciencia renovada: Francisco, aunque murió el 3 de octubre de 1226, lejos del tiempo litúrgico pascual, experimentó su muerte como una", "note": "Publicado el marzo 31, 2026", "url": "https://revistatierrasanta.com/carta-del-ministro-general-para-la-pascua-2026/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/Captura-de-pantalla-2026-04-07-a-las-13.33.26-1024x746.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "carta-del-dicasterio-de-las-iglesias-orientales", "title": "Carta del Dicasterio de las Iglesias Orientales", "author": "direccion", "year": 2026, "category": "2026", "summary": "Querido hermano, ¡Cuánto hemos esperado que la paz pudiera finalmente devolver la vida y la esperanza a Tierra Santa! Los así llamados diálogos y acuerdos se han multiplicado, pero al mismo tiempo las armas no han callado. Se ha dicho que se ha alcanzado la paz;sin embargo, aunque los medios de comunicación hablen hoy mucho menos que antes, se sigue disparando, las personas continúan muriendo, las tierras siguen siendo disputadas y los cristianos siguen emigrando para salvar sus vidas. Incluso las escuelas, con frecuencia, no pueden contar con los profesores, porque no se les permite transitar. Sé que dirigirme a ti y a la familia cristiana de la que eres responsable es cada vez más difícil, y que las palabras", "note": "Publicado el marzo 13, 2026", "url": "https://revistatierrasanta.com/carta-del-dicasterio-de-las-iglesias-orientales/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/03/Captura-de-pantalla-2026-03-13-a-las-9.37.38-768x417.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "cancelacion-de-permisos-para-docentes-palestinos-las-escuelas-cristianas-de-jerusalen-en-huelga", "title": "Cancelación de permisos para docentes palestinos: las escuelas cristianas de Jerusalén, en huelga", "author": "direccion", "year": 2026, "category": "2026", "summary": "Autora: Cécile Lemoine /www.terresainte.net El trimestre de enero no comenzó para los 10.000 estudiantes de las escuelas cristianas de Jerusalén. Si bien el inicio del segundo semestre estaba previsto para el 10 de enero, estas 12 escuelas, entre las más prestigiosas de la ciudad santa, decidieron permanecer cerradas en protesta por la no renovación de", "note": "Publicado el enero 13, 2026", "url": "https://revistatierrasanta.com/cancelacion-de-permisos-para-docentes-palestinos-las-escuelas-cristianas-de-jerusalen-en-huelga/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/01/Colegio-1024x796.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "bendicion-del-estandarte-de-la-hermandad-franciscana-de-salamanca", "title": "Bendición del estandarte de la Hermandad Franciscana de Salamanca", "author": "direccion", "year": 2026, "category": "2026", "summary": "El 9 de mayo, al final de la celebración eucarística presidida por el arzobispo primado de España, monseñor Francisco Cerro, se bendijo un estandarte procesional, con el escudo de la Custodia Franciscana de Tierra Santa, de la Hermandad Franciscana del Santísimo Cristo de la Humildad de Salamanca. La bendición la llevó a cabo fray Francesco", "note": "Publicado el mayo 12, 2026", "url": "https://revistatierrasanta.com/bendicion-del-estandarte-de-la-hermandad-franciscana-de-salamanca/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/05/PHOTO-2026-05-09-20-11-10-1024x576.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "belen-inauguracion-del-nuevo-gimnasio-de-accion-catolica-un-testimonio-de-esperanza-en-tierra-santa", "title": "Belén, inauguración del nuevo gimnasio de Acción Católica: un testimonio de esperanza en Tierra Santa", "author": "direccion", "year": 2026, "category": "2026", "summary": "En un tiempo marcado por profundas incertidumbres y por las heridas del conflicto que atraviesa el Medio Oriente, de Belén llega una señal de renacimiento que habla de cuidado, comunidad y esperanza. De hecho, se ha inaugurado el nuevo gimnasio del centro deportivo de la Fundación Acción Católica. El nuevo centro deportivo representa una pieza", "note": "Publicado el abril 15, 2026", "url": "https://revistatierrasanta.com/belen-inauguracion-del-nuevo-gimnasio-de-accion-catolica-un-testimonio-de-esperanza-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/04/Gimnasio-1024x576.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "asuncion-de-la-virgen-la-tumba-de-maria-en-getsemani", "title": "Asunción de la Virgen, la Tumba de María en Getsemaní", "author": "direccion", "year": 2026, "category": "2026", "summary": "La Tumba de María se halla en el cauce del torrente Cedrón, en Getsemaní, unas decenas de metros al norte de la basílica de la Agonía y del huerto de los Olivos. Recibe también el nombre de iglesia de la Asunción por los cristianos ortodoxos griegos y armenios, que comparten la propiedad, y por los", "note": "Publicado el agosto 15, 2026", "url": "https://revistatierrasanta.com/asuncion-de-la-virgen-la-tumba-de-maria-en-getsemani/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/08/Timba-de-Maria-1024x512.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "asis-acogera-los-actos-centrales-de-la-conmemoracion-del-octavo-centenario-del-transito-de-san-francisco-de-asis", "title": "Asís acogerá los actos centrales de la conmemoración del octavo centenario del Tránsito de San Francisco de Asís", "author": "direccion", "year": 2026, "category": "2026", "summary": "Este año, las celebraciones en honor del santo adquieren un significado especial al conmemorarse el octavo centenario del Tránsito de San Francisco de Asís. El sábado 3 de octubre, las celebraciones se centrarán en Santa María de los Ángeles, donde se oficiará la Eucaristía solemne «Sobre el Tránsito de San Francisco», que estará presidida por", "note": "Publicado el septiembre 28, 2026", "url": "https://revistatierrasanta.com/asis-acogera-los-actos-centrales-de-la-conmemoracion-del-octavo-centenario-del-transito-de-san-francisco-de-asis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/10/Captura-de-pantalla-2026-10-01-a-las-16.48.17-1024x665.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "ahora-puedes-hacer-el-via-matris-on-line", "title": "Ahora, puedes hacer el Via Matris on line", "author": "direccion", "year": 2026, "category": "2026", "summary": "Francisco J. Pereira, peregrino y participante en el encuentro de Chipiona (Cádiz), se interesó por los iconos de la Capilla de la Inmaculada del Campo de los Pastores en Beit Sahour, y del Via Matris que conformaban. Tanto es así, que decidió crear una página web en la que el usuario pudiese hacer el recorrido", "note": "Publicado el junio 21, 2026", "url": "https://revistatierrasanta.com/ahora-puedes-hacer-el-via-matris-on-line/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2026/06/Captura-de-pantalla-2026-06-19-a-las-19.09.18-1024x666.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "ya-esta-disponible-el-calendario-2026", "title": "Ya está disponible el calendario 2026", "author": "direccion", "year": 2025, "category": "2025", "summary": "Por tercer año consecutivo, la Revista Tierra Santa regala a sus suscriptores el Calendario anual. En esta ocasión, la portada del Calendario de 2025 la hemos dedicado al 800 aniversario del Tránsito de San Francisco de Asís. Las fotografías que aparecen en el calendario hacen un recorrido por diferentes lugares que visitan los peregrinos durante", "note": "Publicado el diciembre 9, 2025", "url": "https://revistatierrasanta.com/ya-esta-disponible-el-calendario-2026/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/12/Captura-de-pantalla-2025-12-09-a-las-9.30.41-1024x795.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "volvemos-a-tierra-santa", "title": "¡Volvemos a Tierra Santa!", "author": "direccion", "year": 2025, "category": "2025", "summary": "El lunes, 31 de marzo, un grupo de 44 peregrinos españoles viajarán a Tierra Santa, donde asistirán, el 5 de abril, a la bendición de las capillas españolas de Guadalupe y de la Inmaculada Concepción, que estará presidida por el arzobispo de Toledo, monseñor Francisco Cerro. Ya están abiertas las fechas para futuros viajes a", "note": "Publicado el marzo 30, 2025", "url": "https://revistatierrasanta.com/volvemos-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/355a6dea-4bc4-49c5-861a-13ecca626159-806x1024.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "visita-del-custodio-y-el-director-del-centro-de-tierra-santa-al-consulado-de-espana-en-jerusalen", "title": "Visita del custodio y el director del Centro de Tierra Santa al consulado general de España en Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "El padre custodio, Francesco Ielpo, y el director del Centro de Tierra Santa, fray Luis Quintana, han visitado, el 25 de noviembre, el consulado español en Jerusalén, donde se han reunido con el cónsul general y cónsul adjunto, Javier Gutiérrez, y Luis Pertusa, respectivamente. Durante el encuentro se han tratado diversos asuntos. Entre ellos, se", "note": "Publicado el noviembre 25, 2025", "url": "https://revistatierrasanta.com/visita-del-custodio-y-el-director-del-centro-de-tierra-santa-al-consulado-de-espana-en-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Fray-Luis-Custodio-y-consul-1024x461.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "via-crucis-peregrinacion-por-la-via-dolorosa-de-jerusalen", "title": "Via Crucis. Peregrinación por la Vía Dolorosa de Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "Según recoge el prefacio del libro, «el Vía Crucis es una devocionales típicamente franciscana y nace del deseo de ayudar a los fieles a recorrer ese camino doloroso y al mismo tiempo luminoso que va desde el lugar de la condena de Jesús hasta el lugar de su crucifixión, muerte, sepultura y resurrección. El Vía", "note": "Publicado el marzo 13, 2025", "url": "https://revistatierrasanta.com/via-crucis-peregrinacion-por-la-via-dolorosa-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Captura-de-pantalla-2025-03-13-a-las-19.16.49.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "una-bandera-de-espana-para-el-campo-de-los-pastores", "title": "La Orden de los Reales Tercios dona una Bandera de España para el Campo de los Pastores", "author": "direccion", "year": 2025, "category": "2025", "summary": "El domingo, 29 de junio, una representación de la Orden Cívico Militar de los Reales Tercios de España, encabezada por don Luis Guichot, presidente de la Orden, donaron una Bandera de España, bordada, que irá destinada a la Capilla de la Inmaculada Concepción, «la capilla española», ubicada en el Campo de los Pastores (Beit Sahour).", "note": "Publicado el julio 4, 2025", "url": "https://revistatierrasanta.com/una-bandera-de-espana-para-el-campo-de-los-pastores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/IMG-20250629-WA0006-1024x473.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "un-trozo-de-tierra-santa-en-toledo-una-exposicion-exhibe-la-vida-de-los-guardianes-de-la-tumba-de-cristo", "title": "Un trozo de Tierra Santa en Toledo: una exposición exhibe la vida de los guardianes de la Tumba de Cristo", "author": "direccion", "year": 2025, "category": "2025", "summary": "El arzobispo de Toledo, Francisco Cerro, ha inaugurado este miércoles ‘Guardianes de la tumba de Cristo: 800 años de los franciscanos en Tierra Santa’, una exposición compuesta por 30 fotografías de Thomas Coex, de la agencia AFP, realizadas entre los años 2018 y 2019. La muestra recoge momentos de oración, trabajo y descanso de la comunidad", "note": "Publicado el mayo 6, 2025", "url": "https://revistatierrasanta.com/un-trozo-de-tierra-santa-en-toledo-una-exposicion-exhibe-la-vida-de-los-guardianes-de-la-tumba-de-cristo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Exposicion-Toledo-1024x512.webp", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "todos-somos-voluntarios", "title": "«Todos somos voluntarios»", "author": "direccion", "year": 2025, "category": "2025", "summary": "Bajo el lema «Todos somos voluntarios, la Orden de Caballería del Santo Sepulcro de Jerusalén ha organizado una fiesta para recaudar fondos, que se celebrará el 18 de junio a las 20.00h. en los jardines de la Casa de Brasil.", "note": "Publicado el junio 2, 2025", "url": "https://revistatierrasanta.com/todos-somos-voluntarios/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/WhatsApp-Image-2025-06-02-at-08.51.01.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "tierra-santa-nos-necesita-ayudemosla", "title": "Tierra Santa nos necesita, ¡ayudémosla!", "author": "direccion", "year": 2025, "category": "2025", "summary": "Un año más, coincidiendo con la llegada de la Semana Santa, con su carga emocional de celebraciones religiosas, nuestra mente y corazón vuelan al unísono hacia una tierra que a lo largo de la historia se ha convertido en un referente para el Cristianismo mundial. Porque, en cierto modo, Tierra Santa es la patria espiritual de toda persona cristiana.", "note": "Publicado el abril 14, 2025", "url": "https://revistatierrasanta.com/tierra-santa-nos-necesita-ayudemosla/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/Captura-de-pantalla-2025-04-14-a-las-13.53.09-1024x578.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "tierra-santa-celebra-la-ascension-del-senor", "title": "Tierra Santa celebra la Ascension del Señor", "author": "direccion", "year": 2025, "category": "2025", "summary": "Las celebraciones empezaron a primera hora de la tarde con el ingreso solemne del vicario custodial, fray Ibrahim Faltas, a la capilla de la Ascensión. Le siguió el rezo de las Vísperas tras el cual, los frailes en procesión entonaron las letanías De los Santos, dando tres vueltas alrededor del edículo de los cruzados. Por", "note": "Publicado el mayo 30, 2025", "url": "https://revistatierrasanta.com/tierra-santa-celebra-la-ascension-del-senor/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/GPO08645-1536x1024-1-1024x683.webp", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "suena-en-jerusalen-el-organo-de-belen-tras-ocho-siglos-silenciado", "title": "Suena en Jerusalén el órgano de Belén tras ocho siglos silenciado", "author": "direccion", "year": 2025, "category": "2025", "summary": "Por primera vez hemos podido escuchar en Jerusalén el sonido original de los tubos de un órgano medieval. Con el canto litúrgico del siglo XI «Benedicamus Domino Flos filias», el musicólogo español, David Catalunya —del Instituto Complutense de Ciencias Musicales— hizo sonar los tubos del órgano de Belén, lo que permitió recrear el miso sonido", "note": "Publicado el septiembre 10, 2025", "url": "https://revistatierrasanta.com/suena-en-jerusalen-el-organo-de-belen-tras-ocho-siglos-silenciado/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/09/Foto-1-1024x683.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "san-antonio-patron-de-la-custodia-de-tierra-santa", "title": "San Antonio, patrón de la Custodia de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "La Familia franciscana junto a toda la Iglesia celebra hoy, 13 de junio, la fiesta de San Antonio, este «hijo predilecto» de San Francisco, que vivió en plenitud la ley de Dios y en el que podemos descubrir precisamente la lógica evangélica, pues supo vivir la fe desde la sencillez, la humildad y la pobreza", "note": "Publicado el junio 13, 2025", "url": "https://revistatierrasanta.com/san-antonio-patron-de-la-custodia-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/San-Anton-1024x512.webp", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "recorremos-el-camino-hacia-la-pascua-eterna", "title": "Recorremos el camino hacia la Pascua eterna", "author": "direccion", "year": 2025, "category": "2025", "summary": "Estimadas amigas, estimados amigos, El Señor les de la paz. En estos nueve años he tenido el placer y el privilegio de poder felicitacitarles por la Pascua desde los lugares que recuerdan la resurrección de Jesús y sus primeras apariciones: el Sepulcro vacío y las capillas cercanas que recuerdan el encuentro con su madre, con", "note": "Publicado el abril 20, 2025", "url": "https://revistatierrasanta.com/recorremos-el-camino-hacia-la-pascua-eterna/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/Captura-de-pantalla-2025-04-20-a-las-19.16.34-1024x574.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "quieres-acompanar-al-papa-en-la-oracion-ecumenica-en-nicea", "title": "¿Quieres acompañar al Papa en la oración ecuménica en Nicea?", "author": "direccion", "year": 2025, "category": "2025", "summary": "Para conmemorar el 1700 aniversario del I Concilio de Nicea, el primer concilio ecuménico del cristianismo — en el que, entre otros, se redactó el Credo como declaración fundamental de la fe cristiana que afirma la creencia en la Trinidad (un sólo Dios en tres personas: Padre, Hijo y Espíritu Santo) y la naturaleza divina", "note": "Publicado el noviembre 19, 2025", "url": "https://revistatierrasanta.com/quieres-acompanar-al-papa-en-la-oracion-ecumenica-en-nicea/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Captura-de-pantalla-2025-11-19-a-las-10.29.57-799x1024.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "proxima-peregrinacion-a-tierra-santa-de-la-hospitalidad-jesus-de-nazaret", "title": "Próxima peregrinación a Tierra Santa de la Hospitalidad Jesús de Nazaret", "author": "direccion", "year": 2025, "category": "2025", "summary": "Autora: Ana Palacio El pasado 2 de abril, después de este periodo marcado por el sufrimiento de tantos, volví a Tierra Santa como un nuevo despertar. Como soplo de aire fresco.Para los peregrinos. Como Tierra que Dios escogió para venir al mundo, es un lugar privilegiado de esperanza. En estos días he podido volver a", "note": "Publicado el abril 9, 2025", "url": "https://revistatierrasanta.com/proxima-peregrinacion-a-tierra-santa-de-la-hospitalidad-jesus-de-nazaret/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/WhatsApp-Image-2025-04-09-at-22.18.01-copia-2-1024x768.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "presentacion-del-libro-el-santo-sepulcro-cerca-de-casa-en-madrid", "title": "Presentación del libro «El Santo Sepulcro cerca de casa» en Madrid", "author": "direccion", "year": 2025, "category": "2025", "summary": "En la capilla de la Purísima de la Basílica de San Francisco el Grande (Madrid) se ha presentado, el 17 de octubre, el libro “El Santo Sepulcro cerca de casa: Peregrinos en San Girolano, Reggio Emilia y en Santo Stefano, Bolonia, Region Emilia, Italia”. El presidente de la Asociación de Amigos de Tierra Santa, Rafael", "note": "Publicado el octubre 19, 2025", "url": "https://revistatierrasanta.com/presentacion-del-libro-el-santo-sepulcro-cerca-de-casa-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/Foto-4-1024x576.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "presentacion-del-libro-el-santo-sepulcro-cerca-de-casa-en-la-basilica-de-san-francisco-el-grande", "title": "Presentación del libro «El Santo Sepulcro cerca de casa» en la Basílica de San Francisco el Grande", "author": "direccion", "year": 2025, "category": "2025", "summary": "El próximo 17 de octubre a las 19.00h se presentará en la Basílica de San Francisco el Grande (C/ San Buenaventura, 1. Madrid) el libro «El Santo Sepulcro cerca de casa: Peregrinos en San Girolamo, Reggio Emilia y en Santa Stefano, Bolonia, Región Emilia, Italia», escrito por María Cristina Rattighieri Johnson, que trabajó en Tierra", "note": "Publicado el agosto 29, 2025", "url": "https://revistatierrasanta.com/presentacion-del-libro-el-santo-sepulcro-cerca-de-casa-en-la-basilica-de-san-francisco-el-grande/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/08/IMG_8082.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "pentecostes-shavout-la-fiesta-de-las-semanas", "title": "Pentecostés, Shavout, la Fiesta de las Semanas", "author": "direccion", "year": 2025, "category": "2025", "summary": "A los cincuenta días de celebrar la Pascua, tanto judíos como cristianos tenemos otra fiesta muy especial. Los cristianos lo llamamos «Pentecostés», haciendo referencia a los cincuenta días a partir del día de la Resurrección de Cristo, y en ella celebramos que el Espíritu Santo descendió sobre los apóstoles en el Cenáculo (Jerusalén), dando origen así a la", "note": "Publicado el junio 5, 2025", "url": "https://revistatierrasanta.com/pentecostes-shavout-la-fiesta-de-las-semanas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/image-2-3e038f41-1024x512.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "oracion-por-los-difuntos-en-damasco", "title": "Oración por los difuntos en Lattakia", "author": "direccion", "year": 2025, "category": "2025", "summary": "El atentado suicida en la iglesia ortodoxa griega de Mar Elias en Damasco (Siria), el 22 de junio, en el que un hombre se inmoló entre los fieles mientras se celebraba una Misa, ha dejado 22 muertos y 63 heridos. Un día más tarde, fieles y representantes de todos los cristianos se unieron en una", "note": "Publicado el junio 23, 2025", "url": "https://revistatierrasanta.com/oracion-por-los-difuntos-en-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Fadi-1.1-1024x768.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-9", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Después de 15 meses de bombardeos, destrucción y sufrimiento, el 15 de enero nos despertábamos con la noticia del alto el fuego firmado entre Israel y Hamás. La tregua, que entró en vigor cuatro días después del anuncio, significa la esperanza de que la vida puede comenzar de nuevo en una tierra duramente castigada por", "note": "Publicado el marzo 7, 2025", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-9/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Captura-de-pantalla-2025-03-07-a-las-11.57.18-796x1024.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-7", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "La Navidad es una época del año que siempre tiene sentimientos encontrados: o te encanta o estás deseando que pase, depende de las vivencias y los sentimientos de cada uno de nosotros. He de reconocer que, cuando empieza a faltar “gente” en la mesa, personas importantes en nuestra vida que ya no están con nosotros,", "note": "Publicado el enero 4, 2025", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-7/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/Captura-de-pantalla-2025-01-16-a-las-13.36.07-870x1024.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-11", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "En este número de la revista, hemos querido conmemorar el 1700 aniversario del primer Concilio de Nicea, un acontecimiento que marcó la historia del cristianismo y sentó las bases de la fe católica tal y como la conocemos hoy en día. También recogemos los trabajos de excavación arqueológica que, a pesar del conflicto, se están llevando", "note": "Publicado el octubre 29, 2025", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-11/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/Captura-de-pantalla-2025-10-29-a-las-13.24.03.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-10", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Jerusalén ha sido testigo de la entrada solemne del nuevo custodio de Tierra Santa. La procesión salía de la Puerta de Jaffa —como es tradición para los mandatarios— en dirección al convento de San Salvador, donde recibió el sello del cargo de manos de su antecesor, fray Francesco Patton, prestó juramento sobre el Evangelio y", "note": "Publicado el septiembre 4, 2025", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-10/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/09/Captura-de-pantalla-2025-09-04-a-las-22.23.14-1024x936.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "nuevo-gobierno-de-la-custodia-de-tierra-santa", "title": "Nuevo gobierno de la Custodia de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "El 27 de julio se abrió oficialmente el Capítulo de la Custodia de Tierra Santa. La jornada comenzó con la celebración de la Santa Misa en la iglesia del Convento de San Salvador (Jerusalén), presidida por el ministro general fray Massimo Fussarelli. Al finalizar, los frailes caminaron en procesión hasta el aula capitular, donde se", "note": "Publicado el julio 28, 2025", "url": "https://revistatierrasanta.com/nuevo-gobierno-de-la-custodia-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/Nuevo-Gobierno-Custodia-1024x683.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "nuevas-ordenaciones-sacerdotales-en-la-custodia-de-tierra-santa", "title": "Nuevas ordenaciones sacerdotales en la Custodia de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "En la solemnidad de los Santos Pedro y Pablo, la Iglesia de San Salvador en Jerusalén acogió, el 29 de junio, la ordenación sacerdotal de tres frailes menores de la Custodia de Tierra Santa: fray Saturnin Sadrac, fray Rito José Mendoza y fray Juan David Rodríguez. En presencia del Patriarca de Jerusalén, cardenal Pierbattista Pizzaballa, numerosos hermanos", "note": "Publicado el junio 30, 2025", "url": "https://revistatierrasanta.com/nuevas-ordenaciones-sacerdotales-en-la-custodia-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/1-1024x683.webp", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "misa-votiva-por-el-beato-federico-jansoone-patrono-de-los-comisarios-de-tierra-santa", "title": "Misa votiva por el beato Federico Jansoone, patrono de los Comisarios de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "La jornada de hoy del V Congreso Internacional de Comisarios de Tierra Santa ha comenzado con una misa votiva por el beato Federico Jansoone, patrono de los Comisarios de Tierra Santa. En la Homilía, el Vicario Custodial, fray Ulise Zarza, ha recordado que «Dios llama a través de encuentros concretos, personas que ponen en nuestro", "note": "Publicado el noviembre 20, 2025", "url": "https://revistatierrasanta.com/misa-votiva-por-el-beato-federico-jansoone-patrono-de-los-comisarios-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Captura-de-pantalla-2025-11-20-a-las-13.34.40-1024x847.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "mensaje-de-solidaridad-y-cercania-con-los-patriarcados-ortodoxos-latino-y-griego-del-custodio-de-tierra-santa-fray-francesco-ielpo", "title": "Mensaje de solidaridad y cercanía con los Patriarcados Ortodoxos Latino y Griego, del custodio de Tierra Santa, fray Francesco Ielpo", "author": "direccion", "year": 2025, "category": "2025", "summary": "Las recientes noticias sobre las evacuaciones forzadas de la ciudad de Gaza y la progresiva ocupación militar de la ciudad, con dramáticas consecuencias en términos de víctimas inocentes y crisis humanitaria, han despertado en nuestros corazones un profundo dolor y cercanía hacia los cristianos y toda la población de Gaza, quienes durante casi dos años", "note": "Publicado el septiembre 2, 2025", "url": "https://revistatierrasanta.com/mensaje-de-solidaridad-y-cercania-con-los-patriarcados-ortodoxos-latino-y-griego-del-custodio-de-tierra-santa-fray-francesco-ielpo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/09/540594221_1097110259150108_5443553444652983282_n-1024x683.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "los-reyes-visitan-el-real-monasterio-de-santa-maria-de-guadalupe", "title": "Los Reyes visitan el Real Monasterio de Santa María de Guadalupe", "author": "direccion", "year": 2025, "category": "2025", "summary": "Los Reyes de España, don Felipe y doña Letizia, han visitado, el 28 de mayo, el Real Monasterio de Santa Maria de Guadalupe, en el marco de la visita institucional a la Puebla y Villa, realizada por los reyes con motivo del X aniversario de la proclamación del rey Felipe IV. Los monarcas fueron recibidos", "note": "Publicado el mayo 30, 2025", "url": "https://revistatierrasanta.com/los-reyes-visitan-el-real-monasterio-de-santa-maria-de-guadalupe/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Reyes-Guadalupe-1024x512.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "los-comisarios-de-tierra-santa-visitan-el-campo-de-los-pastores", "title": "Los comisarios de Tierra Santa visitan el Campo de los Pastores", "author": "direccion", "year": 2025, "category": "2025", "summary": "Hoy sábado, el grupo de comisarios han celebrado la Eucaristía en el Campo de los Pastores, en Beit Sahour (Belén) y han visitado la Capilla española de la Inmaculada Concepción que será inaugurada el próximo 14 de enero a las 16.00h. por el custodio, fray Francesco Patton. Si queréis asistir a la peregrinación, ¡todavía quedan", "note": "Publicado el noviembre 22, 2025", "url": "https://revistatierrasanta.com/los-comisarios-de-tierra-santa-visitan-el-campo-de-los-pastores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/WhatsApp-Image-2025-11-22-at-09.22.32-1024x461.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "leon-xiv-nuevo-pontifice", "title": "León XIV, nuevo Papa para la Iglesia", "author": "direccion", "year": 2025, "category": "2025", "summary": "8 de mayo. Eran las 18.07 de la tarde cuando desde la chimenea del tejado de la Capilla Sixtina comenzó a salir humo blanco y las campanas comenzaron a repicar. ¡Habemus Papam! La plaza de San Pedro se llenó de júbilo a la espera de saber cuál de los 133 cardenales reunidos en el Cónclave", "note": "Publicado el mayo 9, 2025", "url": "https://revistatierrasanta.com/leon-xiv-nuevo-pontifice/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Leon-XIV-768x568.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-vida-de-los-franciscanos-de-la-custodia-llega-a-chipiona", "title": "La vida de los franciscanos de la Custodia llega a Chipiona", "author": "direccion", "year": 2025, "category": "2025", "summary": "A las 20.00 de la tarde en la localidad gaditana de Chipiona se ha celebrado una Eucaristía en el Santuario Nuestra Señora de Regla, presidida por el Comisario de Tierra Santa de la Provincia de la Inmaculada Concepción, fray Pedro González, previa a la inauguración de la exposición «Los guardianes de la Tumba de Cristo»,", "note": "Publicado el julio 23, 2025", "url": "https://revistatierrasanta.com/la-vida-de-los-franciscanos-de-la-custodia-llega-a-chipiona/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/2-1024x576.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "la-tierra-santa-en-el-corazon-del-papa-francisco", "title": "La Tierra Santa en el corazón del Papa Francisco", "author": "direccion", "year": 2025, "category": "2025", "summary": "Autora: Marinella Bandini/CTS Con profundo dolor y emoción, la Custodia de Tierra Santa lamenta el fallecimiento de Su Santidad el Papa Francisco, Obispo de Roma y Sucesor de San Pedro. En este momento de dolor, nos unimos a toda la Iglesia católica y a las personas de buena voluntad de todo el mundo para ofrecer", "note": "Publicado el abril 21, 2025", "url": "https://revistatierrasanta.com/la-tierra-santa-en-el-corazon-del-papa-francisco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/NA_140525_4285-scaled-1-1024x791.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-musica-celebra-a-san-francisco-de-asis-en-madrid", "title": "¡La música celebra a San Francisco de Asís en Madrid!", "author": "direccion", "year": 2025, "category": "2025", "summary": "La Familia Franciscana de Madrid abre las puertas de emblemáticos lugares de espiritualidad para ofrecernos un ciclo de seis conciertos gratuitos con motivo de la conmemoración de diversos centenarios vinculados a la figura de San Francisco de Asís, ¡incluyendo el 8º centenario del «Laude delle creature»! Descubre y revaloriza el legado musical franciscano y obras", "note": "Publicado el mayo 7, 2025", "url": "https://revistatierrasanta.com/la-musica-celebra-a-san-francisco-de-asis-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Captura-de-pantalla-2025-05-07-a-las-17.03.00.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-luz-que-nace-de-la-fragilidad", "title": "La luz que nace de la fragilidad", "author": "direccion", "year": 2025, "category": "2025", "summary": "Desde la Gruta de la Natividad, en Belén, el custodio de Tierra Santa, Francesco Ielpo, nos manda su felicitación de Navidad https://www.youtube.com/watch?v=iqwCvbx7Of4", "note": "Publicado el diciembre 19, 2025", "url": "https://revistatierrasanta.com/la-luz-que-nace-de-la-fragilidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/12/Captura-de-pantalla-2025-12-19-a-las-13.05.28-1024x647.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-familia-franciscana-celebra-el-viii-aniversario-del-cantico-de-las-criaturas", "title": "La familia franciscana celebra el 800 aniversario del Cántico de las criaturas", "author": "direccion", "year": 2025, "category": "2025", "summary": "El santuario de San Damián, ubicado en la ciudad italiana de Asís, ha sido el escenario escogido para celebrar la inauguración del octavo centenario de la composición del Cántico de las criaturas, oda compuesta por Francisco de Asís en 1225 como alabanza a la Creación. En la Bula del Jubileo de 2025, el Papa Francisco", "note": "Publicado el enero 12, 2025", "url": "https://revistatierrasanta.com/la-familia-franciscana-celebra-el-viii-aniversario-del-cantico-de-las-criaturas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/san-francisco-de-asis-1024x683.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-murcia", "title": "La exposición «Los guardianes de la Tumba de Cristo» llega a Murcia", "author": "direccion", "year": 2025, "category": "2025", "summary": "El próximo martes 11 de febrero de 2025, a las 16:30 horas, se inaugurará en los exteriores del Instituto Teológico de Murcia (ITM) la exposición fotográfica «Los Guardianes de la Tumba de Cristo». Esta muestra, patrocinada por la Universidad Católica de Murcia (UCAM) y el ITM, ofrece una visión íntima de la vida cotidiana de", "note": "Publicado el febrero 6, 2025", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-murcia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/02/INVITACION-2-1-6a7e0f44-1024x512.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-la-localidad-gaditana-de-chipiona", "title": "La exposición «Los guardianes de la Tumba de Cristo» llega a la localidad gaditana de Chipiona", "author": "direccion", "year": 2025, "category": "2025", "summary": "El próximo martes 22 de julio de 2025, a las 20:30 horas (a las 20:00 se celebrará la Eucaristía presidida por el obispo de la diócesis de Asidonia-Jerez, monseñor José Rico Pavés, se inaugurará en los exteriores del Santuario de Nuestra Señora de Regla la exposición fotográfica “Los Guardianes de la Tumba de Cristo”, donde se podrán ver 12", "note": "Publicado el julio 16, 2025", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-la-localidad-gaditana-de-chipiona/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/exp.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-ceuta-2", "title": "La exposición “Los guardianes de la Tumba de Cristo” llega a Ceuta", "author": "direccion", "year": 2025, "category": "2025", "summary": "Desde Onteniente (Valencia) la exposición “Los guardianes de la Tumba de Cristo” será trasladada a Ceuta, donde se inaugurará el próximo 2 de diciembre a las 18.00h. El claustro de la Casa de San Antonio del Monte Hacho acogerá esta exposición — que recoge, a través de 30 fotografías la vida de los frailes menores en", "note": "Publicado el noviembre 20, 2025", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-ceuta-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/WhatsApp-Image-2025-11-20-at-12.54.45-1024x536.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-ceuta", "title": "La exposición «Los guardianes de la Tumba de Cristo» llega a Ceuta", "author": "direccion", "year": 2025, "category": "2025", "summary": "Desde Onteniente (Valencia) la exposición “Los guardianes de la Tumba de Cristo” será trasladada a Ceuta, donde se inaugurará el próximo 2 de diciembre a las 18.00h. El claustro de la Casa de San Antonio del Monte Hacho acogerá esta exposición — que recoge, a través de 30 fotografías la vida de los frailes menores en", "note": "Publicado el octubre 16, 2025", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-cristo-llega-a-ceuta/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/WhatsApp-Image-2025-10-03-at-12.34.08-1024x461.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-exposicion-de-los-franciscanos-de-la-custodia-llega-a-la-localidad-valenciana-de-onteniente", "title": "La exposición de los franciscanos de la Custodia llega a la localidad valenciana de Onteniente", "author": "direccion", "year": 2025, "category": "2025", "summary": "El arzobispo de Valencia, monseñor Enrique Benavent, inaugurará, el 3 de octubre a las 10.30h, la exposición fotográfica «Los guardianes de la Tumba de Cristo» con la celebración de una Eucaristía en el colegio franciscano de la Concepción de Onteniente (Valencia). Una vez finalizada la misa, los asistentes se trasladarán al patio del colegio, donde", "note": "Publicado el agosto 26, 2025", "url": "https://revistatierrasanta.com/la-exposicion-de-los-franciscanos-de-la-custodia-llega-a-la-localidad-valenciana-de-onteniente/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/08/3-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "la-custodia-de-tierra-santa-con-las-victimas-del-ataque-a-la-iglesia-de-la-sagrada-familia-en-gaza", "title": "Atacada la Sagrada Familia, la única iglesia católica en Gaza", "author": "direccion", "year": 2025, "category": "2025", "summary": "La Custodia de Tierra Santa expresa su profundo dolor y más sincera cercanía a la comunidad cristiana de Gaza, afectada hoy por un ataque del ejército israelí que alcanzó la parroquia de la Sagrada Familia, causando tres víctimas y alrededor de diez heridos, todos civiles inocentes, entre ellos el párroco, padre Gabriel Romanelli, y el", "note": "Publicado el julio 18, 2025", "url": "https://revistatierrasanta.com/la-custodia-de-tierra-santa-con-las-victimas-del-ataque-a-la-iglesia-de-la-sagrada-familia-en-gaza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/images.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-comisaria-y-el-centro-de-tierra-santa-se-hacen-presentes-en-fitur", "title": "La Comisaría y el Centro de Tierra Santa se hacen presentes en FITUR", "author": "direccion", "year": 2025, "category": "2025", "summary": "Un año más, la Comisaría y el Centro de Tierra Santa han querido estar presentes en la Feria Internacional de Turismo. Durante la jornada del día 23 de enero han recorrido diferentes stands, entre los que se encontraban Egipto, destino al que próximamente anunciaremos peregrinaciones, Palestina, donde hemos tenido la ocasión de reunirnos con dos", "note": "Publicado el enero 23, 2025", "url": "https://revistatierrasanta.com/la-comisaria-y-el-centro-de-tierra-santa-se-hacen-presentes-en-fitur/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/cambiar-1024x585.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-cena-la-pones-tu-2025", "title": "La cena la pones tú-2025", "author": "direccion", "year": 2025, "category": "2025", "summary": "Con la llegada de la Navidad, nos preparamos para recordar el nacimiento de Jesús en un pobre pesebre en la ciudad de Belén; una festividad que en muchas ocasiones pierde su sentido religioso. Para las familias cristianas de Tierra Santa la situación este año es especialmente crítica. Aunque los recientes acuerdos de paz nos traen", "note": "Publicado el noviembre 25, 2025", "url": "https://revistatierrasanta.com/la-cena-la-pones-tu-2025/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/alepo4-7bd9fa65-1024x512.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-celebracion-en-el-cenaculo-inicia-oficialmente-el-v-congreso-internacional-de-comisarios", "title": "La celebración en el Cenáculo inicia oficialmente el V Congreso Internacional de Comisarios de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Hoy ha comenzado el V Congreso Internacional de los Comisarios de Tierra Santa, bajo el lema «Embajadores de Paz, escuchar, sostener y anunciar Tierra Santa». En él se han dado cita 75 los comisarios, acompañados por colaboradores y periodistas, provenientes de 38 países de todos los continentes. Una representación verdaderamente global, signo vivo de la universalidad de", "note": "Publicado el noviembre 19, 2025", "url": "https://revistatierrasanta.com/la-celebracion-en-el-cenaculo-inicia-oficialmente-el-v-congreso-internacional-de-comisarios/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_251119_WEB_00066-1024x683.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "jornada-fraterna-en-el-dia-del-peregrino", "title": "Fraternidad y alegría en el Día del Peregrino", "author": "direccion", "year": 2025, "category": "2025", "summary": "El 24 de mayo se celebró, en las instalaciones del colegio San Buenaventura (Madrid), el tradicional Día del Peregrino. Un encuentro que gira en torno a la promoción de las peregrinaciones y al que acuden, año tras año, peregrinos, amigos y simpatizantes de Tierra Santa y que da a conocer la obra de que la", "note": "Publicado el mayo 25, 2025", "url": "https://revistatierrasanta.com/jornada-fraterna-en-el-dia-del-peregrino/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/IMG_4539-1024x686.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "jerusalen-da-la-bienvenida-al-nuevo-custodio-de-tierra-santa", "title": "Jerusalén da la bienvenida al nuevo Custodio de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Tres ingresos solemnes —Jerusalén, Santo Sepulcro y Belén— marcan el inicio del oficio del nuevo custodio de Tierra Santa. La entrada solemne comenzó, el 21 de julio, en la Puerta de Jaffa, en la que el nuevo custodio, fray Francesco Ielpo, a través de la cual el Custodio ingresó en la Ciudad Vieja de Jerusalén", "note": "Publicado el julio 21, 2025", "url": "https://revistatierrasanta.com/jerusalen-da-la-bienvenida-al-nuevo-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/FG_21072025_WEB_262-1536x1024-1.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "inscribete-en-el-curso-el-misterio-de-la-creacion-desde-la-vision-del-cantico-de-las-criaturas", "title": "Inscríbete en el curso «El misterio de la Creación desde la visión del Cántico de las Criaturas»", "author": "direccion", "year": 2025, "category": "2025", "summary": "Con motivo del 800 aniversario del Cántico de las Criaturas el Instituto Teológico de Murcia OFM organiza dentro de su cátedra del Legado Franciscano, el curso «El misterio de la Creación desde la visión del Cántico de las Criaturas». Al curso puede inscribirse cualquier persona interesada en ampliar sus conocimientos sobre la aportación intelectual y", "note": "Publicado el marzo 4, 2025", "url": "https://revistatierrasanta.com/inscribete-en-el-curso-el-misterio-de-la-creacion-desde-la-vision-del-cantico-de-las-criaturas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Captura-de-pantalla-2025-03-05-a-las-17.07.45-1024x588.png", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "ingreso-solemne-en-el-santo-sepulcro", "title": "Ingreso solemne en el Santo Sepulcro", "author": "direccion", "year": 2025, "category": "2025", "summary": "Al día siguiente, el 25 de julio, el nuevo Custodio salió del convento de San Salvador para hacer la entrada solemne en el Santo Sepulcro, corazón de la cristiandad. Lugar central para la fe cristiana, vinculado a la crucifixión, sepultura y resurrección de Jesús. Ante las puertas cerradas, Francesco Ielpo fue recibido por los superiores", "note": "Publicado el julio 26, 2025", "url": "https://revistatierrasanta.com/ingreso-solemne-en-el-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/Custodio-llaves-del-Sepulcro-1024x683.webp", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "ingreso-solemne-del-nuevo-custodio-en-el-cenaculo", "title": "Ingreso solemne del nuevo Custodio en el Cenáculo", "author": "direccion", "year": 2025, "category": "2025", "summary": "Tres días más tarde del ingreso del nuevo Custodio por la Puerta de Jaffa, fray Francesco Ielpo hizo la entrada solemne en el Cenáculo, sobre el Monte Sión. El custodio salió del convento de San Salvador, acompañado por una veintena de franciscanos y del visitador general, fray Alojzy Sławomir. El ingreso en el Cenáculo tiene", "note": "Publicado el julio 25, 2025", "url": "https://revistatierrasanta.com/ingreso-solemne-del-nuevo-custodio-en-el-cenaculo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/Custodio-en-el-Cenaculo--1024x683.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "inauguracion-de-la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-onteniente-valencia", "title": "Inauguración de la exposición «Los guardianes de la Tumba de Cristo» en Onteniente (Valencia)", "author": "direccion", "year": 2025, "category": "2025", "summary": "El arzobispo de Valencia, monseñor Enrique Benavent, ha inaugurado oficialmente la exposición «Los guardianes de la Tumba de Cristo», que recoge, a través de 30 fotografías la vida de los frailes menores en su misión de custodiar los Santos Lugares y servir a las comunidades cristianas en Tierra Santa. A las 10.30 de la mañana,", "note": "Publicado el octubre 3, 2025", "url": "https://revistatierrasanta.com/inauguracion-de-la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-onteniente-valencia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/WhatsApp5-1024x461.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "inauguracion-de-la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-ceuta", "title": "Inauguración de la exposición «Los guardianes de la Tumba de Cristo» en Ceuta", "author": "direccion", "year": 2025, "category": "2025", "summary": "Hoy, 2 de diciembre se ha inaugurado en la ciudad autónoma de Ceuta la exposición «Los guardianes de la Tumba de Cristo», que podrá ser disfrutada por los visitantes hasta finales del mes de enero. La Eucaristía ha sido presidida por el arzobispo franciscano de Tánger, monseñor Emilio Rocha, y concelebrada por el Vicario General", "note": "Publicado el diciembre 2, 2025", "url": "https://revistatierrasanta.com/inauguracion-de-la-exposicion-los-guardianes-de-la-tumba-de-cristo-en-ceuta/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/12/2-1-1024x768.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "fray-francesco-ielpo-y-el-centro-de-tierra-santa-espana", "title": "Fray Francesco Ielpo y el Centro de Tierra Santa (España)", "author": "direccion", "year": 2025, "category": "2025", "summary": "El 14 de julio el director del Centro Tierra Santa y vicecomisario de Tierra Santa de la Provincia de la Inmaculada Concepción, fray Luis Quintana, visitó la delegación de Tierra Santa en Roma. Allí, pudo encontrarse con fray Francesco Patton, actual custodio de Tierra Santa (hasta que termine su oficio el próximo 21 de julio)", "note": "Publicado el julio 15, 2025", "url": "https://revistatierrasanta.com/fray-francesco-ielpo-y-el-centro-de-tierra-santa-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/IMG20250715134503-1024x462.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "fray-francesco-ielpo-ofm-las-primeras-palabras-del-nuevo-custodio-de-tierra-santa", "title": "Fray Francesco Ielpo, OFM: las primeras palabras del nuevo Custodio de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Nos reunimos con Fray Francesco Ielpo, nombrado el martes 24 de junio por Su Santidad el Papa León XIV Custodio de Tierra Santa. Lo escuchamos al teléfono, aún inmerso en sus compromisos como Visitador General de las Provincias Franciscanas de Campania, Basilicata y Calabria, antes de comenzar su servicio a tiempo completo como Custodio de", "note": "Publicado el junio 26, 2025", "url": "https://revistatierrasanta.com/fray-francesco-ielpo-ofm-las-primeras-palabras-del-nuevo-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/2.webp", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "fray-francesco-ielpo-nuevo-custodio-de-tierra-santa", "title": "Fray Francesco Ielpo, nuevo Custodio de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "El Papa León XIV ha ratificado la elección del Fray Francesco Ielpo, O.F.M., como nuevo Custodio de Tierra Santa y Guardián del Monte Sión, designado por el Ministro General de la Orden de los Hermanos Menores y el órgano decisorio de la misma. Fray Ielpo, italiano nació en Lauria, provincia de Potenza (Italia) hace 55", "note": "Publicado el junio 24, 2025", "url": "https://revistatierrasanta.com/fray-francesco-ielpo-nuevo-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Ielpo-1024x572.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "fray-fadi-visita-espana", "title": "Fray Fadi Azar visita España", "author": "direccion", "year": 2025, "category": "2025", "summary": "Fray Fadi Azar, párroco De la Iglesia del Sagrado Corazón de Jesús, ubicada en Lattakia (Siria) ha visitado nuestro país. Durante su estancia, fray Fadi se trasladó hasta Valencia para agradecer a la Asociación Calmaah de Xativa (Valencia) el envío de un contenedor de alimentos, que llegó a suelo sirio el pasado 28 de abril.", "note": "Publicado el mayo 26, 2025", "url": "https://revistatierrasanta.com/fray-fadi-visita-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Fadi-2-1024x461.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "fray-fadi-azar-visita-espana", "title": "Misa por la paz en Madrid", "author": "direccion", "year": 2025, "category": "2025", "summary": "Fray Fadi Azar visitará próximamente nuestro país. Entre los actos a los que tiene previsto asistir, fray Fadi acudirá el 31 de octubre a las 19.00h a la parroquia Cristo de la Paz (C/ Portalegre, 8. Madrid) donde presidirá una Misa por la paz y dará su testimonio como franciscano (de origen palestino-jordano) de Tierra", "note": "Publicado el octubre 24, 2025", "url": "https://revistatierrasanta.com/fray-fadi-azar-visita-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/PHOTO-2025-10-23-17-12-38-768x1024.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "fray-fadi-azar-franciscano-en-alepo-siria-oficia-una-misa-por-la-paz-y-da-testimonio-de-la-situacion-actual-en-siria", "title": "Fray Fadi Azar preside una Misa por la Paz y da testimonio de la situación actual en Siria", "author": "direccion", "year": 2025, "category": "2025", "summary": "En la parroquia Cristo de Paz hemos tenido ocasión de compartir una Eucaristía por la Paz y escuchar el testimonio de fray Fadi Azar —franciscano de la Custodia de Tierra Santa, nacido en Jordania con orígenes palestinos y destinado actualmente en Alepo— sobre la difícil situación de los cristianos que viven en Siria. La Misa,", "note": "Publicado el noviembre 1, 2025", "url": "https://revistatierrasanta.com/fray-fadi-azar-franciscano-en-alepo-siria-oficia-una-misa-por-la-paz-y-da-testimonio-de-la-situacion-actual-en-siria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/IMG_8486-1.heic", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "firma-del-acuerdo-de-paz-para-gaza", "title": "Firma del acuerdo de paz para Gaza", "author": "direccion", "year": 2025, "category": "2025", "summary": "La localidad egipcia de Sharm el Sheij ha sido el lugar escogido, el 13 de octubre, para la firma del acuerdo de paz para Gaza tras dos años de conflicto entre Israel y Hamás. A la rúbrica del acuerdo asistieron los representantes de los países que mediaron el acuerdo de paz en Gaza —Estados Unidos,", "note": "Publicado el octubre 14, 2025", "url": "https://revistatierrasanta.com/firma-del-acuerdo-de-paz-para-gaza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/Middle_East_Peace_Summit_-_1760379202-1024x657.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "finalizan-las-obras-estructurales-del-terra-sancta-museum-arthistory", "title": "Finalizan las obras estructurales del Terra Sancta Museum Art&History", "author": "direccion", "year": 2025, "category": "2025", "summary": "Han concluido las obras estructurales del Terra Sancta Museum Art&History y con este motivo, el 12 de mayo, el cónsul de España en Jerusalen, Javier Gutiérrez, como una amplia delegación de cónsules, jefes de misión y miembros de cooperación acudieron a reafirmar el carácter universal de Jerusalen y a conocer, en primicia, las primeras salas", "note": "Publicado el mayo 20, 2025", "url": "https://revistatierrasanta.com/finalizan-las-obras-estructurales-del-terra-sancta-museum-arthistory/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Consul-Espana-1-1024x683.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "fiesta-de-los-martires-franciscanos-de-tierra-santa", "title": "Fiesta de los Mártires franciscanos de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Por primera vez se va a celebrar, el 10 de julio, la festividad de los Mártires de Damasco— entre ellos, siete españoles— desde que fuesen canonizados por el Papa Francisco, el pasado 20 de octubre https://revistatierrasanta.com/canonizacion-de-los-martires-franciscanos-de-damasco/ En la segunda mitad del siglo XIX, un grupo de franciscanos frailes menores de la comunidad de Damasco, dieron", "note": "Publicado el julio 8, 2025", "url": "https://revistatierrasanta.com/fiesta-de-los-martires-franciscanos-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/IMG_5607-1024x756.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "fallece-el-papa-francisco", "title": "Fallece el Papa Francisco", "author": "direccion", "year": 2025, "category": "2025", "summary": "El cardenal Kevin Joseph Farrell, Camarlengo de la Santa Romana Iglesia, ha anunciado con tristeza el fallecimiento del Papa Francisco, con estas palabras: «Queridos hermanos y hermanas, con profundo dolor debo anunciar el fallecimiento de nuestro Santo Padre Francisco. A las 7:35 de esta mañana, el Obispo de Roma, Francisco, regresó a la casa del", "note": "Publicado el abril 21, 2025", "url": "https://revistatierrasanta.com/fallece-el-papa-francisco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/NA_140525_4273-scaled-1-1024x683.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "entrada-solemne-del-custodio-de-tierra-santa-en-nazaret", "title": "Entrada solemne del custodio de Tierra Santa en Nazaret", "author": "direccion", "year": 2025, "category": "2025", "summary": "La entrada solemne del custodio en Nazaret, el sábado 9 de agosto, sigue a las de las últimas semanas en Jerusalén y Belén, completando así el ciclo de entradas solemnes en las tres basílicas jubilares de Tierra Santa: el Santo Sepulcro, la Natividad y la Anunciación. Y son un signo del vínculo entre el nuevo", "note": "Publicado el agosto 10, 2025", "url": "https://revistatierrasanta.com/entrada-solemne-del-custodio-de-tierra-santa-en-nazaret/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/08/Foto-4-1024x683.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "encuentro-anual-de-animadores-de-tierra-santa-en-madrid", "title": "Encuentro anual de acompañantes espirituales de Tierra Santa en Madrid", "author": "direccion", "year": 2025, "category": "2025", "summary": "Durante la mañana del 24 de enero se han dado cita en la Basílica de San Francisco el Grande (Madrid) numerosos sacerdotes y religiosos que acompañan espiritualmente a los peregrinos en sus viajes a Tierra Santa y a otros lugares. La reunión anual —que se realiza desde hace más de 40 años— ha tenido esta", "note": "Publicado el enero 24, 2025", "url": "https://revistatierrasanta.com/encuentro-anual-de-animadores-de-tierra-santa-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/62c94b96-cbec-41be-871c-24db3ca03ec6-1024x576.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "embajadores-de-paz-tercera-jornada", "title": "Embajadores de Paz: tercera jornada", "author": "direccion", "year": 2025, "category": "2025", "summary": "La tercera jornada fue un día intenso en el corazón de Tierra Santa, marcado por testimonios vibrantes, escucha atenta e historias que hablan de la valentía cotidiana.Desde la misión educativa del Centro Helen Keller hasta los desafíos de vivienda que enfrentan los cristianos en Jerusalén, desde las voces de las familias de Belén hasta la", "note": "Publicado el noviembre 21, 2025", "url": "https://revistatierrasanta.com/embajadores-de-paz-tercera-jornada/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_21112025_WEB_01-3-1024x683.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "embajadores-de-paz-segunda-jornada", "title": "Embajadores de Paz: segunda jornada", "author": "direccion", "year": 2025, "category": "2025", "summary": "El segundo día del congreso «Embajadores de Paz» se centró en el silencio de la escucha y la presencia acogedora: la importancia de seguir orado, estudiando, preservando y dando testimonio, para que la esperanza siga teniendo cabida en esta tierra marcada por la historia. Una invitación a cada uno de nosotros a ser guardianes de", "note": "Publicado el noviembre 20, 2025", "url": "https://revistatierrasanta.com/embajadores-de-paz-segunda-jornada/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_20112025_WEB_11-1024x683.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "embajadores-de-paz-quinta-jornada", "title": "Embajadores de Paz: quinta jornada", "author": "direccion", "year": 2025, "category": "2025", "summary": "En la Solemnidad de Cristo Rey, la comunidad de Jerusalén se reunió en el Monasterio de San Salvador para una celebración extraordinaria: niños de catecismo, jóvenes scouts, familias, peregrinos y religiosos se unieron para abrazar el mensaje de la verdadera realeza, no en el poder, sino en el servicio y el amor.Durante la misa, el", "note": "Publicado el noviembre 23, 2025", "url": "https://revistatierrasanta.com/embajadores-de-paz-quinta-jornada/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_23112025_WEB_49-1024x683.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "embajadores-de-paz-cuarta-jornada", "title": "Embajadores de paz: cuarta jornada", "author": "direccion", "year": 2025, "category": "2025", "summary": "En Belén, el viaje de los Comisarios de Tierra Santa continúa, junto a las piedras vivas que custodian la fe en una tierra herida pero resiliente.Desde la celebración en el Campo de los Pastores hasta la visita al Colegio Tierra Santa, y el encuentro con los niños del Hogar Niño Dios y la comunidad de", "note": "Publicado el noviembre 22, 2025", "url": "https://revistatierrasanta.com/embajadores-de-paz-cuarta-jornada/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_22112025_WEB_01-2-768x512.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "embajadores-de-paz", "title": "Embajadores de Paz: encuentro internacional de Comisarios en Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "Bajo el lema «Embajadores de Paz: escuchar, apoyar y anunciar Tierra Santa, ha comenzado, esta mañana en Jerusalén, el V Congreso Internacional de los Comisarios de Tierra Santa. Un encuentro mundial de oración, diálogo y reflexión compartida para renovar la misión de ser Embajadores de la Paz. Desde los testimonios procedentes de Gaza, Chipre y", "note": "Publicado el noviembre 19, 2025", "url": "https://revistatierrasanta.com/embajadores-de-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_251119_WEB_00023-1024x683.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "embajadores-de-la-paz-sexta-jornada", "title": "Embajadores de la Paz: sexta jornada", "author": "direccion", "year": 2025, "category": "2025", "summary": "La mañana comenzó con un enfoque en la comunicación, corazón de la misión de los franciscanos en Tierra Santa, compartiendo lugares, rostros y espiritualidad con los peregrinos y el mundo entero a través de herramientas cada vez más actualizadas y accesibles.El P. Alberto Pari presentó los canales oficiales de la Custodia, los retos futuros y", "note": "Publicado el noviembre 24, 2025", "url": "https://revistatierrasanta.com/embajadores-de-la-paz-sexta-jornada/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/24.4-1024x683.webp", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "el-pez-signo-de-cristo", "title": "El pez, signo de Cristo", "author": "direccion", "year": 2025, "category": "2025", "summary": "Con frecuencia vemos representado a Jesucristo como el Buen Pastor o el Cordero de Dios, y la simbología del rebaño que sigue al pastor o de la oveja perdida que es encontrada por él, nos habla de nuestra relación con Dios. Así podemos recordar hermosos textos del Antiguo Testamento en los que los profetas nos", "note": "Publicado el junio 12, 2025", "url": "https://revistatierrasanta.com/el-pez-signo-de-cristo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Captura-de-pantalla-2025-06-12-a-las-18.35.00.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "el-patriarca-latino-de-jerusalen-visita-gaza-tras-el-ataque-a-la-iglesia-de-la-sagrada-familia", "title": "El Patriarca Latino de Jerusalén visita Gaza tras el ataque a la Iglesia de la Sagrada Familia", "author": "direccion", "year": 2025, "category": "2025", "summary": "Histórica visita solidaria de Su Beatitud el cardenal Pierbattista Pizzaballa, Patriarca Latino de Jerusalén, y Su Beatitud el Patriarca Teófilos III, Patriarcado Ortodoxo griego, a la Iglesia de la Sagrada Familia en Gaza. Ambos Patriarcas también han visitado a aquellos que se refugian en iglesias e instalaciones médicas cercanas, ofreciendo consuelo y extendiendo palabras de", "note": "Publicado el julio 18, 2025", "url": "https://revistatierrasanta.com/el-patriarca-latino-de-jerusalen-visita-gaza-tras-el-ataque-a-la-iglesia-de-la-sagrada-familia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/4-1024x682.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "el-patriarca-latino-de-jerusalen-invitado-al-capitulo", "title": "El Patriarca Latino de Jerusalén, invitado al Capítulo custodial", "author": "direccion", "year": 2025, "category": "2025", "summary": "El 1 de agosto, el Capítulo daba la bienvenida a un invitado de excepción, el Patriarca Latino de Jerusalén, cardenal Pierbattista Pizzaballa, que fue presentado por el presidente del Capítulo, fray Alojzy Warot. El Patriarca quiso mostrar su profunda cercanía y gratitud a la Custodia de Tierra Santa por su testimonio y servicio a la", "note": "Publicado el agosto 1, 2025", "url": "https://revistatierrasanta.com/el-patriarca-latino-de-jerusalen-invitado-al-capitulo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/08/FG_01082025_WEB_10-1024x683.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "el-papa-leon-xvi-visita-iznik-antigua-nicea", "title": "El Papa León XVI visita Iznik, antigua Nicea, con motivo de 1.700 aniversario del Concilio", "author": "direccion", "year": 2025, "category": "2025", "summary": "En su primer viaje apostólico, el Papa León XIV ha peregrinado hasta İznik, la antigua Nicea, para recordar el Concilio que hace 1.700 años definió la naturaleza divina de Jesucristo. Ante representantes de diversas confesiones cristianas, el Pontífice ha advertido sobre las tergiversaciones actuales de la figura de Cristo y exhorta a la fraternidad universal.", "note": "Publicado el noviembre 29, 2025", "url": "https://revistatierrasanta.com/el-papa-leon-xvi-visita-iznik-antigua-nicea/", "cover": "", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "el-padre-francesco-patton-y-sus-nueve-anos-como-custodio-de-tierra-santa", "title": "El padre Francesco Patton y sus nueve años como custodio de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Con el nombramiento del padre Ielpo concluyó la misión del Fraile Menor en Oriente Medio. “Para quedarse aquí hay que amar esta tierra, ser resiliente y entender que pertenecer a esta tierra no es una maldición sino una vocación”. Con el nombramiento del padre Francesco Ielpo como nuevo Custodio de Tierra Santa, finalizó este 24 de", "note": "Publicado el julio 1, 2025", "url": "https://revistatierrasanta.com/el-padre-francesco-patton-y-sus-nueve-anos-como-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/cq5dam.thumbnail.cropped.750.422-a723a544-1024x512.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "el-libro-le-ofrecieron-un-trozo-de-pez-asado-se-presenta-en-madrid", "title": "El libro “Le ofrecieron un trozo de pez asado”, de fray Luis Quintana, se presenta en Madrid", "author": "direccion", "year": 2025, "category": "2025", "summary": "Cerca de un centenar de personas se dieron cita, el 25 de junio, en la parroquia Cristo de la Paz (Madrid) para asistir a la presentación del libro “Le ofrecieron un trozo de pez asado”, escrito por fray Luis Quintana, director del Centro Tierra Santa y representante legal del Custodio en España. Religiosas, peregrinos, parroquianos,", "note": "Publicado el junio 26, 2025", "url": "https://revistatierrasanta.com/el-libro-le-ofrecieron-un-trozo-de-pez-asado-se-presenta-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/FL7-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "el-ecce-homo-regresa-a-la-flagelacion", "title": "El Ecce Homo regresa a la Iglesia de la Flagelación en Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "Tras dos años de ausencia, el 13 de septiembre de 2025 la imagen de madera del Cristo flagelado volvió a su lugar en el Santuario de la Flagelación en Jerusalén. La estatua, donada hace tiempo por una comunidad de Barcelona, fue gravemente dañada el 2 de febrero de 2023, cuando un extremista irrumpió en la", "note": "Publicado el septiembre 17, 2025", "url": "https://revistatierrasanta.com/el-ecce-homo-regresa-a-la-flagelacion/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/09/GPO03183.jpg-1024x683.webp", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "el-custodio-de-tierra-santa-nos-pide-rezar-insistentemente-por-la-paz", "title": "El Custodio de Tierra Santa nos pide rezar insistentemente por la paz", "author": "direccion", "year": 2025, "category": "2025", "summary": "El Custodio de Tierra Santa, fray Francesco Patton, nos envía un mensaje sobre la situación actual en Tierra Santa y nos pide rezar insistentemente por la paz. «Desde Jerusalén, desde Tierra Santa quisiera enviar a todos un llamamiento, una invitación a orar por la paz. Sabemos que la oración es, por así decirlo, la única", "note": "Publicado el junio 17, 2025", "url": "https://revistatierrasanta.com/el-custodio-de-tierra-santa-nos-pide-rezar-insistentemente-por-la-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Captura-de-pantalla-2025-06-17-a-las-13.32.16-768x760.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "el-altar-de-la-capilla-del-calvario-regresa-al-santo-sepulcro", "title": "El altar de la capilla del Calvario regresa al Santo Sepulcro", "author": "direccion", "year": 2025, "category": "2025", "summary": "El 8 de abril de 2024 el altar de la Capilla Latina de la Crucifixión, en el Calvario, dentro de la Basílica del Santo Sepulcro fue retirado y ahora, el 12 de febrero de este año, ha regresado a su lugar, completamente restaurado, limpiado y pulido por la familia Savi de Roma. Un regalo ofrecido", "note": "Publicado el febrero 14, 2025", "url": "https://revistatierrasanta.com/el-altar-de-la-capilla-del-calvario-regresa-al-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Captura-de-pantalla-2025-03-03-a-las-14.50.53-1024x724.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "donde-esta-betfage-y-que-labor-desempena-su-santuario", "title": "¿Dónde está Betfagé y qué labor desempeña su santuario?", "author": "direccion", "year": 2025, "category": "2025", "summary": "Autor: Fray Silvio de la Fuente, OFM Betfagé es un pequeño y pintoresco santuario, situado en la ladera oriental del Monte de los Olivos, cerca de Betania y a unos 720 metros sobre el nivel del mar, aunque se encuentra en las cercanías de Jerusalén. Este lugar es de gran importancia bíblica, pues desde aquí comenzó la", "note": "Publicado el marzo 11, 2025", "url": "https://revistatierrasanta.com/donde-esta-betfage-y-que-labor-desempena-su-santuario/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Betfage-1-768x512.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "desde-1969-en-nazaret-hasta-el-encuentro-de-2025-los-congresos-internacionales-de-los-comisarios-de-tierra-santa", "title": "Desde 1969 en Nazaret hasta el encuentro de 2025: los Congresos Internacionales de los Comisarios de Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Cincuenta años de encuentros, de escucha y de reflexión.Los Congresos Internacionales de los Comisarios de Tierra Santa representan un hilo de oro que une a los frailes franciscanos dispersos por el mundo con la Custodia de Tierra Santa, corazón palpitante de la presencia cristiana en los Lugares de Jesús.Desde el primer congreso en 1969 hasta", "note": "Publicado el noviembre 7, 2025", "url": "https://revistatierrasanta.com/desde-1969-en-nazaret-hasta-el-encuentro-de-2025-los-congresos-internacionales-de-los-comisarios-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Logo-Comisarios-1024x377.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "descubren-el-huerto-junto-al-sepulcro-mencionado-en-el-evangelio-de-san-juan", "title": "Descubren el huerto junto al Sepulcro mencionado en el Evangelio de San Juan", "author": "direccion", "year": 2025, "category": "2025", "summary": "Según publica la Fundación Tierra Santa, las excavaciones del Santo Sepulcro lideradas por la profesora Francesca Romana Stasolla , de la Universidad de La Sapienza, habrían añadido un nuevo y relevante descubrimiento arqueológico estrechamente relacionado con la figura de Cristo, el huerto junto al Santo Sepulcro mencionado en el Evangeliode San Juan: «Tomaron el cuerpo de", "note": "Publicado el abril 3, 2025", "url": "https://revistatierrasanta.com/descubren-el-huerto-junto-al-sepulcro-mencionado-en-el-evangelio-de-san-juan/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/Huerto-Tierra-Santa-1024x600-1-768x450.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "declaracion-sobre-el-ataque-perpetrado-en-la-ciudad-cristiana-de-taybeh", "title": "Declaración sobre el ataque perpetrado en la ciudad cristiana de Taybeh", "author": "direccion", "year": 2025, "category": "2025", "summary": "29 de julio de 2025Nosotros, los Patriarcas y Jefes de las Iglesias de Jerusalén, expresamos nuestra profunda preocupación y nuestra firme condena tras otro violento ataque contra la ciudad cristiana de Taybeh, en Cisjordania. Varios vehículos fueron incendiados y se pintaron grafitis de odio, un claro acto de intimidación dirigido contra una comunidad pacífica y", "note": "Publicado el julio 29, 2025", "url": "https://revistatierrasanta.com/declaracion-sobre-el-ataque-perpetrado-en-la-ciudad-cristiana-de-taybeh/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/Captura-de-pantalla-2025-07-29-a-las-14.20.58-1024x362.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "declaracion-de-los-ordinarios-catolicos-sobre-el-anuncio-de-alto-el-fuego-en-gaza-tras15-meses-de-guerra", "title": "Declaración de los Ordinarios Católicos sobre el anuncio de alto el fuego en Gaza tras 15 meses de guerra", "author": "direccion", "year": 2025, "category": "2025", "summary": "«Qué hermosos son sobre los montes, los pies del mensajero que anuncia la paz, que trae la buena nueva» (Is. 52,7) Los Ordinarios Católicos de Tierra Santa acogen con satisfacción el anuncio del alto el fuego en Gaza, que tiene como objetivo poner fin a las hostilidades en Gaza, devolver a los rehenes israelíes y", "note": "Publicado el enero 16, 2025", "url": "https://revistatierrasanta.com/declaracion-de-los-ordinarios-catolicos-sobre-el-anuncio-de-alto-el-fuego-en-gaza-tras15-meses-de-guerra/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/IMG_0881.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "curso-de-arqueologia-de-la-devocion-la-ciudad-santa-de-jerusalen", "title": "Curso de Arqueología de la Devoción. La ciudad Santa de Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "La doctora Cayetana H. Johnson, arqueóloga especializada en Arqueología Bíblica y profesora de la Universidad Eclesiástica de San Dámaso, va a impartir el «Curso de Arqueología de la Devoción. La ciudad Santa de Jerusalén», que se desarrollará los días 3, 10 y 17 de junio de 18.00 a 19.00 de la tarde en la Universidad", "note": "Publicado el mayo 13, 2025", "url": "https://revistatierrasanta.com/curso-de-arqueologia-de-la-devocion-la-ciudad-santa-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Jerusalen.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "cristianos-del-mundo-es-tiempo-de-regresar-a-la-iglesia-madre-os-esperamos", "title": "Cristianos del mundo, es tiempo de regresar a la Iglesia Madre. ¡Os esperamos!", "author": "direccion", "year": 2025, "category": "2025", "summary": "Desde Jerusalén, el custodio de Tierra Santa, fray Francesco Ielpo, y el patriarca Latino, cardenal Pierbattista Pizzaballa, han realizado una invitación muyespecial: Es tiempo de regresar a las raíces de la fe, de vivir una experiencia de peregrinación única y de ser presencia y apoyo para la comunidad cristiana local. Podéis ver el video accediendo", "note": "Publicado el noviembre 13, 2025", "url": "https://revistatierrasanta.com/cristianos-del-mundo-es-tiempo-de-regresar-a-la-iglesia-madre-os-esperamos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Captura-de-pantalla-2025-11-13-a-las-18.15.07-1024x571.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "continuan-las-labores-de-restauracion-del-pavimento-del-santo-sepulcro", "title": "Continúan las labores de restauración del pavimento del Santo Sepulcro", "author": "direccion", "year": 2025, "category": "2025", "summary": "En las salas de la Curia Custodial de San Salvador en Jerusalén, se ha celebrado una conferencia de prensa dedicada al estado de avance de las obras de renovación del pavimento de la Basílica del Santo Sepulcro. En el encuentro participaron representantes de las diferentes comunidades cristianas que comparten la custodia del Santuario, entre ellos", "note": "Publicado el octubre 22, 2025", "url": "https://revistatierrasanta.com/continuan-las-labores-de-restauracion-del-pavimento-del-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/FG_21102025_WEB_23-1536x1024-8cfab624-1024x512.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "consagracion-de-la-capilla-croata-en-el-campo-de-los-pastores", "title": "Consagración de la capilla croata en el Campo de los Pastores", "author": "direccion", "year": 2025, "category": "2025", "summary": "Numerosas personalidades diplomáticas y del gobierno croata, entre ellos Gordan Grlić, ministro de Asuntos Exteriores y Europeos y enviado especial del primer ministro de la República de Croacia, se dieron cita el 1 de marzo en el Campo de los Pastores, en Beit Sahour (Belén) para asistir a la consagración de la capilla croata. La", "note": "Publicado el marzo 2, 2025", "url": "https://revistatierrasanta.com/consagracion-de-la-capilla-croata-en-el-campo-de-los-pastores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Capilla-croata-1024x683.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "condena-unanime-a-los-ataques-a-cristianos-en-cisjordania", "title": "Condena unánime a los ataques a cristianos en Taybeh", "author": "direccion", "year": 2025, "category": "2025", "summary": "El Consejo de Patriarcas de las Iglesias de Jerusalén, compuesto por los líderes de las distintas ramas del cristianismo en Tierra Santa, ha pedido a la comunidad internacional, el 14 de julio, que actúe contra la violencia de los colonos israelíes en Taybeh, la única ciudad enteramente cristiana que queda en Cisjordania. A continuación, reproducimos", "note": "Publicado el julio 15, 2025", "url": "https://revistatierrasanta.com/condena-unanime-a-los-ataques-a-cristianos-en-cisjordania/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/1-1024x768.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "concierto-solidario-en-mallorca-a-favor-de-tierra-santa", "title": "Concierto solidario en Mallorca a favor de Tierra Santa ", "author": "direccion", "year": 2025, "category": "2025", "summary": "El viernes, 14 de marzo, tuvo lugar el acto solidario titulado «Desconhort per Terra Santa», dedicado a la recogida de donativos a favor de la Custodia franciscana de Tierra Santa. Fue organizado por el grupo de investigadores Vexil·la, especialistas en temas de Semana Santa. La Basílica de Sant Francesc de Palma acogió un emotivo concierto del Coro de Adultos de Sant Francesc y", "note": "Publicado el marzo 19, 2025", "url": "https://revistatierrasanta.com/concierto-solidario-en-mallorca-a-favor-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/1mall-1024x512.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "comunicado-sobre-el-acuerdo-de-paz-para-gaza", "title": "Comunicado sobre el fin de la guerra en Gaza", "author": "direccion", "year": 2025, "category": "2025", "summary": "“[El Todopoderoso] hace cesar las guerras hasta los confines de la tierra; quiebra el arco y destroza la lanza, quema los escudos con fuego. Dice: ‘Estad quietos, y sabed que yo soy Dios; seré exaltado entre las naciones, seré exaltado en la tierra’” (Salmo 46:9-10). Junto con millones de personas que viven en nuestra región", "note": "Publicado el octubre 14, 2025", "url": "https://revistatierrasanta.com/comunicado-sobre-el-acuerdo-de-paz-para-gaza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/10/IMG_8092-1024x332.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "christian-galvez-presenta-el-libro-san-lucas-el-evangelista-de-los-elegidos", "title": "Christian Gálvez presenta el libro «San Lucas, el evangelista de los elegidos»", "author": "direccion", "year": 2025, "category": "2025", "summary": "El viernes 28 de noviembre a las 19.00 de la tarde, la Basílica de San Francisco el Grande (Madrid) acogió la presentación del libro «Lucas, el evangelista de los invisibles, del escritor y presentador, Christian Gálvez. Durante la presentación, el autor reconoció que lo que más le gusta de San Lucas —médico griego— es su", "note": "Publicado el noviembre 29, 2025", "url": "https://revistatierrasanta.com/christian-galvez-presenta-el-libro-san-lucas-el-evangelista-de-los-elegidos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/IMG_9170-1024x768.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "celebracion-del-dia-de-los-difuntos-en-jerusalen", "title": "Celebración del Día de los Difuntos en Jerusalén", "author": "direccion", "year": 2025, "category": "2025", "summary": "En Jerusalén, el 2 de noviembre, Día de los Difuntos resuena de manera especial para los católicos locales y son varias las tradiciones vinculadas a esta fecha. Incluida entre las fiestas de precepto gracias a la reforma litúrgica iniciada por el Concilio Vaticano II, esta antigua celebración fue reconocida oficialmente como festividad en el lejano siglo", "note": "Publicado el noviembre 2, 2025", "url": "https://revistatierrasanta.com/celebracion-del-dia-de-los-difuntos-en-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/FG_251102_WEB_18.jpg-1024x683.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "carta-para-el-viii-centenario-del-cantico-de-las-criaturas", "title": "Carta para celebrar el VIII Centenario del Cántico de las Criaturas", "author": "direccion", "year": 2025, "category": "2025", "summary": "Los ministros generales de la Orden Franciscana han compartido una carta con motivo del VIII Centenario del Cántico de las Criaturas, que finalizará el próximo 21 de septiembre. Entre el dolor y el amor de Alvernia, donde Francisco recibió los estigmas, y el encuentro con la “hermana Muerte”, —dice el escrito— encontramos este cántico de", "note": "Publicado el septiembre 9, 2025", "url": "https://revistatierrasanta.com/carta-para-el-viii-centenario-del-cantico-de-las-criaturas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/09/2.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "camino-de-la-beatificacion-se-sor-maria-trinidad", "title": "Camino de la beatificación de Sor María Trinidad", "author": "direccion", "year": 2025, "category": "2025", "summary": "La fase diocesana de la causa de beatificación de Sor María de la Trinidad se abrió oficialmente el 30 de abril en el monasterio de las Clarisas de Jerusalén en un acto al que se unió la comunidad franciscana se unió en oración, junto con el Custodio, fray Francesco Patton. La ceremonia estuvo presidida por", "note": "Publicado el mayo 2, 2025", "url": "https://revistatierrasanta.com/camino-de-la-beatificacion-se-sor-maria-trinidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/05/Sor-Maria-de-la-Trinidad-1.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "biblia-y-arqueologia-en-los-cursos-de-verano-de-el-escorial", "title": "«Biblia y arqueología» en los cursos de verano de El Escorial", "author": "direccion", "year": 2025, "category": "2025", "summary": "En el marco de los Cursos de Verano CEU – El Escorial, se desarrollará el curso «Biblia y Arqueología», que tendrá lugar el 1 y 2 de julio de 2025 en el RCU María Cristina de San Lorenzo de El Escorial (Madrid). En este curso nos sumergiremos en la Biblia como un testimonio vivo de", "note": "Publicado el junio 20, 2025", "url": "https://revistatierrasanta.com/biblia-y-arqueologia-en-los-cursos-de-verano-de-el-escorial/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/06/Captura-de-pantalla-2025-06-20-a-las-16.51.54-1024x608.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "bendicion-de-las-capillas-espanolas-en-el-campo-de-los-pastores-en-beit-sahour", "title": "Bendición de las capillas españolas en el Campo de los Pastores en Beit Sahour", "author": "direccion", "year": 2025, "category": "2025", "summary": "Hoy, 5 de abril, ha sido un día muy especial para todos los españoles amantes de Tierra Santa. El arzobispo de Toledo, monseñor Francisco Cerro, ha bendecido e inaugurado la Capilla de Nuestra Señora de Guadalupe en el Campo de los Pastores, en Beit Sahour, junto a Belén. También ha bendecido los iconos y los", "note": "Publicado el abril 6, 2025", "url": "https://revistatierrasanta.com/bendicion-de-las-capillas-espanolas-en-el-campo-de-los-pastores-en-beit-sahour/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/WhatsApp-Image-2025-04-05-at-18.50.53-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "belen-recibe-al-nuevo-custodio", "title": "En Belén: peregrino de paz", "author": "direccion", "year": 2025, "category": "2025", "summary": "Fray Francesco Ielpo hizo su entrada solemne en Belén el sábado 26 de julio, recorriendo, como es tradición, el lado del muro que divide la ciudad de la Tumba de Raquel. Los ingresos del Custodio y del Patriarca de Jerusalén en la ciudad palestina son los únicos momentos en que se abre la puerta del", "note": "Publicado el julio 27, 2025", "url": "https://revistatierrasanta.com/belen-recibe-al-nuevo-custodio/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/Betlemme_20.jpg-1024x683.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "becas-de-estudios-universitarios-para-jovenes-sirios", "title": "Becas de estudios universitarios para jóvenes sirios", "author": "direccion", "year": 2025, "category": "2025", "summary": "Siria continúa en guerra y los cristianos viven más temerosos y amenzadados que nunca. Con la llegada de un nuevo gobierno a principios de año se abría una nueva esperanza. Si bien es cierto que se muestra tolerante con los cristianos no lo son, sin embargo, los grupos radicales que le apoyan y que han", "note": "Publicado el julio 22, 2025", "url": "https://revistatierrasanta.com/becas-de-estudios-universitarios-para-jovenes-sirios/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-19-at-17.57.36-1024x768.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "ayudanos-a-ayudar-a-tierra-santa", "title": "¡Ayúdanos a ayudar! a Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "El padre Custodio, Francesco Patton, hace un balance de la situación actual en Tierra Santa y resalta la importancia de colaborar en la Colecta Pontificia por os Santos Lugares del Viernes Santo para ayudar al mantenimiento de los Santuarios y a los cristianos de Tierra Santa. A continuación transcribimos su mensaje: Queridas amigas, queridos amigos,", "note": "Publicado el marzo 5, 2025", "url": "https://revistatierrasanta.com/ayudanos-a-ayudar-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/03/Captura-de-pantalla-2025-03-05-a-las-14.33.23-1024x589.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "apertura-del-viii-centenario-del-cantico-de-las-criaturas", "title": "Apertura del VIII Centenario del Cántico de las criaturas", "author": "direccion", "year": 2025, "category": "2025", "summary": "El próximo 11 de enero se inaugurará oficialmente el octavo centenario de Cántico de las criaturas, también conocida como Cántico al Hermano Sol, que fue compuesta por San Francisco de Asís cuando ya se encontraba prácticamente ciego. Lo hizo como alabanza y acción de gracias a Dios por la Creación. Al igual que en centenarios", "note": "Publicado el enero 8, 2025", "url": "https://revistatierrasanta.com/apertura-del-viii-centenario-del-cantico-de-las-criaturas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/ABU_CTS-OA-26773_Dipinto-768x432.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "7617-2", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2025, "category": "2025", "summary": "Intentar explicar todo el trabajo que hay detrás de cada obra es muy difícil, máxime si se ha seguido, de primera mano, las inquietudes, angustias y desvelos del autor, Miguel Ángel Laguna, ante, quizás, uno de sus mayores retos profesionales: pintar los cuadros del presbiterio de la Capilla de la Inmaculada Concepción en el santuario", "note": "Publicado el mayo 1, 2025", "url": "https://revistatierrasanta.com/7617-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/Captura-de-pantalla-2025-04-24-a-las-13.25.09-896x1024.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "24-de-mayo-dia-del-peregrino-2025", "title": "24 de mayo, Día del Peregrino 2025", "author": "direccion", "year": 2025, "category": "2025", "summary": "La Asociación Española de Amigos de Tierra Santa junto con la Comisaría de Tierra Santa han organizado, un año más, el tradicional Día del Peregrino. La cita será el sábado 24 de mayo en el colegio San Buenaventura de Madrid (C/ Greco, 16). Aunque la jornada dará comienzo a las 12 del mediodía, desde las", "note": "Publicado el marzo 28, 2025", "url": "https://revistatierrasanta.com/24-de-mayo-dia-del-peregrino-2025/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/IMG_4892-1024x768.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "20-iconos-20-gracias", "title": "20 iconos, ¡20 gracias!", "author": "direccion", "year": 2025, "category": "2025", "summary": "El pasado 5 de abril, sábado, se bendijeron en el Campo de los pastores los iconos de la Capilla de la Inmaculada Concepción (capilla española). Estos iconos han sido apadrinados por 20 entidades o personas individuales que habéis querido echarnos una mano con la financiación de dicha capilla. A todos vosotros, ¡gracias! A continuación, presentamos los iconos, con", "note": "Publicado el abril 9, 2025", "url": "https://revistatierrasanta.com/20-iconos-20-gracias/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/04/ajax-1024x512.webp", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "14-de-enero-el-custodio-inaugurara-la-capilla-espanola-de-la-inmaculada-concepcion-en-beit-sahour", "title": "14 de enero: El custodio inaugurará la Capilla de la Inmaculada Concepción en Beit Sahour", "author": "direccion", "year": 2025, "category": "2025", "summary": "El custodio de Tierra Santa, Francesco Ielpo, inaugurará oficialmente el 14 de enero a las 16.00h. la Capilla española de la Inmaculada Concepción, ubicada en el Campo de los Pastores (Beit Sahour). Para la inauguración se colocarán: en el retablo, los cuatro últimos iconos —de los 20 que se han realizado—; en el altar, el", "note": "Publicado el noviembre 27, 2025", "url": "https://revistatierrasanta.com/14-de-enero-el-custodio-inaugurara-la-capilla-espanola-de-la-inmaculada-concepcion-en-beit-sahour/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/11/Foto-1-Presbiterio-de-la-Capilla-de-la-Inmaculada-@Custodia-de-Tierra-Santa-1024x683.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "ya-esta-disponible-el-calendario-2025", "title": "Ya está disponible el Calendario 2025", "author": "direccion", "year": 2024, "category": "2024", "summary": "Por segundo año consecutivo, la Revista Tierra Santa regala a sus suscriptores el Calendario anual. En esta ocasión, la portada del Calendario de 2025 la hemos dedicado al 800 aniversario del Cántico de las Criaturas de San Francisco de Asís. Las fotografías que aparecen en el interior del calendario han sido realizadas por el fotógrafo", "note": "Publicado el noviembre 23, 2024", "url": "https://revistatierrasanta.com/ya-esta-disponible-el-calendario-2025/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/11/Captura-de-pantalla-2024-11-26-a-las-13.11.57-1024x747.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "vuelve-podlectio-meditaciones-sobre-tierra-santa", "title": "«PodLectio. Meditaciones sobre Tierra Santa», disponible en las principales plataformas", "author": "direccion", "year": 2024, "category": "2024", "summary": "Cada día, del 1 al 24 de diciembre, los frailes de la Custodia de Tierra Santa comentarán el Evangelio del día del tiempo de Adviento. La primera y la última meditación correrán a cargo del Custodio de Tierra Santa, fray Francesco Patton. Los diferentes episodios del podcast se publicarán cada día en las plataformas Spotify,", "note": "Publicado el diciembre 1, 2024", "url": "https://revistatierrasanta.com/vuelve-podlectio-meditaciones-sobre-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/PodLectio-1024x683.webp", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "visita-del-ministro-general-de-los-frailes-menores-a-la-capilla-de-la-inmaculada-en-el-campo-de-los-pastores", "title": "Visita del Ministro General de los Frailes Menores a la Capilla de la Inmaculada en el Campo de los Pastores", "author": "direccion", "year": 2024, "category": "2024", "summary": "La mañana del 19 de abril, el ministro general de los Frailes Menores, fray Massimo Fusarelli, y el vicario, fray Ignacio Ceja Jiménez, visitaron la ciudad de Belén. Dentro de su recorrido, y acompañados por el padre Custodio, Francesco Patton, el vicario, fray Ibrahim Faltas, el visitador general, fray Alojzy Warot, y el visitador asistente,", "note": "Publicado el abril 20, 2024", "url": "https://revistatierrasanta.com/visita-del-ministro-general-de-los-frailes-menores-a-la-capilla-de-la-inmaculada-en-el-campo-de-los-pastores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/IMG_3856-768x513.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "viernes-santo-una-jornada-de-solidaridad-universal-con-la-iglesia-de-jerusalen", "title": "Viernes Santo, una jornada de solidaridad universal con la Iglesia de Jerusalén", "author": "direccion", "year": 2024, "category": "2024", "summary": "Queridos amigos, queridas amigas, que el Señor os dé la paz. Después de haber vivido más de dos años de incertidumbre a causa del Covid y de habernos hecho la ilusión de que la normalidad había vuelto, el 7 de octubre nos sorprendió de repente el estallido de una nueva guerra en Tierra Santa, que, además de", "note": "Publicado el febrero 22, 2024", "url": "https://revistatierrasanta.com/viernes-santo-una-jornada-de-solidaridad-universal-con-la-iglesia-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/Custodio-768x432.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "via-crucis-por-la-paz", "title": "Via Crucis por la paz", "author": "direccion", "year": 2024, "category": "2024", "summary": "Alumnos de todas las escuelas cristianas de Jerusalén se dieron cita en el Santuario de la Flagelación, donde comenzó el Via Crucis por la Vía Dolorosa. Allí, se les dio a los estudiantes un pañuelo blanco con una oración por la paz. La procesión recorrió la ciudad vieja, pasando por las estaciones de la Pasión", "note": "Publicado el febrero 24, 2024", "url": "https://revistatierrasanta.com/via-crucis-por-la-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/viacrucisschools2024-05-768x513.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "vi-reflexion-franciscana", "title": "VI Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "Francisco, cuerpo“transparencia” de Cristo (LM 13, 8-9) Por más diligencia que ponía el Santo en tener oculto el tesoro encontrado en el campo (Mt 13,44), no pudo evitar que algunos llegaran a ver las llagas de sus manos y pies, no obstante llevar casi siempre cubiertas las manos y andar desde entonces con los pies calzados. Muchos hermanos vieron las llagas", "note": "Publicado el junio 3, 2024", "url": "https://revistatierrasanta.com/vi-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/foto-Retiro-junio-2024.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "v-reflexion-franciscana", "title": "V Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "Francisco, cuerpo “herido que cura” las heridas del hombre (LM 13, 5-7) Terminado el plazo de cuarenta días que se había propuesto pasar en soledad y próxima ya la solemnidad del arcángel Miguel [el 29 de septiembre], bajó del monte el angélico varón Francisco llevando consigo la efigie del Crucificado, no esculpida por mano de algún artífice en", "note": "Publicado el mayo 5, 2024", "url": "https://revistatierrasanta.com/v-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/5.-Retiro-mayo-2024.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "solemne-apertura-del-viii-centenario-de-los-estigmas-de-san-francisco", "title": "Solemne apertura del VIII Centenario de los Estigmas de San Francisco", "author": "direccion", "year": 2024, "category": "2024", "summary": "Se desarrollará, el 5 de enero, en La Verna bajo el título «De las heridas, vida nueva»", "note": "Publicado el enero 2, 2024", "url": "https://revistatierrasanta.com/solemne-apertura-del-viii-centenario-de-los-estigmas-de-san-francisco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/IMG_0771-1024x668.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "se-puede-peregrinar-de-nuevo-a-tierra-santa", "title": "Se puede peregrinar, de nuevo, a Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "La directora de la revista Tierra Santa, María Díaz-Ripoll, junto con María José Fernández, dama de la Orden de Caballería del Santo Sepulcro y responsable del voluntariado, y Anastasio Moreno, secretario de la Asociación Española de Amigos de Tierra Santa, han acudido el 5 de marzo al programa radiofónico «Tercer Sector», de Capital Radio, para", "note": "Publicado el marzo 6, 2024", "url": "https://revistatierrasanta.com/se-puede-peregrinar-de-nuevo-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/IMG_2606-1024x998.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "se-presenta-en-madrid-el-libro-confia", "title": "Se presenta en la Universidad San Pablo CEU el libro «Confía»", "author": "direccion", "year": 2024, "category": "2024", "summary": "Ayer, 24 de mayo, se presentó en el Aula Magna de la Universidad San Pablo CEU (Madrid), el libro «Confía», donde el autor, Eugenio Camacho, dio un impresionante testimonio de fe y abandono a la voluntad del Señor ante una de las mayores pronas que te puede poner la vida: enfrentarse a la más que", "note": "Publicado el mayo 25, 2024", "url": "https://revistatierrasanta.com/se-presenta-en-madrid-el-libro-confia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/IMG_4739-1024x984.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "se-abre-el-proceso-de-canonizacion-de-sor-maria-de-la-trinidad", "title": "Se abre el proceso de canonización de Sor María de la Trinidad", "author": "direccion", "year": 2024, "category": "2024", "summary": "Louisa Elisa Jacques nació el 26 de abril de 1901 en Pretoria (actualmente Sudáfrica) y creció en Suiza. Débil de salud, vivió una juventud atormentada en cuerpo y espíritu. A los 25 años experimentó una profunda crisis existencial que culminó en la «noche de la conversión», entre el 13 y el 14 de febrero de", "note": "Publicado el noviembre 29, 2024", "url": "https://revistatierrasanta.com/se-abre-el-proceso-de-canonizacion-de-sor-maria-de-la-trinidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/11/45-1935-Neuchatel.jpg-1024x766.webp", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "san-leonardo-de-porto-maurizio-iniciador-del-rezo-del-via-crucis", "title": "San Leonardo de Porto Maurizio, iniciador del rezo del Via Crucis", "author": "direccion", "year": 2024, "category": "2024", "summary": "Hoy dedicamos el santoral a San Leonardo, franciscano que nació en Puerto Mauricio (Italia) en 1676 y murió en Roma en 1751. Estudió con los jesuitas en Roma, y a los 21 años logró entrar en la Comunidad de los franciscanos. Una vez ordenado sacerdote se dedicó a la predicación, pero uniendo este apostolado al", "note": "Publicado el noviembre 26, 2024", "url": "https://revistatierrasanta.com/san-leonardo-de-porto-maurizio-iniciador-del-rezo-del-via-crucis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/11/San-Leonardo.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "retomamos-las-peregrinaciones-a-tierra-santa", "title": "Retomamos, con inmensa alegría, las peregrinaciones a Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Del 29 de febrero al 4 de marzo un grupo formado por nueve personas de la Comisaría de Tierra Santa estuvimos en Tierra Santa para ver y comprobar si se podían retomar las peregrinaciones, siempre con las debidas precauciones. Para ello, recorrimos los lugares que habitualmente se visitan en las peregrinaciones(Israel y territorios palestinos, Galilea y Judea,", "note": "Publicado el marzo 15, 2024", "url": "https://revistatierrasanta.com/retomamos-las-peregrinaciones-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/355a6dea-4bc4-49c5-861a-13ecca626159-1-806x1024.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "peregrinaciones-programadas-para-la-canonizacion-de-los-martires-de-damasco", "title": "Peregrinaciones programadas para la canonización de los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "Como venimos comentando, el próximo 20 de octubre será la canonización de los Mártires de Damasco, entre los que se encuentran siete franciscanos frailes menores españoles: Manuel Ruiz, superior de la Comunidad, nacido en San Martín de Ollas (Burgos) el 5 de mayo de 1804 (†56 años); Carmelo Bolta, nacido en Real de Gandía (Valencia)", "note": "Publicado el julio 23, 2024", "url": "https://revistatierrasanta.com/peregrinaciones-programadas-para-la-canonizacion-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/Captura-de-pantalla-2024-07-23-a-las-20.19.18-964x1024.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "padre-federico-jansoone-patrono-de-los-comisarios-de-tierra-santa", "title": "Padre Federico Jansoone, patrono de los Comisarios de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Federico Jansoone nació en Ghyvelde (Francia), el 19 de noviembre de 1838, hijo de Pedro Janssoone y de María Isabel Bollengier, cristianos de profundas convicciones y padres de familia numerosa. Como era muy inteligente, realizó sus estudios de forma brillante. Sintiéndose llamado al sacerdocio, ingresó en el seminario, pero pronto tuvo que dejarlo: su familia", "note": "Publicado el noviembre 19, 2024", "url": "https://revistatierrasanta.com/padre-federico-jansoone-patrono-de-los-comisarios-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/11/Federico-Jansoone.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "nuevo-numero-de-telefono-del-centro-tierra-santa", "title": "Nuevo número de teléfono del Centro Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "OS INFORMAMOS QUE YA TENEMOS NUEVO NÚMERO DE TELÉFONO DEL CENTRO TIERRA SANTA: +34 621096477. Asimismo, si queréis contactar con nosotros podéis hacerlo presencialmente en la C/ San Buenaventura, 1 (Madrid) o a través del correo electrónico: tierrasanta.suscripciones@gmail.com. Si queréis contactar con la directora de la Revista Tierra Santa, escribid a direccion@revistatierrasanta.com. El horario de", "note": "Publicado el marzo 7, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-telefono-del-centro-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/Imagen-1-1024x823.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-8", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "En este número de la revista queremos conmemorar el centenario de la Basílica del Getsemaní y celebrar la canonización de los Mártires de Damasco, siete de ellos franciscanos españoles. Pero no podemos dejar de pedir, insistentemente, por la paz y por el fin de tanto sufrimiento. No nos es ajeno el dolor de los que", "note": "Publicado el noviembre 4, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-8/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2025/01/Captura-de-pantalla-2025-01-16-a-las-13.40.34-781x1024.png", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-6", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Diccionario de la Real Academia de la Lengua define el martirio como aquella muerte “padecida por causa de una religión”. Así fue como fallecieron los Mártires de Damasco en 1860, defendiendo su fe hasta el extremo; entregando su vida y poniéndola en manos del Señor por no querer renunciar a su fe. A los once de Damasco —fray Manuel Ruiz,", "note": "Publicado el septiembre 12, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-6/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/09/4-Captura-de-pantalla-2024-09-12-a-las-13.45.12-867x1024.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-5", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Orar, dar limosna y peregrinar. Tres acciones. Tres pasos. Tres formas de ayudar a Tierra Santa y a la comunidad cristiana que allí reside. Eso fue lo que nos pidió fray Tony Choucry, ecónomo de la Custodia, en su reciente visita a nuestro país. Señaló, además, que en esta guerra debemos olvidar quién es el", "note": "Publicado el junio 20, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-5/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/Captura-de-pantalla-2024-06-20-a-las-10.51.26-709x1024.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-4", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Las noticias que nos llegan de Tierra Santa no son buenas. La situación de los cristianos allí donde la Custodia está presente, tampoco. Desde la Revista hemos querido hacernos eco de dos de esos países que, dependiendo de la Custodia, parecen caer en el olvido: Líbano y Siria. Dos países inmersos en la desesperanza y", "note": "Publicado el abril 23, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-4/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/IMG_3907-732x1024.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-3", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Tierra Santa nos hace falta. Seguir los pasos de Jesús en su tierra; caminar, respirar, abrir el corazón y sentir “desde dentro”, se echa de menos… Por eso queremos retomar poco a poco las peregrinaciones con una primera, a la que hemos llamado “La peregrinación de la esperanza”, para el próximo mes de abril. Siempre", "note": "Publicado el febrero 27, 2024", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-3/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/74-911x1024.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "nombrado-visitador-general-para-la-eleccion-del-futuro-custodio-de-tierra-santa", "title": "Nombrado Visitador General para la elección del futuro custodio de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Ministro General de la Orden de Frailes Menores, con su definitorio, ha nombrado a fray Alojzy Sławomir Warot Visitador General de la Custodia de Tierra Santa y a fray Marcello Ghirlando Visitador Asistente. La decisión fue tomada en la sesión del 22 de diciembre de 2023 y la Custodia de Tierra Santa acaba de hacerla pública. “Queremos", "note": "Publicado el enero 16, 2024", "url": "https://revistatierrasanta.com/nombrado-visitador-general-para-la-eleccion-del-futuro-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/fra_alojzy.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "ninos-de-la-casa-del-nino-en-belen-visitan-madrid", "title": "Jóvenes de la Casa del Niño en Belén visitan Madrid", "author": "direccion", "year": 2024, "category": "2024", "summary": "Un total de 20 niños y seis educadores de la Casa del Niño en Belén han visitado nuestro país. Durante su estancia, han tenido la ocasión de visitar diversas ciudades como Valencia, Ávila o Toledo, aunque la mayor parte del tiempo han estado en Madrid, acogidos por familias de la Parroquia del Santo Cristo de", "note": "Publicado el agosto 3, 2024", "url": "https://revistatierrasanta.com/ninos-de-la-casa-del-nino-en-belen-visitan-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/08/Casa-del-Nino-1-1024x768.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "monsenor-bruno-varriano-visita-espana", "title": "Monseñor Bruno Varriano, franciscano, visita España", "author": "direccion", "year": 2024, "category": "2024", "summary": "El obispo auxiliar del Patriarca Latino de Jerusalén en Chipre, Mons. Bruno Varriano, aterrizó el viernes 19 de abril en nuestro país. Nada más llegar, se dirigió al Centro de Tierra Santa, acompañado de Fr, Luis Quintana, director del mismo, donde bendijo sus instalaciones junto con las de la Comisaría y la Asociación de Amigos", "note": "Publicado el abril 21, 2024", "url": "https://revistatierrasanta.com/monsenor-bruno-varriano-visita-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/d8c5d85c-86ac-4e54-bb28-b22ab56a7c9f-1024x768.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "misa-por-la-paz-en-tierra-santa", "title": "Misa por la paz en Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Con ocasión de la visita a España de fray Toni Choucry, ecónomo de la Custodia, el 31 de mayo se celebró en la parroquia San Antonio del Retiro una Misa por la paz, en la que pudimos escuchar su testimonio sobre la situación actual y las dificultades por las que está atravesando la comunidad cristiana", "note": "Publicado el junio 1, 2024", "url": "https://revistatierrasanta.com/misa-por-la-paz-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/IMG_4877-1024x768.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "mensaje-de-pascua-de-fr-francesco-patton-custodio-de-tierra-santa", "title": "Mensaje de Pascua de Fr. Francesco Patton, Custodio de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Queridos amigos y amigas, Cada uno de nosotros ha vivido la dolorosa experiencia de perder a un ser querido: un padre, un hermano, un cónyuge, un hijo o un amigo. Es un momento de sufrimiento, de oscuridad y desesperación que recae sobre cada uno de nosotros cuyo dolor es incalculable. Las lágrimas descienden apresuradamente y", "note": "Publicado el marzo 30, 2024", "url": "https://revistatierrasanta.com/mensaje-de-pascua-de-fr-francesco-patton-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/custos2.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "los-rostros-de-los-martires-de-damasco-se-descubren-en-los-grandes-lienzos-de-1926", "title": "Los rostros de los Mártires de Damasco se descubren en los grandes lienzos de 1926", "author": "direccion", "year": 2024, "category": "2024", "summary": "Autora: Silvia Guiliano / CTS Ante la inminente canonización de los mártires de Damasco el 20 de octubre, en la gran sala de la Curia Custodial se han exhibido hoy, 24 de julio, los grandes lienzos originales que fueron utilizados en San Pedro con motivo de su beatificación, el 10 de octubre de 1926, hace", "note": "Publicado el julio 24, 2024", "url": "https://revistatierrasanta.com/los-rostros-de-los-martires-de-damasco-se-descubren-en-los-grandes-lienzos-de-1926/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/MD1-754x1024.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "los-magos-de-oriente", "title": "Los Magos de Oriente", "author": "direccion", "year": 2024, "category": "2024", "summary": "¿Eran unos sabios sin más o también reyes? ¿Eran sólo tres? ¿De dónde venían? Sólo tenemos la noticia que leemos en el evangelio de Mateo 2,1-12. Veamos la historia y su identidad. Estas preguntas, la última aún más, han tenido varias respuestas en la predicación, en la catequesis en la teología, en la leyenda hagiográfica.", "note": "Publicado el enero 4, 2024", "url": "https://revistatierrasanta.com/los-magos-de-oriente/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/Reyes-1024x640.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "los-franciscanos-celebran-misa-en-el-cenaculo", "title": "Los franciscanos celebran misa en el Cenáculo", "author": "direccion", "year": 2024, "category": "2024", "summary": "Es la cuarta vez desde hace 470 años que los franciscanos de la Custodia celebran misa en el Cenáculo. Sin embargo, este año ha tenido un significado especial porque han podido asistir peregrinos. La española Maria Jose Fernandez Martin ha tenido la suerte de vivir este momento y ha querido compartirlo con nosotros: “¿Cómo expresar", "note": "Publicado el marzo 29, 2024", "url": "https://revistatierrasanta.com/los-franciscanos-celebran-misa-en-el-cenaculo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/2-768x513.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "llega-a-madrid-la-exposicion-los-guardianes-de-la-tumba-de-jesus", "title": "Llega a Madrid la exposición “Los guardianes de la Tumba de Cristo”", "author": "direccion", "year": 2024, "category": "2024", "summary": "Es la primera vez que un fotoperiodista, Thomas Coex, de la agencia francesa AFP, consigue adentrase y fotografiar la vida cotidiana de los frailes franciscanos de la Custodia de Tierra Santa y es lo que se podrá ver en la exposición “Los guardianes de la tumba de Cristo”, que verá la luz en la Basílica", "note": "Publicado el septiembre 30, 2024", "url": "https://revistatierrasanta.com/llega-a-madrid-la-exposicion-los-guardianes-de-la-tumba-de-jesus/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/09/thomas_coex-768x548.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "la-revista-tierra-santa-participa-en-el-congreso-de-comisarios-de-mexico-y-centroamerica", "title": "La Revista Tierra Santa participa en el Congreso de Comisarios de México y Centroamérica", "author": "direccion", "year": 2024, "category": "2024", "summary": "La Revista Tierra Santa ha participado en el Congreso de Comisarios de México y Centroamérica, que se está desarrollando en Izamal, Yucatán (México). Fray Luis Quintana, director del Centro de Tierra Santa, fray Edgar, presidente del Conosur, y María Díaz-Ripoll, directora de la Revista, tuvieron ocasión de compartir experiencias, analizar la evolución de la Revista", "note": "Publicado el enero 24, 2024", "url": "https://revistatierrasanta.com/la-revista-tierra-santa-participa-en-el-congreso-de-comisarios-de-mexico-y-centroamerica/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/PHOTO-2024-01-23-20-12-45-4-1024x461.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-revista-espanola-tierra-santa-llega-a-mexico", "title": "La revista española Tierra Santa llega a México", "author": "direccion", "year": 2024, "category": "2024", "summary": "Desde hace meses hemos estado dándole vueltas a la idea. No podíamos obviar la misión principal de la Revista Tierra Santa: hacer llegar la tierra de Jesús al mayor número de personas posible; tanto a los peregrinos que ya la han visitado, y que sigan rememorando su experiencia de vida y fe vivida en aquellas", "note": "Publicado el abril 25, 2024", "url": "https://revistatierrasanta.com/la-revista-espanola-tierra-santa-llega-a-mexico/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/WhatsApp-Image-2024-04-15-at-23.34.20-1024x683.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-peregrinacion-de-la-esperanza-ya-esta-en-tierra-santa", "title": "La «Peregrinación de la esperanza» ya está en Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "¡La «Peregrinación de la Esperanza» ya ha llegado a Tierra Santa! Cuando iban a celebrar la Eucaristía en Saxum (Emaús) han tenido un encuentro con el padre Gabriel Romanelli, párroco latino de Gaza, con el que ha estado hablando de la situación actual en la que viven de los cristianos allí. Precisamente, el cartel de", "note": "Publicado el abril 1, 2024", "url": "https://revistatierrasanta.com/la-peregrinacion-de-la-esperanza-ya-esta-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/adc424da-8425-4c3a-9772-14554de442c1-1024x576.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "la-paz-palabra-de-la-sagrada-escritura-y-del-presente-de-las-guerras", "title": "La Paz. Palabra de la Sagrada Escritura y del presente de las guerras", "author": "direccion", "year": 2024, "category": "2024", "summary": "En el discurso del Papa Francisco al Cuerpo Diplomático acreditado ante la Santa Sede ha dicho que se inicia “un año para el que quisiéramos paz y que, sin embargo, comienza bajo el signo de conflictos y divisiones”. Es un hecho, sin embargo, que la paz está amenazada por múltiples conflictos y enfrentamientos, “en un", "note": "Publicado el febrero 12, 2024", "url": "https://revistatierrasanta.com/la-paz-palabra-de-la-sagrada-escritura-y-del-presente-de-las-guerras/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/IMG_1160-768x1024.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "la-inteligencia-artificial-al-servicio-de-la-humanidad", "title": "La Inteligencia artificial al servicio de la humanidad", "author": "direccion", "year": 2024, "category": "2024", "summary": "Bajo el lema «Inteligencia artificial y paz» se desarrolló a principios de enero la Jornada Mundial por la Paz en su 57 edición. En ella, el Papa Francisco hizo hincapié en las consecuencias que puede tener el uso de las tecnologías digitales a medio y largo plazo sobre los individuos, la sociedad y la paz", "note": "Publicado el enero 11, 2024", "url": "https://revistatierrasanta.com/la-inteligencia-artificial-al-servicio-de-la-humanidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/Inteligencia-Estupidez-Artificial-1024x512.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-gran-familia-de-la-revista-tierra-santa", "title": "La gran familia de la Revista Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Desde que a principios de 2023 el nuevo equipo de dirección comenzara su andadura, hemos conseguido formar una pequeña-gran familia. El consejo de redacción está compuesto por fray Luis Quintana, responsable del Centro Tierra Santa, María Díaz-Ripoll, directora de la Revista; fray Carlos Molina, director de Casa Nova de Nazaret; Cayetana Johnson, arqueóloga y profesora", "note": "Publicado el marzo 8, 2024", "url": "https://revistatierrasanta.com/la-gran-familia-de-la-revista-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/IMG_2641-1024x768.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-exposicion-los-guardianes-de-la-tumba-de-jesus-llega-a-madrid", "title": "La exposición “Los guardianes de la Tumba de Jesús” llega a Madrid", "author": "direccion", "year": 2024, "category": "2024", "summary": "Ha sido la primera vez que un fotógrafo ha conseguido entrar en el interior de la vida de la Custodia. Thomas Coex, de la agencia AFP, acompañó a los frailes en sus momentos de oración, trabajo y descanso. Tal y como él mismo nos cuenta “se acostumbraron a mi presencia y pude retratar momentos que", "note": "Publicado el octubre 18, 2024", "url": "https://revistatierrasanta.com/la-exposicion-los-guardianes-de-la-tumba-de-jesus-llega-a-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/10/IMG_8609-1024x768.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "la-epifania-del-senor", "title": "La Epifanía del Señor", "author": "direccion", "year": 2024, "category": "2024", "summary": "Del Evangelio según San Mateo 2,1-12 Habiendo nacido Jesús en Belén de Judea en tiempos del rey Herodes, unos magos de Oriente se presentaron en Jerusalén preguntando: «¿Dónde está el Rey de los judíos que ha nacido? Porque hemos visto salir su estrella y venimos a adorarlo». Al enterarse el rey Herodes, se sobresaltó y", "note": "Publicado el enero 5, 2024", "url": "https://revistatierrasanta.com/la-epifania-del-senor/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/adoracion-de-los-reyes-magos-6_thumb.jpg.webp", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-custodia-de-tierra-santa-y-la-actualidad-en-siria", "title": "La Custodia de Tierra Santa y la actualidad en Siria", "author": "direccion", "year": 2024, "category": "2024", "summary": "www.custodia.orgDesde hace años, la situación en Siria aparece en todos los medios internacionales como una situación dramática, golpeada primero por una guerra civil que duró 14 años, luego destruida por un violento terremoto y con un territorio dividido entre muchas facciones en guerra entre sí Lo ocurrido en los últimos días, de manera tan repentina", "note": "Publicado el diciembre 9, 2024", "url": "https://revistatierrasanta.com/la-custodia-de-tierra-santa-y-la-actualidad-en-siria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/aleppo_2_0-1024x576.webp", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-custodia-de-tierra-santa-se-une-a-la-jornada-de-ayuno-y-oracion-por-la-paz-convocada-por-el-cardenal-pierbattista-pizzaballa", "title": "La Custodia de Tierra Santa se une a la jornada de ayuno y oración por la paz convocada por el cardenal Pierbattista Pizzaballa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Queridos hermanos, La Custodia de Tierra Santa se une a la iniciativa de una jornada de oración, ayuno y penitencia convocada por el Patriarca Latino de Jerusalén, el cardenal Pierbattista Pizzaballa, para el próximo 7 de octubre. Esta fecha marca un año desde que «Tierra Santa, y más allá, fue sumergida en un vórtice de", "note": "Publicado el octubre 1, 2024", "url": "https://revistatierrasanta.com/la-custodia-de-tierra-santa-se-une-a-la-jornada-de-ayuno-y-oracion-por-la-paz-convocada-por-el-cardenal-pierbattista-pizzaballa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/10/Libano.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "la-custodia-de-tierra-santa-en-primera-linea-para-ayudar-a-los-ninos-de-gaza", "title": "La Custodia de Tierra Santa en primera línea para ayudar a los niños de Gaza", "author": "direccion", "year": 2024, "category": "2024", "summary": "Desde el aeropuerto militar de Ciampino de Roma llegaron el 29 de enero las primeras imágenes nocturnas que dan testimonio del comienzo de la operación humanitaria destinada a proporcionar asistencia médica a los niños de Gaza. A través del paso fronterizo de Rafah, actualmente único punto de salida de la franja de Gaza, los primeros 11 menores", "note": "Publicado el enero 31, 2024", "url": "https://revistatierrasanta.com/la-custodia-de-tierra-santa-en-primera-linea-para-ayudar-a-los-ninos-de-gaza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/IMG_1177-1024x729.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-custodia-de-tierra-santa-celebra-la-canonizacion-de-los-martires-de-damasco", "title": "La Custodia de Tierra Santa celebra la canonización de los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "Para conmemorar la canonización de los Mártires de Damasco, que será el próximo domingo 20 de octubre en la plaza De San Pedro, la Custodia de Tierra Santa ha organizado una serie de actividades conmemorativas en la Iglesia de San Salvador, en Jerusalén. El día 17, 18 y 19 de octubre, se celebrará un Triduo", "note": "Publicado el octubre 16, 2024", "url": "https://revistatierrasanta.com/la-custodia-de-tierra-santa-celebra-la-canonizacion-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/10/Captura-de-pantalla-2024-10-16-a-las-14.16.56-1024x695.png", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "jornada-de-ayuno-y-oracion-por-la-paz-en-tierra-santa-y-en-el-mundo", "title": "Jornada de ayuno y oración por la paz en Tierra Santa y en el mundo", "author": "direccion", "year": 2024, "category": "2024", "summary": "Hoy, 7 de octubre, cuando se cumple un año guerra en Tierra Santa, el Papa Francisco —al que se unieron la archidiócesis de Madrid, el cardenal Pizzaballa y el padre Custodio, Francisco Patton— convocó una jornada de ayuno y oración por la paz en Tierra Santa y en el mundo. La vigilia de oración —convocada", "note": "Publicado el octubre 7, 2024", "url": "https://revistatierrasanta.com/jornada-de-ayuno-y-oracion-por-la-paz-en-tierra-santa-y-en-el-mundo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/10/IMG_8231-1024x768.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "iv-reflexion-franciscana", "title": "IV Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "Francisco, cuerpo “crucificado” (LM 13,3-4) Al desaparecer la visión dejó en su corazón un ardor maravilloso, y no fue menos maravillosa la efigie de las señales que imprimió en su carne. Así, pues, al instante comenzaron a aparecer en sus manos y pies las señales de los clavos, tal como lo había visto poco antes en", "note": "Publicado el abril 12, 2024", "url": "https://revistatierrasanta.com/iv-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/4.-Retiro-abril-2024.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "indulgencias-en-tierra-santa-durante-el-jubileo-2025", "title": "Indulgencia en Tierra Santa durante el Jubileo 2025", "author": "direccion", "year": 2024, "category": "2024", "summary": "Durante el Jubileo 2025 los peregrinos de Tierra Santa también podrán obtener la indulgencia concedida por el Santo Padre si visitan, al menos, uno de estos tres santos lugares: El Santo Sepulcro (Jerusalen), la basílica de la Natividad (Belén) o la basílica de la Anunciación (Nazaret). La Penitenciaría Apostólica establece que “todos los fieles verdaderamente", "note": "Publicado el diciembre 27, 2024", "url": "https://revistatierrasanta.com/indulgencias-en-tierra-santa-durante-el-jubileo-2025/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/Estrella-Basilica-de-la-Natividad-topaz-enhance-1024x576.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "inauguracion-de-las-nuevas-instalaciones-de-la-casa-de-santiago-en-jerusalen", "title": "Inauguración de las nuevas instalaciones de la Casa de Santiago en Jerusalén", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Centro de Estudios Bíblicos y Arqueológicos de España, más conocido como Casa de Santiago, ha inaugurado sus nuevas instalaciones en Jerusalén. El cardenal Juan José Omella, arzobispo de Barcelona y presidente de la Conferencia Episcopal española, presidió una Misa en la Capilla de San Vicente de Paúl, concelebrada por el cardenal Pierbattista Pizzaballa, Patriarca", "note": "Publicado el marzo 3, 2024", "url": "https://revistatierrasanta.com/inauguracion-de-las-nuevas-instalaciones-de-la-casa-de-santiago-en-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/PLJ.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "inauguracion-de-la-exposicion-tesoros-reales-obras-maestras-del-terra-sancta-museum-en-santiago-de-compostela", "title": "Inauguración de la Exposición “Tesoros Reales. Obras maestras del Terra Sancta Museum” en Santiago de Compostela", "author": "direccion", "year": 2024, "category": "2024", "summary": "El jueves 21 de marzo, en el Museo Centro Gaiás de la Ciudad de la Cultura de Santiago de Compostela, tuvo lugar la inauguración “Tesoros Reales. Obras maestras del Terra Sancta Museum”. La exposición, que permanecerá abierta del 22 de marzo hasta el 4 de agosto y cuya entrada es gratuita, está compuesta por un", "note": "Publicado el marzo 22, 2024", "url": "https://revistatierrasanta.com/inauguracion-de-la-exposicion-tesoros-reales-obras-maestras-del-terra-sancta-museum-en-santiago-de-compostela/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/IMG_2844-1024x935.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "imagen-oficial-de-la-canonizacion-de-los-martires-de-damasco", "title": "Imagen oficial de la canonización de los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "La imagen de los Santos Mártires Franciscanos y Maronitas de Damasco (+1860), encargada por la Postulación General OFM con motivo de la canonización solemne del 20 de octubre de 2024, es obra gráfica del ilustrador Andrea Pucci, a quien se debe, entre otras cosas, el gran ciclo iconográfico de los santos que decora el interior", "note": "Publicado el septiembre 3, 2024", "url": "https://revistatierrasanta.com/imagen-oficial-de-la-canonizacion-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/09/Canonizacion-728x1024.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "iii-reflexion-franciscana", "title": "III Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "Francisco, cuerpo “atravesado” por la compasión (LM 13,3) Elevándose, pues, a Dios a impulsos del ardor seráfico de sus deseos y transformado por su tierna compasión en Aquel que a causa de su extremada caridad, quiso ser crucificado: cierta mañana de un día próximo a la fiesta de la Exaltación de la Santa Cruz, mientras", "note": "Publicado el marzo 11, 2024", "url": "https://revistatierrasanta.com/iii-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/BerlinghieroFrancisPescia_19-21.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "ii-reflexion-franciscana", "title": "II Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "2024", "note": "Publicado el febrero 7, 2024", "url": "https://revistatierrasanta.com/ii-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/images.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "i-reflexion-franciscana", "title": "I Reflexión franciscana", "author": "direccion", "year": 2024, "category": "2024", "summary": "Francisco, cuerpo “gastado” por el Evangelio, y “dedicado” a la contemplación (LM 13,1) Era costumbre en el angélico varón Francisco no cesar nunca en la práctica del bien, antes, por el contrario, a semejanza de los espíritus celestiales en la escala de Jacob, o subía hacia Dios o descendía hasta el prójimo (Gen 28,12). En", "note": "Publicado el enero 15, 2024", "url": "https://revistatierrasanta.com/i-reflexion-franciscana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/images.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "hoy-celebramos-san-nicolas-taveric-y-companeros-martires", "title": "Hoy celebramos San Nicolás Taveric y compañeros mártires", "author": "direccion", "year": 2024, "category": "2024", "summary": "Los santos Nicolás Tavelic, Deodato de Rodez, Estaban de Cuneo y Pedro de Narbona, sacerdotes franciscanos, murieron mártires en Jerusalén el 14 de noviembre de 1391. Procedían de distintas Provincias franciscanas: Croacia, Aquitania, Génova y Provenza, y coincidieron en la Custodia de Tierra Santa, confiada por la Santa Sede a la Orden franciscana. San Nicolas", "note": "Publicado el noviembre 14, 2024", "url": "https://revistatierrasanta.com/hoy-celebramos-san-nicolas-taveric-y-companeros-martires/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/11/Sveti-Nikola-Tavelic-e1731573394211.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "guadalupe-madre-de-la-humanidad", "title": "Guadalupe, madre de la humanidad", "author": "direccion", "year": 2024, "category": "2024", "summary": "La Comisaría de Tierra Santa de la provincia de la Inmaculada Concepción publicaba recientemente en su blog una peregrinación a México para el próximo mes de abril http://tierrasanta-ofminmaculada.blogspot.com/2024/01/peregrinacion-mexico-guadalupe.html cuyo punto culminante será la visita a la Basílica Nuestra Señora de Guadalupe. Para ir calentando motores os animamos a que antes de ir físicamente a conocerla,", "note": "Publicado el febrero 20, 2024", "url": "https://revistatierrasanta.com/guadalupe-madre-de-la-humanidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/IMG_1448-768x1024.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "fray-tony-choucry-economo-de-la-custodia-visita-espana", "title": "Fray Toni Choucry, ecónomo de la Custodia, visita España", "author": "direccion", "year": 2024, "category": "2024", "summary": "Orar, dar limosna y peregrinar a Tierra Santa. Así podríamos resumir la petición que ha hecho fray Toni Choucry, ecónomo de la Custodia de Tierra Santa, durante los diversos encuentros y Misas por la Paz que ha realizado durante su viaje a España, del 29 de mayo al 7 de junio. “No busquéis quién es", "note": "Publicado el junio 7, 2024", "url": "https://revistatierrasanta.com/fray-tony-choucry-economo-de-la-custodia-visita-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/2.-Consejo_Episcopal-1024x576.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "fray-fadi-azar-y-fray-luis-quintana-rezan-por-el-alma-de-michel-en-el-cementerio-de-almeria", "title": "Fray Fadi Azar y fray Luis Quintana rezan por el alma de Michel en el cementerio de Almería", "author": "direccion", "year": 2024, "category": "2024", "summary": "Hace unos días contábamos la historia de Michel, un hombre de 40 años —casado y padre de dos hijos, Elías y Melena, que actualmente tienen 11 y 4 años— que trabajaba como marino mercante. Como cualquier otro día, salió en barco para trabajar pero esta vez no volvió a casa. Michel, junto con dos compañeros", "note": "Publicado el julio 7, 2024", "url": "https://revistatierrasanta.com/fray-fadi-azar-y-fray-luis-quintana-rezan-por-el-alma-de-michel-en-el-cementerio-de-almeria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/WhatsApp-Image-2024-07-07-at-19.18.31-768x1024.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "fray-edgar-presidente-de-la-conferencia-del-conosur-visita-madrid", "title": "Fray Edgar, presidente de la Conferencia del Conosur, visita Madrid", "author": "direccion", "year": 2024, "category": "2024", "summary": "El presidente de los comisarios del Conosur, el brasileño fray Edgar, está de visita en Madrid. Durante su estancia en la ciudad, fray Edgar dio testimonio de la presencia de los franciscanos en Brasil en la parroquia Cristo de la Paz, ha participado en diferentes reuniones y encuentros con comisarios de Tierra Santa de España", "note": "Publicado el enero 24, 2024", "url": "https://revistatierrasanta.com/fray-edgar-presidente-de-la-conferencia-del-conosur-visita-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/PHOTO-2024-01-23-20-12-45-2-461x1024.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "felicitacion-de-navidad-del-custodio-de-tierra-santa", "title": "Felicitación de Navidad del Custodio de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Estimadas amigas, estimados amigos, Como nos cuenta el evangelista Lucas, María y José tuvieron que ir a Belén para el censo. Como no había sitio para ellos en ningún albergue, tuvieron que adaptarse y encontraron cobijo en una gruta, de las que usaban los pastores. Así tienen un poco de privacidad y María puede dar", "note": "Publicado el diciembre 20, 2024", "url": "https://revistatierrasanta.com/felicitacion-de-navidad-del-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/christmas_greetings_2023_01.jpg-768x512.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "estamos-de-celebracion", "title": "¡ Estamos de celebración!", "author": "direccion", "year": 2024, "category": "2024", "summary": "Durante todo 2023 hemos celebrado que hace 800 años San Francisco de Asís realizó en Greccio (Italia) el primer belén viviente. Por eso queremos compartir nuestra alegría con vosotros REGALANDO el próximo número de la Revista Tierra Santa en formato pdf, correspondiente a los meses de enero-febrero 2024.Podéis descargar de manera gratuita la Revista correspondiente", "note": "Publicado el enero 3, 2024", "url": "https://revistatierrasanta.com/estamos-de-celebracion/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/IMG_0775-1024x833.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "encuentro-de-la-asociacion-espanola-de-amigos-de-tierra-santa", "title": "Encuentro de la Asociación Española de Amigos de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "La Asociación Española de Amigos de Tierra Santa ha organizado, el 27 de enero, un encuentro cultural y religioso en la Basílica de San Francisco el Grande (Madrid).Entre socios de la asociación, amigos y familiares se congregaron más de un centener de personas que escucharon atentas las explicaciones de fray Pedro González, comisario de Tierra", "note": "Publicado el enero 29, 2024", "url": "https://revistatierrasanta.com/encuentro-de-la-asociacion-espanola-de-amigos-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/IMG_1135-2-1024x768.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "encuentro-anual-de-animadores-de-tierra-santa", "title": "Encuentro anual de animadores de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "La Comisaría de Tierra Santa reunió, el 26 de enero, en la Basílica de San Francisco El Grande (Madrid) a sacerdotes y religiosos que acompañan las peregrinaciones a Tierra Santa y otros lugares. Esta reunión anual se hace desde hace más de 40 años para continuar la formación permanente, informar de las novedades y convivir", "note": "Publicado el enero 27, 2024", "url": "https://revistatierrasanta.com/encuentro-anual-de-animadores-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/IMG_1088-866x1024.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "en-verdad-ha-resucitado", "title": "¡En verdad ha resucitado!", "author": "direccion", "year": 2024, "category": "2024", "summary": "", "note": "Publicado el marzo 31, 2024", "url": "https://revistatierrasanta.com/en-verdad-ha-resucitado/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/E.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "en-paiporta-este-ano-la-navidad-sera-mas-navidad", "title": "En Paiporta este año, la Navidad, será más Navidad", "author": "direccion", "year": 2024, "category": "2024", "summary": "Autor: Gustavo Riveiro. Párroco de San Jorge en Paiporta (Valencia). Hace unos días una señora que vino a retirar elementos de primera necesidad me pregunto si este año “tendríamos Navidad”, “si iba a haber Navidad”. Es claro que, ante sus ojos como ante los míos, la pregunta estaba motivada en dos situaciones: la primera, que", "note": "Publicado el diciembre 4, 2024", "url": "https://revistatierrasanta.com/en-paiporta-este-ano-la-navidad-sera-mas-navidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/Paiporta2-768x432.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "empieza-el-proyecto-la-cena-la-pones-tu-2024", "title": "Empieza el proyecto solidario «La cena la pones tú – 2024»", "author": "direccion", "year": 2024, "category": "2024", "summary": "Un año más y con la llegada del Adviento, desde la Comisaría de Tierra Santa de la Provincia de la Inmaculada se ha puesto en marcha el proyecto «La cena la pones tú – 2024». Se trata de u na propuesta que consiste en donar el valor de una cena navideña (30€) para ayudar a que", "note": "Publicado el diciembre 1, 2024", "url": "https://revistatierrasanta.com/empieza-el-proyecto-la-cena-la-pones-tu-2024/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/Cena.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "emotivas-palabras-de-monsenor-bruno-varriano", "title": "Emotivas palabras de monseñor Bruno Varriano", "author": "direccion", "year": 2024, "category": "2024", "summary": "Supone una gran alegría poder compartir con mis hermanos y hermanas de España, y con todos mis amigos de habla hispana, mi experiencia personal tras mi ordenación episcopal, que tuvo lugar el 16 de marzo de este año. Soy el primer obispo católico latino en Chipre desde hace 400 años. Realmente me conmovió la misericordia", "note": "Publicado el junio 17, 2024", "url": "https://revistatierrasanta.com/emotivas-palabras-de-monsenor-bruno-varriano/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/IMG_3968-2-959x1024.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "el-patriarca-de-jerusalen-de-visita-pastoral-en-gaza", "title": "El Patriarca Latino de Jerusalén transmite un mensaje de esperanza en Gaza", "author": "direccion", "year": 2024, "category": "2024", "summary": "Según informan desde el Patriarcado Latino de Jerusalén, su Beatitud, el cardenal Pierbattista Pizzaballa ha entrado, el 16 de mayo, en Gaza para realizar una visita pastoral en la parroquia de la Sagrada Familia. Junto a su Beatitud estuvieron su Excelencia Fray Alessandro de Franciscis, gran hospitalario de la soberana Orden de Malta, el P.", "note": "Publicado el mayo 16, 2024", "url": "https://revistatierrasanta.com/el-patriarca-de-jerusalen-de-visita-pastoral-en-gaza/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/whatsapp-image-2024-05-16-at-130015-1-2-1024x768.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "el-papa-recibe-en-audiencia-a-una-delegacion-del-sbf", "title": "El Papa recibe en audiencia a una delegación del Studium Biblicum Franciscanum de Jerusalén", "author": "direccion", "year": 2024, "category": "2024", "summary": "El 7 de enero se celebró un cumpleaños en Jerusalén. La escuela de Sagrada Escritura y arqueología bíblica de la Custodia de Tierra Santa, el Studium Biblicum Franciscanum (SBF) cumplía 100 años. Profesores, alumnos y frailes franciscanos del Convento de la Flagelación —sede del SBF— se reunieron para celebrarlo, con un momento de recuerdo y", "note": "Publicado el enero 15, 2024", "url": "https://revistatierrasanta.com/el-papa-recibe-en-audiencia-a-una-delegacion-del-sbf/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/DSC1800-1024x683.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "el-papa-francisco-santifica-a-los-martires-de-damasco", "title": "El Papa Francisco canoniza a los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "El 20 de octubre a las 10.30 de la mañana comenzó la solemne celebración de la canonización de los 14 nuevos santos, once de ellos conocidos como los Mártires de Damasco. A esa hora, la plaza de San Pedro ya estaba llena de religiosos y feligreses que quisieron estar presentes en un día tan señalado", "note": "Publicado el octubre 21, 2024", "url": "https://revistatierrasanta.com/el-papa-francisco-santifica-a-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/10/@Lorenzo-Iorfino_053-1024x683.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "el-papa-aprueba-la-canonizacion-de-los-martires-de-damasco", "title": "El Papa Francisco aprueba la canonización de los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Sumo Pontífice ha aprobado, el 23 de mayo, los votos favorables de la Sesión Ordinaria de los padres cardenales y obispos para la canonización de los siete beatos españoles, de la Orden franciscana de los Hermanos Menores, y de Francisco, Abdel Mooti y Raphael Massabki, fieles laicos, asesinados en odio a la fe en", "note": "Publicado el mayo 23, 2024", "url": "https://revistatierrasanta.com/el-papa-aprueba-la-canonizacion-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/Huesos-1024x768.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "el-padre-franciscano-bruno-varriano-nombrado-obispo-auxiliar", "title": "El padre franciscano Bruno Varriano, nombrado obispo auxiliar del Patriarcado Latino de Jerusalén", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Santo Padre, el papa Francisco, ha nombrado obispo auxiliar para la diócesis patriarcal de los latinos de Jerusalén a fray Bruno Varriano, fraile menor de la Custodia de Tierra Santa. A través de un comunicado, el cardenal Pierbattista Pizzaballa ha anunciado el nombramiento del padre Bruno Varriano, que continuará su misión como Vicario patriarcal", "note": "Publicado el enero 9, 2024", "url": "https://revistatierrasanta.com/el-padre-franciscano-bruno-varriano-nombrado-obispo-auxiliar/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/bruno-varriano-ofm_750xauto.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "el-obispo-de-chipre-realiza-el-camino-de-santiago-con-un-grupo-de-jovenes-catolicos-de-chipre", "title": "El obispo de Chipre realiza el Camino de Santiago con un grupo de jóvenes católicos chipriotas", "author": "direccion", "year": 2024, "category": "2024", "summary": "Un grupo de 33 jóvenes católicos de Chipre, de entre 13 y 20 años, aterrizaron en España el 16 de agosto para realizar el Camino de Santiago, acompañados y guiados por el obispo de Chipre, monseñor Bruno Varriano, tres frailes franciscanos, un sacerdote del Verbo Encarnado, dos clarisas y dos catequistas. En Madrid, el grupo", "note": "Publicado el agosto 24, 2024", "url": "https://revistatierrasanta.com/el-obispo-de-chipre-realiza-el-camino-de-santiago-con-un-grupo-de-jovenes-catolicos-de-chipre/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/08/WhatsApp-Image-2024-08-22-at-07.38.15-576x1024.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "el-naufragio-de-una-vida", "title": "El naufragio de una vida", "author": "direccion", "year": 2024, "category": "2024", "summary": "En una de sus visitas a España en 2023, fray Fadi Azar, párroco del convento Sagrado Corazón de Jesús en Latakia (Siria) nos contó la triste historia de Michel y pidió nuestra colaboración. Michel era un hombre sirio de 40 años, padre de dos hijos, que había hecho el servicio militar en su país durante", "note": "Publicado el junio 20, 2024", "url": "https://revistatierrasanta.com/el-naufragio-de-una-vida/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/e989eec0-0e83-427d-bb4a-f9341618f341-671x1024.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "el-cardenal-pizzaballa-en-barcelona", "title": "El Cardenal Pizzaballa, en Barcelona", "author": "direccion", "year": 2024, "category": "2024", "summary": "Anualmente el cardenal Juan José Omella convoca a todos los jóvenes de la diócesis de Barcelona para comenzar juntos la Cuaresma alrededor de una cruz de una comunidad cristiana del país que está en guerra o en sufrimiento. En esta ocasión, «Sent la Creu» se ha celebrado el 18 de febrero en la Basílica de", "note": "Publicado el febrero 19, 2024", "url": "https://revistatierrasanta.com/el-cardenal-pizzaballa-en-barcelona/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/P-1-1024x683.png", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "el-beato-lorquino-pedro-soler", "title": "El beato lorquino Pedro Soler", "author": "direccion", "year": 2024, "category": "2024", "summary": "AUTOR: Ricardo Martínez Sánchez. Técnico del Archivo y Biblioteca Franciscana de Fondos Antiguos de Murcia. Pedro Nolasco Prudencio Soler Menéndez, nace en Lorca en 1827, en el seno de una familia numerosa. Su educación la inicia en la Escuela Caritativa de San Diego, en el convento de Nuestra Señora de los Desamparados (Lorca), perteneciente a", "note": "Publicado el septiembre 20, 2024", "url": "https://revistatierrasanta.com/el-beato-lorquino-pedro-soler/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/09/Pedro-Soler-2.png", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "el-20-de-octubre-sera-la-canonizacion-de-los-martires-de-damasco", "title": "El 20 de octubre serán canonizados los Mártires de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Sumo Pontífice aprobó el pasado 23 de mayo la canonización de los siete beatos españoles y un austriaco, de la Orden franciscana de los Hermanos Menores, y de Francisco, Abdel Mooti y Raphael Massabki, fieles laicos, asesinados en odio a la fe en Damasco (Siria) entre el 9 y el 10 de julio de", "note": "Publicado el julio 3, 2024", "url": "https://revistatierrasanta.com/el-20-de-octubre-sera-la-canonizacion-de-los-martires-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/Foto-2-1024x576.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "dia-de-oracion-por-la-paz-en-nazaret", "title": "Día de oración por la paz en Nazaret", "author": "direccion", "year": 2024, "category": "2024", "summary": "El próximo 8 de mayo, de 8 de la mañana a 5 de la tarde, se va a celebrar en la Basílica de la Anunciación en Nazaret, un día de oración por la paz. La jornada, comenzará a las 8 de la mañana con la Eucaristía. Posteriormente, se expondrá el Santísimo y a las 10.30", "note": "Publicado el mayo 7, 2024", "url": "https://revistatierrasanta.com/dia-de-oracion-por-la-paz-en-nazaret/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/Nazaret-726x1024.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "declaraciones-del-padre-custodio-francesco-patton-sobre-siria", "title": "Declaraciones del padre Custodio, Francesco Patton, sobre Siria", "author": "direccion", "year": 2024, "category": "2024", "summary": "“Esta tarde, domingo 1 de diciembre, durante un bombardeo sobre la ciudad de Alepo, una bomba cayó sobre el complejo franciscano del Terra Santa College. Gracias a Dios no hubo víctimas ni heridos, sólo el edificio resultó dañado. Nuestros frailes y fieles de la parroquia se encuentran todos bien. Desde nuestra Curia estamos en constante", "note": "Publicado el diciembre 2, 2024", "url": "https://revistatierrasanta.com/declaraciones-del-padre-custodio-francesco-patton-sobre-siria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/12/Aleppo-1024x576.webp", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "crece-la-poblacion-cristiana-en-israel", "title": "Crece la población cristiana en Israel", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Servicio Central de Estadística publicó datos estadísticos, el 24 de diciembre de 2023, que indican que aproximadamente 187.000 cristianos viven en Israel, lo que constituye el 1,9% de la población total del país. La población cristiana creció así un 1,3%. Según los datos, los cristianos árabes constituyen el 75,3% de los cristianos israelíes y", "note": "Publicado el enero 25, 2024", "url": "https://revistatierrasanta.com/crece-la-poblacion-cristiana-en-israel/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/Nazareth_View-768x621.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "conmemoracion-de-la-muerte-de-san-buenaventura", "title": "Conmemoración de la muerte de San Buenaventura", "author": "direccion", "year": 2024, "category": "2024", "summary": "La muerte de San Buenaventura tuvo lugar un 15 de julio de 1274. Se cumple ahora el 750 aniversario de su fallecimiento, motivo por el cual los Ministros Generales de la Primera Orden y de la Tercera Orden Regular han querido recordar y valorar en una carta el servicio y legado que dejó a la", "note": "Publicado el febrero 21, 2024", "url": "https://revistatierrasanta.com/conmemoracion-de-la-muerte-de-san-buenaventura/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/02/IMG_1475-1024x1021.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "conferencia-primeros-viajes-y-expediciones-espanolas-e-hispanoamericanas-a-las-tierras-biblicas", "title": "Conferencia «Primeros viajes y expediciones españolas e hispanoamericanas a las tierras bíblicas»", "author": "direccion", "year": 2024, "category": "2024", "summary": "La egiptóloga y orientalista Maria Luz Mangado dará una ponencia, el 13 de junio, sobre los primeros documentales a los Santos Lugares y las primeras filmaciones de Egipto, Jerusalén o Cisjordania, que comienzan con los viajes y exploraciones organizadas desde España e Hispanoamérica a las Tierras Bíblicas a finales del siglo XIX.", "note": "Publicado el mayo 29, 2024", "url": "https://revistatierrasanta.com/conferencia-primeros-viajes-y-expediciones-espanolas-e-hispanoamericanas-a-las-tierras-biblicas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/12-812x1024.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "comunicado-de-los-patriarcas-y-jefes-de-la-iglesia-de-jerusalen", "title": "Comunicado de los Patriarcas y Jefes de la Iglesia de Jerusalén", "author": "direccion", "year": 2024, "category": "2024", "summary": "“Bienaventurados los pacificadores, porque ellos serán llamados hijos de Dios”. Mateo 5:9 Al acercarnos rápidamente al duodécimo mes de la devastadora guerra actual, nosotros, los Patriarcas y Jefes de las Iglesias en Jerusalén, nos sentimos obligados Para expresar una vez más nuestra profunda preocupación por el rumbo que está tomando. A pesar de los repetidos", "note": "Publicado el agosto 27, 2024", "url": "https://revistatierrasanta.com/comunicado-de-los-patriarcas-y-jefes-de-la-iglesia-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/08/Captura-de-pantalla-2024-08-28-a-las-10.56.00-734x1024.png", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "comienza-la-semana-de-oracion-por-la-unidad-de-los-cristianos", "title": "Comienza la Semana de oración por la Unidad de los Cristianos", "author": "direccion", "year": 2024, "category": "2024", "summary": "La Iglesia celebra la Semana de Oración por la Unidad de los Cristianos del 18 al 25 de enero de 2024 este año con el lema «Amarás al Señor, tu Dios… y a tu prójimo como a ti mismo» (Lc 10,27) Las comunidades cristianas de Tierra Santa vuelven a rezar juntas en las iglesias de Jerusalén, con motivo de esta semana", "note": "Publicado el enero 18, 2024", "url": "https://revistatierrasanta.com/comienza-la-semana-de-oracion-por-la-unidad-de-los-cristianos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/2024-semana-oracion-portada-768x576.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "challenge-internacional-organiza-el-curso-mujeres-en-la-biblia", "title": "Challenge Internacional organiza el curso «Mujeres en la Biblia»", "author": "direccion", "year": 2024, "category": "2024", "summary": "A partir del 1 de abril dará comienzo el Challenge «Mujeres en la Biblia I (Antiguo Testamento». Con este curso —desarrollado en doce etapas— descubriremos el papel fundamental de la mujer en la historia de la salvación y cómo Dios las ha dignificado desde el principio de los tiempos: Ester, Rut, Miriam, Abigail, Débora, Rebeca,", "note": "Publicado el marzo 12, 2024", "url": "https://revistatierrasanta.com/challenge-internacional-organiza-el-curso-mujeres-en-la-biblia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/Unknown.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "carta-del-santo-padre-a-los-catolicos-de-tierra-santa", "title": "Carta del Santo Padre a los católicos de Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "drama absurdo de la guerra, a los niños a los que se les niega un futuro, a cuantos lloran y sufren, a cuantos experimentan angustia y desorientación. La Pascua, centro de nuestra fe, tiene aún más significado para ustedes, que la celebran en los lugares en los que el Señor vivió, murió y resucitó. No", "note": "Publicado el marzo 27, 2024", "url": "https://revistatierrasanta.com/carta-del-santo-padre-a-los-catolicos-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/03/papa-francisco-viacrucis-coliseo-1024x576.webp", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "carmelo-bolta-discipulo-misionero-y-martir", "title": "Carmelo Bolta: discípulo, misionero y mártir", "author": "direccion", "year": 2024, "category": "2024", "summary": "AUTOR: Padre Gonzalo M. Carbó Bolta. Cooperador de la Verdad de la Madre de Dios Mientras estaba en Roma como peregrino, el pasado 24 de mayo, me transmitieron la gran noticia. El Santo Padre había aprobado el día anterior la canonización, entre otros, de los once “Mártires de Damasco”, ocho de los cuales eran hermanos", "note": "Publicado el septiembre 11, 2024", "url": "https://revistatierrasanta.com/carmelo-bolta-discipulo-misionero-y-martir/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/09/Carmelo-Bolta-foto-1024x717.webp", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "canonizacion-de-los-martires-franciscanos-de-damasco", "title": "Canonización de los mártires franciscanos de Damasco", "author": "direccion", "year": 2024, "category": "2024", "summary": "Autor: Fray Fadi Azar, OFM. Párroco del Convento del Sagrado Corazón de Jesús en Latakia (Siria) Los custodios de los Santos Lugares eran hijos de san Francisco de Asís, quien en 1219 había predicado el Evangelio al sultán de Egipto. Se encargaron de conservar y restaurar las basílicas cristianas, y cuidaron de los peregrinos y", "note": "Publicado el julio 16, 2024", "url": "https://revistatierrasanta.com/canonizacion-de-los-martires-franciscanos-de-damasco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/10-1024x576.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "cambio-de-numero-de-suscriptor", "title": "Cambio de número de suscriptor para el sorteo de un viaje a Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "Con motivo de la actualización de nuestra base de datos vamos a proceder a dar a todos los suscriptores un nuevo número que será con el que, a partir de ahora participen en el sorteo de un viaje a Tierra Santa. Por lo tanto, el número con el que reciban la próxima revista, correspondiente a", "note": "Publicado el julio 5, 2024", "url": "https://revistatierrasanta.com/cambio-de-numero-de-suscriptor/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/07/IMG_5364-1024x639.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "bendicion-del-icono-de-maria-inmaculada-en-beit-sahour", "title": "Bendición del icono de María Inmaculada en Beit Sahour", "author": "direccion", "year": 2024, "category": "2024", "summary": "Hoy 2 de abril, se ha colocado el icono principal de María Inmaculada en la capilla de la Inmaculada, en el Campo de los Pastores en Beit Sahour, que ha sido íntegramente sufragada por donaciones españolas a la Comisaría de Tierra Santa de la provincia de la Inmaculada. A su vez, se han instalado las", "note": "Publicado el abril 2, 2024", "url": "https://revistatierrasanta.com/bendicion-del-icono-de-maria-inmaculada-en-beit-sahour/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/04/Bendicion-Maria-Inmaculada-768x711.jpg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "500-anos-de-la-evangelizacion-en-mexico-y-tu-dejarias-tu-casa-y-dejandolo-todo-lo-siguieron-lc-511", "title": "500 años de la Evangelización en México:  Y tú ¿dejarías tu casa? “Y dejándolo todo, lo siguieron” (Lc 5,11)", "author": "direccion", "year": 2024, "category": "2024", "summary": "“Marchad, carísimos, de dos en dos por las diversas partes de la tierra, anunciando a los hombres la paz y la penitencia para remisión de los pecados (…) Y ellos, inundados de gozo y alegría, se postraban en tierra ante Francisco en actitud de súplica, mientras recibían el mandato de la santa obediencia. Y Francisco", "note": "Publicado el mayo 25, 2024", "url": "https://revistatierrasanta.com/500-anos-de-la-evangelizacion-en-mexico-y-tu-dejarias-tu-casa-y-dejandolo-todo-lo-siguieron-lc-511/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/05/Los_doce_apostoles_de_Mexico-768x520.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "4772-2", "title": "Día del Peregrino 2024", "author": "direccion", "year": 2024, "category": "2024", "summary": "“Donde están dos o tres reunidos en mi nombre, allí estoy en medio de ellos” (Mt 18,20) Rafael Martínez Casado, OFS, presidente de la AEATS ¡Y nos volvimos a juntar! No podía ser de otra forma. No podíamos faltar a nuestra cita anual. Nuestro amor a Tierra Santa hace que tengamos fijo en nuestro calendario", "note": "Publicado el junio 5, 2024", "url": "https://revistatierrasanta.com/4772-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/06/IMG_4892-1024x768.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "1964-pablo-vi-visita-tierra-santa", "title": "1964: Pablo VI visita Tierra Santa", "author": "direccion", "year": 2024, "category": "2024", "summary": "El Papa Pablo VI fue el precursor de las peregrinaciones papales a Tierra Santa. Este hecho histórico se produjo del 4 al 6 de enero de 1964. Durante su visita y hora de oración en el Santo Sepulcro, el Santo Padre depositó una rama de olivo de oro (símbolo de reconciliación) en la tumba de", "note": "Publicado el enero 12, 2024", "url": "https://revistatierrasanta.com/1964-pablo-vi-visita-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2024/01/24161_g-768x572.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "xii-congreso-de-comisarios-y-vice-comisarios-latinoamericanos-de-tierra-santa", "title": "XII Congreso de Comisarios y Vice-comisarios latinoamericanos de Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Con el objetivo principal de actualizar y revitalizar el modo de vida y evangelización para continuar con el camino de la difusión de los Santos Lugares se ha celebrado, del 23 al 26 de agosto en la ciudad brasileña de Sao Paulo, el XII Congreso de Comisarios y Vice-comisarios latinoamericanos de Tierra Santa. A la", "note": "Publicado el agosto 24, 2023", "url": "https://revistatierrasanta.com/xii-congreso-de-comisarios-y-vice-comisarios-latinoamericanos-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/08/79e1eac9-439b-45ce-875b-a60f28ae9c95-1024x841.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "xi-congreso-de-estudios", "title": "XI Congreso de Estudios", "author": "direccion", "year": 2023, "category": "2023", "summary": "En la Escuela Superior de Estudios Franciscanos, ubicada en la localidad madrileña de El Pardo, va a tener lugar, el 20 y 21 de mayo, el XI Congreso de Estudios. En el marco de las celebraciones desarrolladas con motivo del VIII centenario, y bajo el título «Contemplar lo humano con los ojos De Francisco: De", "note": "Publicado el mayo 10, 2023", "url": "https://revistatierrasanta.com/xi-congreso-de-estudios/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/IMG_2085-1024x782.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "visita-del-patriarca-siro-ortodoxo-a-tierra-santa", "title": "El patriarca siro-ortodoxo visita Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Han pasado 58 años desde la última vez que un patriarca ortodoxo sirio pudo entrar en los Santos Lugares. El patriarca fue recibido por delegaciones de líderes y representantes de las diversas Iglesias, y por el presidente de la Alta Comisión Presidencial para Asuntos Eclesiásticos Palestino, en representación del presidente palestino. El 4 de mayo,", "note": "Publicado el mayo 11, 2023", "url": "https://revistatierrasanta.com/visita-del-patriarca-siro-ortodoxo-a-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/Visita-del-patriarca-Sirio-ortodoxo.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "ven-y-veras-el-viaje-de-tu-vida", "title": "Ven y verás: El viaje de tu vida", "author": "direccion", "year": 2023, "category": "2023", "summary": "El domingo 18 de junio se emitió en TVE 2 el programa matinal «Últimas preguntas» sobre Tierra Santa en el que participaron el responsable de la Custodia en España y vicecomisario de la Comisaría de Tierra Santa, fray Luis Quintana, y Noelia Ávila, directora de Peregrinaciones del Grupo Avoris (Halcón Peregrinaciones y Peregrinos Viajeros B-Travel).", "note": "Publicado el junio 19, 2023", "url": "https://revistatierrasanta.com/ven-y-veras-el-viaje-de-tu-vida/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/06/e4649efc-cadf-435b-8963-6010bf1feaa6-1024x626.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "una-grave-crisis-humanitaria", "title": "Crisis humanitaria en Gaza", "author": "direccion", "year": 2023, "category": "2023", "summary": "“Dios creó al hombre a su imagen” (Gen 1,27)Hoy, un comité de emergencia de los Patriarcas y Jefes de las Iglesias en Jerusalén se reunió para orar y consultar sobre la grave crisis humanitaria que nos ha afectado a todos.Nuestra querida Tierra Santa ha cambiado dramáticamente durante la semana pasada. Estamos siendo testigos de un", "note": "Publicado el octubre 13, 2023", "url": "https://revistatierrasanta.com/una-grave-crisis-humanitaria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/IMG_E0F99435CC15-1-1017x1024.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "tres-nuevo-novicios-siguen-la-senda-de-francisco", "title": "Tres nuevo novicios siguen la senda de San Francisco", "author": "direccion", "year": 2023, "category": "2023", "summary": "Tres novicios de la Custodia de Tierra Santa hicieron su primera profesión (votos temporales) a manos del Custodio de Tierra Santa, fray Francesco Patton. Se trata de fray Brutus Mualem, fray Deyvis Padilla Cervantes y fray José Luis Guaimas. La ceremonia, presidida por el padre Custodio, tuvo lugar el sábado 2 de septiembre en La Verna (Italia).", "note": "Publicado el septiembre 8, 2023", "url": "https://revistatierrasanta.com/tres-nuevo-novicios-siguen-la-senda-de-francisco/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/photo-2023-09-03-20-26-08_0.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "terremoto-en-turquia-y-siria", "title": "Terremoto en Turquía y Siria", "author": "gestor", "year": 2023, "category": "2023", "summary": "Paz y Bien. El pasado 6 de febrero Turquía y Siria sufrieron dos potentes sismos que afectaron, con nueve horas de diferencia, el sur y el centro de Turquía. Como resultados preliminares de ambos terremotos, más de 10.000 personas han muerto y más de 38.500 han resultado heridas.​ Desde la Comisaría de Tierra Santa os", "note": "Publicado el marzo 9, 2023", "url": "https://revistatierrasanta.com/terremoto-en-turquia-y-siria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/IMG-20230208-WA0000-768x1024.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "su-beatitud-pierbattista-pizzaballa-sera-nombrado-cardenal-el-30-de-septiembre", "title": "Su Beatitud Pierbattista Pizzaballa será nombrado cardenal el 30 de septiembre", "author": "direccion", "year": 2023, "category": "2023", "summary": "El Papa Francisco ha anunciado, el 9 de julio, la celebración de un nuevo consistorio el 30 de septiembre en el que nombrará a 21 nuevos cardenales. Entre ellos estará Su Beatitud Pierbattista Pizzaballa; primer franciscano en ser nombrado cardenal tras haber sido Custodio de Tierra Santa y, posteriormente, Patriarca Latino de Jerusalén. Pierbattista Pizzaballa", "note": "Publicado el julio 9, 2023", "url": "https://revistatierrasanta.com/su-beatitud-pierbattista-pizzaballa-sera-nombrado-cardenal-el-30-de-septiembre/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Pierbattista.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "su-beatitud-pierbattista-pizzaballa-nombrado-cardenal-titular-de-san-onofre", "title": "Su Beatitud Pierbattista Pizzaballa nombrado cardenal titular de San Onofre", "author": "direccion", "year": 2023, "category": "2023", "summary": "Durante el Consistorio ordinario celebrado en Roma, el 30 de septiembre y presidido por el papa Francisco, el Patriarca Latino de Jerusalén, Pierbattista Pizzaballa recibió las insignias cardenalicias. Además de la imposición del birrete y la entrega del anillo, el Sumo Pontífice asignó al nuevo cardenal el título de San Onofre, lo que le convierte", "note": "Publicado el septiembre 30, 2023", "url": "https://revistatierrasanta.com/su-beatitud-pierbattista-pizzaballa-nombrado-cardenal-titular-de-san-onofre/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/Pizaballa.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "sos-educacion-belen", "title": "SOS Educación Belén", "author": "gestor", "year": 2023, "category": "2023", "summary": "Hagamos un regalo a los niños de Belén. La Custodia de Tierra Santa administra 15 escuelas y otros centros educativos, que ofrecen educación escolar a alrededor de 12,000 estudiantes en todo el Medio Oriente, principalmente en Palestina, Siria y Jordania, pero también en Israel, Líbano y Chipre, donde además, abundan extranjeros subsaharianos, inmigrantes y refugiados. La", "note": "Publicado el marzo 10, 2023", "url": "https://revistatierrasanta.com/sos-educacion-belen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/sos-escuela-belen-768x498.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "sevilla-tambiacogen-las-ultimas-misas-por-la-paz-en-tierra-santa", "title": "Sevilla también celebra una  misa por la Paz en Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Sevilla acogió el día 30 la misa por la Paz. Antes de que diera comienzo la conferencia prevista para las 19.00 de la tarde, fray Alfonso García Araya, guardián de la fraternidad franciscana de San Buenaventura dio la bienvenida a fray Fadi Azar, párroco del Convento del Sagrado Corazón de Jesús en la ciudad siria", "note": "Publicado el octubre 31, 2023", "url": "https://revistatierrasanta.com/sevilla-tambiacogen-las-ultimas-misas-por-la-paz-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/PHOTO-2023-10-31-09-49-08-768x576.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "se-luz-para-una-familia", "title": "Sé  luz para una familia", "author": "direccion", "year": 2023, "category": "2023", "summary": "Gracias a la visita que ha realizado fray Fadi, párroco del Convento del Sagrado Corazón de Jesús, ubicado en Lattakiah (Siria) hemos podido conocer de primera mano las condiciones en las que miles de personas están viviendo actualmente. Uno de los principales problemas con los que se enfrentan diariamente es la falta de electricidad. Sólo", "note": "Publicado el octubre 27, 2023", "url": "https://revistatierrasanta.com/se-luz-para-una-familia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/PHOTO-2023-10-25-15-15-03-1024x576.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "santiago-de-compostela-acogera-la-exposicion-tesoros-reales-obras-maestras-del-museo-de-tierra-santa", "title": "Santiago de Compostela acogerá la exposición «Tesoros reales. Obras maestras del Museo de Tierra Santa»", "author": "direccion", "year": 2023, "category": "2023", "summary": "Desde el mes de marzo de 2024, Santiago de Compostela expondrá parte del tesoro histórico-artístico del Museo de Tierra Santa de Jerusalén, cuyas piezas fueron donadas por las casas reales europeas durante más de 500 años. En la exposición, los visitantes podrán contemplar, entre otras obras, joyas, baldaquinos cálices, códices o piezas litúrgicas y de", "note": "Publicado el diciembre 12, 2023", "url": "https://revistatierrasanta.com/santiago-de-compostela-acogera-la-exposicion-tesoros-reales-obras-maestras-del-museo-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/12/CdC_231212_022-1024x683.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "restauracion-del-campanario-de-emaus", "title": "Restauración del campanario de Emaús", "author": "direccion", "year": 2023, "category": "2023", "summary": "Nos hacemos eco de una noticia publicada desde la Comisaría de Tierra Santa de la provincia de la Inmaculada que trasladan la necesidad de los hermanos franciscanos de reparar las campanas, el reloj y la torre del campanario de la Iglesia de Emaús. El importe total de todos los arreglos asciende a 13.265,31€. Si deseas", "note": "Publicado el julio 5, 2023", "url": "https://revistatierrasanta.com/restauracion-del-campanario-de-emaus/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Unknown-768x431.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "primera-misa-por-la-paz-en-tierra-santa", "title": "Primera Misa por la Paz en Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "La primera de las Eucaristías por la Paz se ha celebrado en el Convento de la Anunciación, de las hermanas Clarisas de Madrid, que ha estado presidida por fray Fadi, párroco del Convento del Sagrado Corazón de Jesús, ubicado en la ciudad siria de Lattakiah. Por la tarde —y tras la inauguración y bendición por", "note": "Publicado el octubre 26, 2023", "url": "https://revistatierrasanta.com/primera-misa-por-la-paz-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/af50bf97-f44a-4d79-aeb8-39238188f798.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "pierbattista-pizzaballa-los-cristianos-en-tierra-santa-quieren-que-se-respeten-sus-derechos", "title": "Pierbattista Pizzaballa: Los cristianos en Tierra Santa quieren que se respeten sus derechos", "author": "direccion", "year": 2023, "category": "2023", "summary": "El Patriarca Latino de Jerusalén y cardenal electo Pierbattista Pizzaballa ha hablado para Vatican News sobre el aumento de los ataques contra los cristianos por parte de judíos ultraortodoxos . Asegura que los cristianos en Tierra Santa no quieren una protección especial, sólo que se garanticen sus derechos fundamentales. En sus declaraciones, el arzobispo confirmó", "note": "Publicado el julio 30, 2023", "url": "https://revistatierrasanta.com/pierbattista-pizzaballa-los-cristianos-en-tierra-santa-quieren-que-se-respeten-sus-derechos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Pierbattista-Pizzaballa.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "peregrinos", "title": "Continúan las peregrinaciones a Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Comisaría de Tierra Santa de la Provincia de la Inmaculada continúa organizando peregrinaciones a Tierra Santa. En esta ocasión, y durante estos días lo ha hecho el grupo más numeroso del año, con un total de 100 personas visitando Los Santos lugares. Si estás interesado en peregrinar a Tierra Santa y conocer las próximas", "note": "Publicado el septiembre 6, 2023", "url": "https://revistatierrasanta.com/peregrinos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/PHOTO-2023-09-06-14-15-37-5-1024x576.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "patriarcas-y-cabezas-de-iglesias-en-jerusalen-hacen-un-llamamiento-por-la-paz-y-la-justicia", "title": "Patriarcas y cabezas de Iglesias en Jerusalén hacen un llamamiento por la paz y la justicia", "author": "direccion", "year": 2023, "category": "2023", "summary": "Los Patriarcas y cabezas De la Iglesia en Jerusalén se unen en una llamada por La Paz y la justicia en medio de la violencia. Jerusalen, 7 de octubre de 2023 Tierra Santa, un lugar sagrado para millones de personas en todo el mundo está actualmente sumida en la violencia y el sufrimiento debido al", "note": "Publicado el octubre 8, 2023", "url": "https://revistatierrasanta.com/patriarcas-y-cabezas-de-iglesias-en-jerusalen-hacen-un-llamamiento-por-la-paz-y-la-justicia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/IMG_E0F99435CC15-1-1017x1024.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "nuevo-numero-de-la-revista-tierra-santa-2", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Ya está disponible el último número de la revista, correspondiente a los meses de noviembre y diciembre, cuyas páginas centrales están dedicadas a la Basílica de la Natividad de Constantino el Grande, el lugar exacto donde el Niño nació y fue visitado por los pastorcillos y los Reyes Magos. Aprenderemos qué hubo detrás de la", "note": "Publicado el octubre 29, 2023", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/Portada-no-72-2-929x1024.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "nuevo-numero-de-la-revista-tierra-santa", "title": "Nuevo número de la Revista Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Ya está disponible el último número de la revista, correspondiente a los meses de septiembre y octubre, cuyas páginas centrales están dedicadas a la Exaltación de la Santa Cruz, cuya festividad se celebró el 14 de septiembre. También dedicamos unas páginas a la próxima Bendición e inauguración de la Capilla de la Inmaculada en el", "note": "Publicado el septiembre 15, 2023", "url": "https://revistatierrasanta.com/nuevo-numero-de-la-revista-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/Imagen-1-768x817.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "nuevo-hallazgo-en-magdala-frasco-de-perfume", "title": "Nuevo hallazgo en Magdala: frasco de perfume", "author": "direccion", "year": 2023, "category": "2023", "summary": "En la localización bíblica de Magdala (excavaciones de la Custodia de Tierra Santa, franciscanos) están de enhorabuena. Ayer, 22 de junio, fue un gran día para las excavaciones arqueológicas. Han encontrado un frasco, como el que María Magdalena utilizó cuando fue a ungir el cuerpo del Señor la mañana de la Resurrección, cuando se encontró", "note": "Publicado el junio 23, 2023", "url": "https://revistatierrasanta.com/nuevo-hallazgo-en-magdala-frasco-de-perfume/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/06/WhatsApp-Image-2023-06-22-at-19.52.07-1024x768.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "ninos-y-jovenes-de-la-escuela-terra-sancta-en-jerusalen-piden-por-la-paz", "title": "Niños y jóvenes de la escuela Terra Sancta, en Jerusalén, piden por La Paz", "author": "direccion", "year": 2023, "category": "2023", "summary": "Niños y jóvenes estudiantes de la escuela de secundaria Terra Sancta, en Jerusalén fueron los protagonistas de la jornada en la que rezaron por la paz en Tierra Santa. Todos ellos pidieron unidos a Dios el regalo de la paz, pero también a los gobernantes. Paz para todos. Paz para su tierra, para sus compañeros", "note": "Publicado el noviembre 7, 2023", "url": "https://revistatierrasanta.com/ninos-y-jovenes-de-la-escuela-terra-sancta-en-jerusalen-piden-por-la-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/11/IMG_0590-1024x671.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "misas-por-la-paz-en-tierra-santa", "title": "Misas por la Paz en Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Comisaría de Tierra Santa de la provincia de la Inmaculada (franciscanos) y el Centro de Tierra Santa, en Madrid, han organizado siete Misas por la Paz en Tierra Santa en diferentes localidades españolas, con ocasión de la visita de fray Fadi Azar, párroco del Convento del Sagrado Corazón de Jesús, ubicado en la ciudad", "note": "Publicado el octubre 18, 2023", "url": "https://revistatierrasanta.com/misas-por-la-paz-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/IMG_9958-1-1024x567.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "misa-y-dos-conferencias-por-la-paz-en-madrid", "title": "Misa y dos conferencias por la Paz en Madrid", "author": "direccion", "year": 2023, "category": "2023", "summary": "El viernes, 27 de octubre, la jornada comenzó en Madrid con un encuentro con universitarios en el colegio mayor Jaime del Amo, donde fray Fadi, párroco del Convento del Sagrado Corazón de Jesús en Lattakiah (Siria), expuso la importancia de la oración por la paz en Tierra Santa, habló de la situación que están viviendo", "note": "Publicado el octubre 28, 2023", "url": "https://revistatierrasanta.com/misa-y-dos-conferencias-por-la-paz-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/PHOTO-2023-10-27-18-22-00-768x576.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "misa-por-la-paz-en-la-catedral-de-valencia", "title": "Misa por la Paz en la Catedral de Valencia", "author": "direccion", "year": 2023, "category": "2023", "summary": "El día 26 de octubre, Valencia acogió la celebración de la Misa por la Paz en Tierra Santa. Los actos comenzaron a las 18.00 en el Salón del Arzobispado. Allí, los asistentes pudieron escuchar a fray Luis Quintana, vicecomisario de la Comisaría de Tierra Santa de la Provincia de la Inmaculada, y la conferencia ofrecida", "note": "Publicado el octubre 27, 2023", "url": "https://revistatierrasanta.com/misa-por-la-paz-en-la-catedral-de-valencia/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/82ab4e05-0f3f-4703-b76b-7133e5fe0682-1024x768.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "los-franciscanos-rezan-por-la-paz-en-madrid", "title": "Los franciscanos rezan por la Paz en Madrid", "author": "direccion", "year": 2023, "category": "2023", "summary": "La última de las siete misas celebradas en España pidiendo por La Paz en Tierra Santa se realizó en la parroquia Cristo de La Paz, en Madrid. A las 6 de la tarde fray Fadi Azar, párroco del Convento del Sagrado Corazón de Jesús ubicado en la ciudad siria de Lattakiah, y Fray Luis Quintana,", "note": "Publicado el noviembre 1, 2023", "url": "https://revistatierrasanta.com/los-franciscanos-rezan-por-la-paz-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/11/IMG_0401-1024x768.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "las-ruinas-prehistoricas-de-jerico-declaradas-patrimonio-de-la-humanidad", "title": "Las ruinas prehistóricas de Jericó declaradas Patrimonio de la Humanidad", "author": "direccion", "year": 2023, "category": "2023", "summary": "Las ruinas prehistóricas de Tel es-Sultán, situadas a dos kilómetros de la ciudad de Jericó, han sido declaradas por la Unesco Patrimonio Mundial de la Humanidad. Los 21 miembros del comité aprobaron, el 17 de septiembre, de forma unánime la incorporación de este lugar en la convención anual celebrada en Riad (Marruecos). De esta forma,", "note": "Publicado el septiembre 19, 2023", "url": "https://revistatierrasanta.com/las-ruinas-prehistoricas-de-jerico-declaradas-patrimonio-de-la-humanidad/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/Tell_es-Sultan_Jericho_Palestine2-1024x697.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "la-presencia-franciscana-en-el-monte-nebo-cumple-90-anos", "title": "La presencia franciscana en el Monte Nebo cumple 90 años", "author": "direccion", "year": 2023, "category": "2023", "summary": "La comunidad franciscana del Monte Nebo (Jordania) cumple 90 años. Los primeros frailes de la Custodia de Tierra Santa se establecieron en la zona el 13 de julio de 1933, tras haber comprado el terreno a los beduinos. Los dirigía Girolamo Mihaic, “abuna Germana”. Según la tradición, en este lugar Moisés vio la Tierra Prometida – aunque", "note": "Publicado el julio 21, 2023", "url": "https://revistatierrasanta.com/la-presencia-franciscana-en-el-monte-nebo-cumple-90-anos/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Monte-Nebo.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-orden-del-santo-sepulcro-organiza-para-el-periodo-estival-campos-de-trabajo-en-tierra-santa", "title": "La Orden del Santo Sepulcro organiza, para el periodo estival, campos de trabajo en Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Lugartendencia de España Occidental de la Orden de Caballería del Santo Sepulcro organiza en Tierra Santa, del 14 al 31 de julio, diversos campos de trabajo en Israel y Palestina (Belén). Durante dos semanas los asistentes podrán realizar uno de estos proyectos: uno de ellos centrado en el cuidado, mantenimiento y limpieza de los", "note": "Publicado el mayo 9, 2023", "url": "https://revistatierrasanta.com/la-orden-del-santo-sepulcro-organiza-para-el-periodo-estival-campos-de-trabajo-en-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/Orden-Santo-Sepulcro-Campo-de-Trabajo-e1683658629586-1024x803.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-marcha-franciscana-en-tierra-santa-bajo-el-lema-hoy-estaras-conmigo-en-el-paraiso", "title": "La Marcha Franciscana en Tierra Santa, bajo el lema «Hoy estarás conmigo en el paraíso»", "author": "direccion", "year": 2023, "category": "2023", "summary": "A finales de agosto, del 20 al 27, numerosos jóvenes llegados desde distintas partes de Tierra Santa (Belén, Ramala, Nazaret, Haifa, Alta Galilea) y acompañados por un grupo de frailes y hermanas, participaron en la trigésimo segunda edición de la Marcha Franciscana, que este año se ha celebrado bajo el título «Hoy estarás conmigo en", "note": "Publicado el septiembre 4, 2023", "url": "https://revistatierrasanta.com/la-marcha-franciscana-en-tierra-santa-bajo-el-lema-hoy-estaras-conmigo-en-el-paraiso/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/IMG_8666.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "la-familia-franciscana-celebra-la-festividad-de-san-francisco-de-asis", "title": "La familia franciscana celebra la festividad de San Francisco de Asís", "author": "direccion", "year": 2023, "category": "2023", "summary": "Hoy celebramos la festividad de San Francisco de Asís, fundador de la Orden franciscana, y la comunidad cristiana local ha querido sumarse a las celebraciones en el Santuario de Betgafé.", "note": "Publicado el octubre 4, 2023", "url": "https://revistatierrasanta.com/la-familia-franciscana-celebra-la-festividad-de-san-francisco-de-asis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/WhatsApp-Image-2023-10-04-at-19.47.07-768x1024.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "la-custodia-celebra-por-primera-vez-la-festividad-de-maria-magdalena-en-magdala", "title": "La Custodia celebra por primera vez la festividad de María Magdalena en Magdala", "author": "direccion", "year": 2023, "category": "2023", "summary": "La comunidad franciscana de la Custodia de Tierra Santa ha celebrado, el 22 de julio, la festividad de María Magdalena precisamente en Magdala, su lugar de nacimiento, concretamente en el santuario franciscano. La solemne presentación estuvo presidida por el Custodio, p. Francesco Patton, , quien señaló que «Magdalena acompaña a Jesús a Jerusalén y mientras", "note": "Publicado el julio 22, 2023", "url": "https://revistatierrasanta.com/la-custodia-celebra-por-primera-vez-la-festividad-de-maria-magdalena-en-magdala/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/WhatsApp-Image-2023-07-22-at-17.22.23-1-1024x682.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "la-cofradia-e-la-vera-cruz-de-valladolid-entrega-al-centro-tierra-santa-un-donativo", "title": "La Cofradía de la Vera Cruz de Valladolid entrega al Centro Tierra Santa un donativo", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Cofradía Penitencial de la Santa Vera Cruz de Valladolid hizo entrega al Centro de Tierra Santa, representado por su director Fray Luis Quintana, de un cheque por un importe de 6.480€.El acto, desarrollado el 15 de septiembre, festividad de Nuestra Señora de los Dolores, comenzó con la entrega de medallas a los más de", "note": "Publicado el septiembre 17, 2023", "url": "https://revistatierrasanta.com/la-cofradia-e-la-vera-cruz-de-valladolid-entrega-al-centro-tierra-santa-un-donativo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/WhatsApp-Image-2023-09-16-at-19.03.27-768x1024.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "la-cena-la-pones-tu", "title": "La cena la pones tú", "author": "direccion", "year": 2023, "category": "2023", "summary": "Llega la Navidad, tiempo del nacimiento del Mesías en una cueva de Belén. Pero estamos viendo cómo nuestra sociedad llama Navidad al día de la lotería del 22 de diciembre, al encendido de luces, al turrón o la «magia» de personajes infantiles… Tampoco nos olvidamos de las grandes cenas de empresa que durante las dos", "note": "Publicado el noviembre 30, 2023", "url": "https://revistatierrasanta.com/la-cena-la-pones-tu/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/11/Unknown.jpeg", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "jornada-mundial-de-la-juventud", "title": "Jornada Mundial de la Juventud", "author": "direccion", "year": 2023, "category": "2023", "summary": "Frailes franciscanos de Tierra Santa van a acompañar a jóvenes españoles durante la Jornada Mundial de la Juventud (JMJ), que se celebrará en Lisboa del 1 al 6 de agosto. Muchos de ellos, y desde sus parroquias de origen, llevan meses vendiendo papeletas —en las que se sortea una peregrinación a Italia, cortesía de Halcón", "note": "Publicado el junio 16, 2023", "url": "https://revistatierrasanta.com/jornada-mundial-de-la-juventud/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/06/6ab5fa6b-39c8-4e03-99d7-30b32ad0bc52-768x1024.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "indulgencia-plenaria-en-iglesias-franciscanas", "title": "Indulgencia plenaria en Iglesias franciscanas", "author": "direccion", "year": 2023, "category": "2023", "summary": "Con motivo del octavo centenario de la «Navidad de Greccio», el Santo Padre ha concedido la indulgencia plenaria a todos los fieles que, desde el 8 de diciembre de 2023 (Solemnidad de la Inmaculada Concepción de la Santísima Virgen María) hasta el 2 de febrero de 2024 (Fiesta de la Presentación al Templo de Nuestro", "note": "Publicado el octubre 29, 2023", "url": "https://revistatierrasanta.com/indulgencia-plenaria-en-iglesias-franciscanas/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/IMG_0334-769x1024.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "gran-asistencia-al-dia-del-peregrino", "title": "Gran asistencia al Día del Peregrino", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Asociación Española de Amigos de Tierra Santa y la Comisaría de Tierra Santa han celebrado, el 27 de mayo, el Día del Peregrino. Los actos comenzaron a primera hora de la mañana en el colegio San Buenaventura de Madrid, con la bienvenida de fray Luis Quintana. Los asistentes —que llegaron desde todos los rincones", "note": "Publicado el mayo 28, 2023", "url": "https://revistatierrasanta.com/gran-asistencia-al-dia-del-peregrino/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/IMG_2631-1024x634.jpg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "fray-toni-choucry-economo-de-la-custodia-de-tierra-santa-visita-espana", "title": "Fray Toni Choucry, ecónomo de la Custodia de Tierra Santa, visita España", "author": "direccion", "year": 2023, "category": "2023", "summary": "Nada más aterrizar en Madrid el 19 de noviembre, fray Toni —junto con fray Luis Quintana, vicecomisario de Tierra Santa en Madrid, y con Rafael Martínez, presidente de la Asociación Española de Amigos de Tierra Santa— se desplazó hasta Toledo donde ofreció, en la Casa de Ejercicios del Buen Pastor, una conferencia en la que", "note": "Publicado el noviembre 21, 2023", "url": "https://revistatierrasanta.com/fray-toni-choucry-economo-de-la-custodia-de-tierra-santa-visita-espana/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/11/986-070-1024x683.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "fray-hanna-jallouf-ordenado-obispo-en-siria", "title": "Fray Hanna Jallouf ordenado obispo en Siria", "author": "direccion", "year": 2023, "category": "2023", "summary": "Por primera vez, la Iglesia católica en Siria ha ordenado obispo de los católicos del rito latino del país a uno de sus «hijos», Fray Hanna Jallouf. Con su ordenación, el nuevo obispo asume también el cargo de Vicario Apostólico Latino de Alepo. La celebración estuvo presidida por Monseñor Claudio Gugerotti (próximo cardenal), prefecto del", "note": "Publicado el septiembre 18, 2023", "url": "https://revistatierrasanta.com/fray-hanna-jallouf-ordenado-obispo-en-siria/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/hanna_jallouf_ordination_web.jpeg", "color": "#D9C9A3", "type": "#2A1D0E", "art": "#6E3B23", "motif": "grid"}, {"id": "franciscanos-espanoles-realizan-ejercicios-espirituales-en-tierra-santa-2", "title": "Franciscanos españoles realizan ejercicios espirituales en Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "La provincia franciscana de la Inmaculada y la Comisaría de Tierra Santa han organizado unos ejercicios espirituales en Tierra Santa del 16 al 21 de junio. Un grupo formado por diecisiete franciscanos españoles —11 de la provincia de la Inmaculada, cinco franciscanos conventuales y un franciscano de la provincia de Nuestra Señora de Aranzazu— han", "note": "Publicado el junio 20, 2023", "url": "https://revistatierrasanta.com/franciscanos-espanoles-realizan-ejercicios-espirituales-en-tierra-santa-2/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/06/IMG_3437.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "exposicion-bajo-el-cielo-de-oriente-un-viaje-en-el-tiempo", "title": "Exposición «Bajo el cielo de Oriente. Un viaje en el tiempo»", "author": "direccion", "year": 2023, "category": "2023", "summary": "El Centro Sefarad-Israel, ubicado en Madrid, acogerá el próximo 8 de junio, la exposición «Bajo el cielo de Oriente. Un viaje en el tiempo», donde se presentarán videos documentales sobre las expediciones españolas a Jerusalén. La presentación, que tendrá lugar a las 18.00 h, correrá a cargo de Maria Luz Mangado Alonso, historiadora especializada en", "note": "Publicado el mayo 24, 2023", "url": "https://revistatierrasanta.com/exposicion-bajo-el-cielo-de-oriente-un-viaje-en-el-tiempo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/Exposicion-videos-1024x1024.jpg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "eucaristia-y-conferencia-para-conmemorar-el-ano-lebaniego", "title": "Jornada solidaria en favor de los cristianos de Tierra Santa", "author": "direccion", "year": 2023, "category": "2023", "summary": "Dentro de los actos celebrados con motivo del Año Lebaniego, la parroquia de Santa Cruz de Bezana (Cantabria) ha celebrado, el 27 de abril, una Jornada solidaria en favor de los cristianos de Tierra Santa. El acto comenzó con una Eucaristía por Tierra Santa y sus necesidades, que fue presidida por fray Luis Quintana, representante", "note": "Publicado el mayo 1, 2023", "url": "https://revistatierrasanta.com/eucaristia-y-conferencia-para-conmemorar-el-ano-lebaniego/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/Unknown-2-1024x768.jpeg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "encuentro-del-grupo-de-apoyo-de-tierra-santa-en-ciudad-real", "title": "Encuentro del Grupo de Apoyo a Tierra Santa en Ciudad Real", "author": "direccion", "year": 2023, "category": "2023", "summary": "El pasado 6 de octubre, Fray Luis Quintana (director del Centro Tierra Santa) y D. Rafael Martínez (presidente de la Asociación Española Amigos de Tierra Santa, AEATS) visitaron en Ciudad Real al Grupo de Apoyo a Tierra Santa, (GATS) con quienes hablaron, rezaron y compartieron un ágape fraterno. También aprovecharon hacer una generosa colecta entre", "note": "Publicado el octubre 7, 2023", "url": "https://revistatierrasanta.com/encuentro-del-grupo-de-apoyo-de-tierra-santa-en-ciudad-real/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/IMG20231006192124-1024x461.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "eleccion-del-custodio-de-tierra-santa", "title": "Elección del Custodio de Tierra Santa", "author": "gestor", "year": 2023, "category": "2023", "summary": "El 29 de abril de 2022, Fr. Julio César Bunader, ofm, Visitador general, ha anunciado a todos los hermanos de la Custodia de Tierra Santa, que el Rvdo. Padre Fr. Massimo Fusarelli ofm, Ministro general de la Orden de los Frailes Menores, con Carta del 25 de abril de 2022, ha comunicado que fray Francesco", "note": "Publicado el marzo 9, 2023", "url": "https://revistatierrasanta.com/eleccion-del-custodio-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/fray-patton-elegido-para-un-nuevo-mandato-como-custodio-de-tierra-santa-PSQS.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "el-viaje-de-miles-de-kilometros-para-encontrarte-a-ti-mismo", "title": "El viaje de miles de kilómetros para encontrarte a ti mismo", "author": "gestor", "year": 2023, "category": "2023", "summary": "Paz y Bien. Eugenio Camacho, periodista y peregrino a Tierra Santa en enero del 2023, nos relata su experiencia: «Peregrinar a Tierra Santa supone un punto de inflexión. Un reseteo muy recomendable en medio de la maravillosa aventura de la vida». Expone que todo cristiano debería visitar Tierra Santa una vez en la vida. De la misma", "note": "Publicado el marzo 13, 2023", "url": "https://revistatierrasanta.com/el-viaje-de-miles-de-kilometros-para-encontrarte-a-ti-mismo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/image-768x576.png", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "el-padre-fadi-visita-madrid", "title": "El padre Fadi visita Madrid", "author": "direccion", "year": 2023, "category": "2023", "summary": "El padre Fadi, fraile franciscano jordano que actualmente reside en la ciudad siria de Latakia, ha visitado Madrid para dar una charla, el 20 de mayo, en la parroquia Santo Cristo de la Misericordia, ubicada en la localidad de Boadilla del Monte. Allí, fray Fadi pudo exponer a los asistentes la situación actual en Siria", "note": "Publicado el mayo 21, 2023", "url": "https://revistatierrasanta.com/el-padre-fadi-visita-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/Unknown-3-768x1024.jpeg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "el-custodio-de-tierra-santa-nos-ha-visitado-en-madrid", "title": "El custodio de Tierra Santa nos ha visitado en Madrid", "author": "gestor", "year": 2023, "category": "2023", "summary": "Paz y Bien. El p. Custodio, fr. Francesco Patton, nos ha visitado en la Parroquia Cristo de la Paz (21 febrero) y en la Parroquia Santo Cristo de la Misericordia (22 febrero), acompañado en las dos ocasiones por fr. Silvio de la Fuente, coordinador de los Comisarios de Tierra Santa, y fr. Luis Quintana, representante del Custodio en España. En la parroquia", "note": "Publicado el marzo 13, 2023", "url": "https://revistatierrasanta.com/el-custodio-de-tierra-santa-nos-ha-visitado-en-madrid/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/IMG_20230221_194217-1024x768.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "el-christian-informacion-center-celebra-su-50-aniversario", "title": "El Christian Información Center celebra su 50 aniversario", "author": "direccion", "year": 2023, "category": "2023", "summary": "El día 23, los actos se realizaran para personas de habla inglesa y otras iglesias, mientras que el 24 será en italiano y estará destinado a la Custodia, frailes y sacerdotes de la Iglesia Católica. Los actos comenzarán con un discurso de bienvenida. A continuación se hará una presentación de la historia y principales actividades", "note": "Publicado el mayo 12, 2023", "url": "https://revistatierrasanta.com/el-christian-informacion-center-celebra-su-50-aniversario/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/IMG_2125-768x488.jpg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "dia-de-ayuno-y-oracion-por-la-paz", "title": "Jornada de ayuno y oración por la paz", "author": "direccion", "year": 2023, "category": "2023", "summary": "El cardenal Pierbattista Pizzaballa, patriarca latino de Jerusalén, en nombre de los ordinarios de Tierra Santa, invita a las parroquias y comunidades religiosas a una jornada de ayuno y oración por la paz y la reconciliación que se realizará el martes 17 de octubre. Los momentos de oración se organizarán con adoración eucarística y el", "note": "Publicado el octubre 11, 2023", "url": "https://revistatierrasanta.com/dia-de-ayuno-y-oracion-por-la-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/Jornada-por-la-paz-1024x682.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "declaracion-sobre-la-conmemoracion-por-parte-de-los-palestinos-de-al-nakba", "title": "Declaración sobre la conmemoración por parte de los palestinos de “Al-Nakba”", "author": "direccion", "year": 2023, "category": "2023", "summary": "Reconociendo la conmemoración de nuestras comunidades del 75 aniversario de la “Al-Nakba”, junto con la de sus hermanos palestinos, el Consejo de Patriarcas y Jefes de las Iglesias en Jerusalén reitera el llamado de las Iglesias a luchar por una paz justa y duradera para nuestra tierra, la Tierra Santa. Nuestra fe nos enseña que", "note": "Publicado el mayo 16, 2023", "url": "https://revistatierrasanta.com/declaracion-sobre-la-conmemoracion-por-parte-de-los-palestinos-de-al-nakba/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/patriarchs_and_heads_of_the_churches_in_jerusalem.jpg.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "comunicado-sobre-los-trabajos-de-excavacion-en-la-zona-frente-al-ediculo-del-santo-sepulcro", "title": "Comunicado sobre los trabajos de excavación en la zona frente al Edículo del Santo Sepulcro", "author": "direccion", "year": 2023, "category": "2023", "summary": "El 7 de julio se publicó el Comunicado sobre los trabajos de excavación en el área frente al Edículo del Santo Sepulcro en Jerusalén, editado por la Prof. Francesca Romana Stasolla del Departamento de Antigüedades de la Universidad de Roma Sapienza. «Los trabajos de excavación en el área inmediatamente frente al Edículo, en el complejo", "note": "Publicado el julio 7, 2023", "url": "https://revistatierrasanta.com/comunicado-sobre-los-trabajos-de-excavacion-en-la-zona-frente-al-ediculo-del-santo-sepulcro/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Fig.-3-Crediti-Archivio-Sapienza-Universita-di-Roma-2-915x1024.jpg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "comunicado-del-patriarcado-latino-de-jerusalen", "title": "Comunicado del Patriarcado Latino de Jerusalén", "author": "direccion", "year": 2023, "category": "2023", "summary": "«El ciclo de violencia que ha matado a numerosos palestinos e israelíes en los últimos meses ha estallado esta mañana, sábado, 7 de octubre de 2023.Asistimos a una repentina explosión de violencia que preocupa mucho por su extensión e intensidad. La operación lanzada desde Gaza y la reacción del ejército israelí nos están devolviendo a", "note": "Publicado el octubre 7, 2023", "url": "https://revistatierrasanta.com/comunicado-del-patriarcado-latino-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/final.jpg", "color": "#C9A35B", "type": "#241B10", "art": "#1E2A22", "motif": "orbit"}, {"id": "comunicado-de-la-orden-de-los-franciscanos-menores", "title": "Comunicado de la Orden de los Franciscanos Menores", "author": "direccion", "year": 2023, "category": "2023", "summary": "La Orden de los Frailes Menores está presente en los Santos Lugares desde hace ocho siglos y, junto con los santuarios, preserva también el vínculo con los pueblos que habitan esa tierra. La actual situación de violencia y guerra nos entristece profundamente, nos preocupa por la suerte de las personas que allí viven y hace", "note": "Publicado el octubre 9, 2023", "url": "https://revistatierrasanta.com/comunicado-de-la-orden-de-los-franciscanos-menores/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/Jeru.png", "color": "#B5322B", "type": "#F6E9C7", "art": "#241B10", "motif": "wave"}, {"id": "comida-solidaria-en-favor-de-tierra-santa", "title": "Comida solidaria en favor de Tierra Santa", "author": "gestor", "year": 2023, "category": "2023", "summary": "Paz y Bien. El grupo parroquial «Sobre el Mar de Galilea» de la Parroquia Perpetuo Socorro de Badajoz cuyo párroco es Pedro Alberto Delgado, organiza para el próximo sábado 25 de marzo en el Hotel Río, una comida solidaria para recaudar fondos para paliar la situación en la que se encuentran las comunidades cristianas de Tierra Santa. Las entradas para esta comida se", "note": "Publicado el marzo 11, 2023", "url": "https://revistatierrasanta.com/comida-solidaria-en-favor-de-tierra-santa/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/03/IMG-20230308-WA0004-1024x791.jpeg", "color": "#14120E", "type": "#C9A35B", "art": "#B5322B", "motif": "sun"}, {"id": "ceremonia-de-graduacion-en-el-colegio-nuestra-senora-del-pilar-de-jerusalen", "title": "Ceremonia de graduación en el Colegio Nuestra Señora del Pilar de Jerusalén", "author": "direccion", "year": 2023, "category": "2023", "summary": "El Colegio de Nuestra Señora del Pilar de Jerusalén ha celebrado, el 20 de mayo, la ceremonia de graduación de la cuadragésimo quinta promoción de estudiantes. Durante el acto, y después de los himnos y de los saludos de bienvenida, las alumnas del colegio obsequiaron a los asistentes con actuaciones musicales, incluidas canciones y bailes,", "note": "Publicado el mayo 22, 2023", "url": "https://revistatierrasanta.com/ceremonia-de-graduacion-en-el-colegio-nuestra-senora-del-pilar-de-jerusalen/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/05/image-1024x768.jpeg", "color": "#6E3B23", "type": "#F2EBDD", "art": "#D9BF8C", "motif": "split"}, {"id": "celebramos-la-festividad-de-san-ignacio-de-loyola", "title": "Celebramos la festividad de San Ignacio de Loyola", "author": "direccion", "year": 2023, "category": "2023", "summary": "", "note": "Publicado el julio 31, 2023", "url": "https://revistatierrasanta.com/celebramos-la-festividad-de-san-ignacio-de-loyola/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/07/Unknown-5-e1690791398731.jpeg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "celebracion-del-dia-del-peregrino", "title": "Celebración del Día del Peregrino", "author": "direccion", "year": 2023, "category": "2023", "summary": "El colegio San Buenaventura (Madrid) acogerá, el 27 de mayo, el Día del Peregrino. Durante la jornada, los asistentes disfrutarán de un ambiente distendido donde podrás visitar los diferentes stands preparados para la ocasión: Uno de Amigos de Tierra Santa —podrán adquirir recuerdos de Tierra Santa como rosarios, agua del Jordán, aceites, libros y otro", "note": "Publicado el abril 28, 2023", "url": "https://revistatierrasanta.com/celebracion-del-dia-del-peregrino/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/04/PHOTO-2023-04-26-17-10-55-1024x758.jpg", "color": "#2A3B3A", "type": "#E8DFC4", "art": "#C9A35B", "motif": "steps"}, {"id": "carta-a-toda-la-diocesis", "title": "Carta a toda la Diócesis", "author": "direccion", "year": 2023, "category": "2023", "summary": "Estimados hermanos y hermanas, ¡Que el Señor les dé la paz! Estamos atravesando uno de los períodos más difíciles y dolorosos de nuestra historia reciente. Desde hace más de dos semanas, nos inundan imágenes de horror, que han despertado antiguos traumas, abierto nuevas heridas y hecho estallar el dolor, la frustración y la rabia dentro", "note": "Publicado el octubre 24, 2023", "url": "https://revistatierrasanta.com/carta-a-toda-la-diocesis/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/Patriarca.jpeg", "color": "#1E2A22", "type": "#F2EBDD", "art": "#C9A35B", "motif": "sun"}, {"id": "burgos-y-santo-toribio-de-liebana-tambien-piden-por-la-paz", "title": "Burgos y Santo Toribio de Liébana piden por la Paz", "author": "direccion", "year": 2023, "category": "2023", "summary": "Durante el fin de semana (28 y 29 de octubre) las Misas ofrecidas por la Paz en Tierra Santa se han enmarcado dentro de la Peregrinación a Santo Toribio de Liébana, organizada por la Asociación Española de Amigos de Tierra Santa, a la que también asisten fieles de la parroquia Cristo de la Paz (Madrid)", "note": "Publicado el octubre 29, 2023", "url": "https://revistatierrasanta.com/burgos-y-santo-toribio-de-liebana-tambien-piden-por-la-paz/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/10/PHOTO-2023-10-28-19-22-38-2-576x1024.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}, {"id": "aniversario-de-la-casa-del-fanciullo", "title": "Aniversario de la fundación de la Casa del Fanciullo", "author": "direccion", "year": 2023, "category": "2023", "summary": "Ya han pasado 16 años desde la fundación de la Casa del Niño en Belén. Es un lugar de acogida donde a fuerza del amor y la fe se curan las heridas de las familias, para que niños y jóvenes encuentren un refugio seguro y un hogar lleno de calidez. Para conmemorar esta fecha tan", "note": "Publicado el septiembre 14, 2023", "url": "https://revistatierrasanta.com/aniversario-de-la-casa-del-fanciullo/", "cover": "https://revistatierrasanta.com/wp-content/uploads/2023/09/A©-Nadim-Asfour_CTS_130921_6819-1024x681.jpg", "color": "#EADFC4", "type": "#241B10", "art": "#9C6B30", "motif": "orbit"}]};